const e=[{id:"q-ex01-01",examNumber:1,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"Which TWO of the following are fundamental principles of British life? (Choose TWO)",options:["Democracy","Guaranteed free car ownership","The rule of law","Compulsory membership of a trade union"],correctIndices:[0,2],explanation:"The five fundamental principles of British life are democracy, the rule of law, individual liberty, tolerance of those with different faiths and beliefs, and participation in community life.",memoryHook:'Acronym "DR. LIT": Democracy, Rule of law, Liberty, Involvement in community, Tolerance.'},{id:"q-ex01-02",examNumber:1,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"How many questions are there in the official Life in the UK Test?",options:["18","20","24","30"],correctIndices:[2],explanation:"The official Life in the UK Test consists of 24 questions based on the official handbook, Life in the United Kingdom: A Guide for New Residents.",memoryHook:"24 hours in a day = 24 questions on the test."},{id:"q-ex01-03",examNumber:1,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"During a UK citizenship ceremony, to whom do new citizens swear or affirm the Oath of Allegiance?",options:["His Majesty King Charles III, His Heirs and Successors","The Prime Minister and Cabinet","The Speaker of the House of Commons","The Archbishop of Canterbury"],correctIndices:[0],explanation:"At a citizenship ceremony, new British citizens swear or affirm allegiance to the reigning Monarch: His Majesty King Charles III, His Heirs and Successors, according to law."},{id:"q-ex01-04",examNumber:1,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Which countries make up Great Britain?",options:["England, Scotland, Wales, and Northern Ireland","England, Scotland, and Wales only","England, Wales, and the Republic of Ireland","England and Scotland only"],correctIndices:[1],explanation:'"Great Britain" refers only to the island comprising England, Scotland, and Wales. Adding Northern Ireland forms the United Kingdom of Great Britain and Northern Ireland.',memoryHook:'Look at the full official name: "The United Kingdom of [Great Britain] and [Northern Ireland]". Because Northern Ireland comes after "and", it is not part of Great Britain.',visualId:"uk-map"},{id:"q-ex01-05",examNumber:1,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"What is the national flower of England?",options:["The Thistle","The Daffodil","The Shamrock","The Tudor Rose"],correctIndices:[3],explanation:"The national flower of England is the Rose (specifically the red-and-white Tudor Rose). Scotland has the thistle, Wales has the daffodil, and Northern Ireland has the shamrock.",visualId:"national-emblems"},{id:"q-ex01-06",examNumber:1,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"How did the very first people who lived in Britain during the Stone Age survive?",options:["They were industrial ironworkers","They imported grain from the Roman Empire","They lived in walled stone castles","They were hunter-gatherers who followed herds of deer and horses"],correctIndices:[3],explanation:"The first people to live in Britain during the Stone Age were hunter-gatherers who hunted wild animals such as deer and horses and gathered seasonal food.",visualId:"history-timeline"},{id:"q-ex01-07",examNumber:1,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Where is Skara Brae, the best-preserved prehistoric village in northern Europe, located?",options:["Wiltshire, in south-west England","Orkney, off the north coast of Scotland","Snowdonia, in north Wales","County Antrim, in Northern Ireland"],correctIndices:[1],explanation:"Skara Brae on Orkney, off the north coast of Scotland, is the best-preserved prehistoric Stone Age village in northern Europe, helping archaeologists understand how people lived near the end of the Stone Age.",memoryHook:'"Brae" is a Scots word for hillside (as in "banks and braes"), anchoring Skara Brae to Scotland (Orkney).',visualId:"history-timeline"},{id:"q-ex01-08",examNumber:1,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"In AD 43, which Roman Emperor led a successful invasion of Britain?",options:["Julius Caesar","Emperor Hadrian","Emperor Augustus","Emperor Claudius"],correctIndices:[3],explanation:"After Julius Caesar’s failed invasion in 55 BC, Emperor Claudius led the Roman army in a successful invasion in AD 43, beginning nearly 400 years of Roman rule in Britain.",memoryHook:"Exam trap: Julius Caesar was never an emperor and his 55 BC invasion failed. Emperor CL-audius CL-inched the conquest in AD 43.",visualId:"history-timeline"},{id:"q-ex01-09",examNumber:1,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Who led missionaries from Rome to spread Christianity in southern Britain and became the first Archbishop of Canterbury?",options:["St Columba","St Patrick","St Augustine","St Andrew"],correctIndices:[2],explanation:"St Augustine led missionaries from Rome who spread Christianity in the south of Britain and became the very first Archbishop of Canterbury.",memoryHook:"A = A: St Augustine became the 1st Archbishop of Canterbury in the south (don’t confuse him with St Columba on Scottish Iona).",visualId:"history-timeline"},{id:"q-ex01-10",examNumber:1,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"boolean",prompt:"True or False: The Norman Conquest of 1066 was the last successful foreign invasion of England.",options:["True","False"],correctIndices:[0],explanation:"William, Duke of Normandy, defeated the Saxon King Harold at the Battle of Hastings in 1066. It remains the last successful foreign military invasion of England.",visualId:"history-timeline"},{id:"q-ex01-11",examNumber:1,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"In what year was King John forced by his noblemen to agree to the Magna Carta?",options:["1066","1215","1314","1415"],correctIndices:[1],explanation:"In 1215, King John was forced by his noblemen to agree to a number of demands in the Magna Carta (meaning the Great Charter), limiting the monarch’s unchecked power.",memoryHook:"Clock anchor: picture the barons cornering King John at 12:15 sharp (1215) to agree to the Magna Carta.",visualId:"history-timeline"},{id:"q-ex01-12",examNumber:1,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Which Scottish king defeated the English army led by Edward II at the Battle of Bannockburn in 1314?",options:["Kenneth MacAlpin","William Wallace","Robert the Bruce","James I"],correctIndices:[2],explanation:"In 1314, the Scottish led by King Robert the Bruce defeated the English at the Battle of Bannockburn, ensuring that Scotland remained unconquered by England.",memoryHook:"B + B: Battle of Bannockburn (1314) = King Robert the Bruce (not William Wallace, who was never king).",visualId:"history-timeline"},{id:"q-ex01-13",examNumber:1,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Who wrote The Canterbury Tales, a collection of poems in English about a group of pilgrims?",options:["Geoffrey Chaucer","John Barbour","William Caxton","Thomas Hardy"],correctIndices:[0],explanation:"Geoffrey Chaucer wrote The Canterbury Tales, a series of poems in English about pilgrims travelling to Canterbury, and it became one of the first books printed in England by William Caxton.",memoryHook:"Don’t mix up the two Cs: CHaucer wrote the CHaracters’ poems (Canterbury Tales); CaXton ran the printing press (think X = Xerox)."},{id:"q-ex01-14",examNumber:1,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"Who is the Supreme Governor (formal head) of the Church of England?",options:["The Prime Minister","The Pope","The Monarch (King Charles III)","The Moderator of the General Assembly"],correctIndices:[2],explanation:"In England, the Church of England (Anglican Church) is the official established state church, and the reigning Monarch: King Charles III, is its Supreme Governor, while the Archbishop of Canterbury is its spiritual leader."},{id:"q-ex01-15",examNumber:1,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Who captained the England football team that won the FIFA World Cup in 1966?",options:["Bobby Moore","Sir Roger Bannister","Gary Lineker","David Beckham"],correctIndices:[0],explanation:"Bobby Moore captained the England football team when England hosted and won the World Cup in 1966.",memoryHook:'England won in 1966 under captain Bobby Moore, and haven’t won "more" World Cups since.'},{id:"q-ex01-16",examNumber:1,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:'Which Scottish town is famously known around the world as the "home of golf"?',options:["Aberdeen","St Andrews","Dundee","Inverness"],correctIndices:[1],explanation:"The modern game of golf can be traced back to 15th-century Scotland, and St Andrews in Fife is universally known as the home of golf.",memoryHook:"Match Scotland’s patron saint (St Andrew) to Scotland’s home of golf: St Andrews."},{id:"q-ex01-17",examNumber:1,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO of the following classic novels were written by Jane Austen? (Choose TWO)",options:["Pride and Prejudice","Sense and Sensibility","Great Expectations","Treasure Island"],correctIndices:[0,1],explanation:"Jane Austen (1775–1817) is one of England’s finest novelists; her famous works concerning marriage and family relationships include Pride and Prejudice and Sense and Sensibility.",memoryHook:'Spot Austen’s signature alliterative "Trait and Trait" title pattern: Pride and Prejudice, Sense and Sensibility.'},{id:"q-ex01-18",examNumber:1,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"In which English town was playwright and poet William Shakespeare born in 1564?",options:["Canterbury","Winchester","Bath","Stratford-upon-Avon"],correctIndices:[3],explanation:"William Shakespeare (1564–1616) was born in Stratford-upon-Avon, England, and worked in London as an actor and playwright."},{id:"q-ex01-19",examNumber:1,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"boolean",prompt:"Does the United Kingdom have a single formal written document that contains its entire constitution?",options:["Yes","No"],correctIndices:[1],explanation:'Unlike the United States or France, the UK constitution is described as "unwritten" because it has never been codified into one single formal document; instead, it consists of Acts of Parliament, common law, and historic conventions.',visualId:"parliament-courts"},{id:"q-ex01-20",examNumber:1,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"What is the title of the National Anthem of the United Kingdom?",options:["God Save the King","Rule, Britannia!","Land of Hope and Glory","Jerusalem"],correctIndices:[0],explanation:'With His Majesty King Charles III as the reigning Monarch, the UK National Anthem is "God Save the King", sung at major national occasions and sporting events.',visualId:"parliament-courts"},{id:"q-ex01-21",examNumber:1,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"How many Members of Parliament (MPs) are elected to sit in the House of Commons?",options:["500","600","650","750"],correctIndices:[2],explanation:"There are 650 MPs in the UK House of Commons, with each MP representing one parliamentary constituency across the UK.",visualId:"parliament-courts"},{id:"q-ex01-22",examNumber:1,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"Which senior Cabinet minister is responsible for the economy and preparing the annual Budget?",options:["The Home Secretary","The Foreign Secretary","The Chancellor of the Exchequer","The Speaker"],correctIndices:[2],explanation:"The Chancellor of the Exchequer is the senior Cabinet minister responsible for the economy, public spending, and taxation.",memoryHook:'Spot "cheque" hidden inside Ex-chequ-er: the Chancellor of the Exchequer handles money, taxes, and the Budget.',visualId:"parliament-courts"},{id:"q-ex01-23",examNumber:1,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"multiple",prompt:"Alongside UK citizens, which TWO other groups of UK residents aged 18 or over are eligible to register to vote in all UK Parliamentary General Elections? (Choose TWO)",options:["Tourists on visitor visas","Qualifying Commonwealth citizens","All United States citizens","Irish citizens"],correctIndices:[1,3],explanation:"Adult (18+) UK citizens, together with qualifying Commonwealth citizens and Irish citizens who are resident in the UK and on the electoral register, can vote in all UK public elections.",visualId:"parliament-courts"},{id:"q-ex01-24",examNumber:1,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"What is the minimum legal age to play the National Lottery (including Lotto and scratchcards) in the UK?",options:["16","17","18","21"],correctIndices:[2],explanation:"People under 18 are not allowed to participate in the National Lottery (the minimum age was raised from 16 to 18 in 2021)."},{id:"q-ex02-01",examNumber:2,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"What score is required to pass the official 24-question Life in the UK Test?",options:["50% (12 out of 24)","65% (16 out of 24)","75% (18 out of 24)","85% (21 out of 24)"],correctIndices:[2],explanation:"Candidates must answer at least 18 out of 24 questions correctly: a pass mark of 75%, within 45 minutes."},{id:"q-ex02-02",examNumber:2,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"Which TWO of the following are shared responsibilities of everyone living in the UK? (Choose TWO)",options:["Vote for the governing political party","Respect and obey the law","Look after the area in which you live and the environment","Attend church services every Sunday"],correctIndices:[1,2],explanation:"If you wish to be a permanent resident or citizen of the UK, you should: respect and obey the law, respect the rights of others (including their opinions), treat others with fairness, look after yourself and your family, and look after the area in which you live and the environment."},{id:"q-ex02-03",examNumber:2,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"What is the capital city of Wales?",options:["Swansea","Newport","Cardiff","Wrexham"],correctIndices:[2],explanation:"Cardiff is the capital city of Wales (and home to the Senedd Cymru / Welsh Parliament). Swansea and Newport are other major Welsh cities.",visualId:"uk-map"},{id:"q-ex02-04",examNumber:2,chapterId:"ch2",subtopicId:"ch2-symbols",type:"multiple",prompt:"Alongside the Cross of St George (England), which TWO other patron saints’ crosses are combined to make the Union Flag? (Choose TWO)",options:["St Andrew","St David","St Patrick","St Columba"],correctIndices:[0,2],explanation:"The Union Flag (Union Jack) combines three crosses: St George (England), St Andrew (Scotland), and St Patrick (Ireland). St David’s cross is not part of the flag.",memoryHook:'Acronym "GAP": George, Andrew, and Patrick make up the Union Flag, leaving a "gap" for Wales’s St David.',visualId:"union-jack"},{id:"q-ex02-05",examNumber:2,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"On what date is St David’s Day, the patron saint’s day of Wales, celebrated each year?",options:["1 March","17 March","23 April","30 November"],correctIndices:[0],explanation:"St David’s Day (Wales) is celebrated on 1 March. St Patrick’s Day is 17 March, St George’s Day is 23 April, and St Andrew’s Day is 30 November.",memoryHook:"Meteorological spring begins on 1 March, right when yellow Welsh daffodils bloom first: 1 March = St David’s Day.",visualId:"national-emblems"},{id:"q-ex02-06",examNumber:2,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Approximately how many years ago did Britain become permanently separated from mainland Europe by the English Channel?",options:["2,000 years ago","4,000 years ago","10,000 years ago","50,000 years ago"],correctIndices:[2],explanation:"For much of the Stone Age, Britain was connected to the continent by a land bridge. It only became permanently separated from the continent by the Channel about 10,000 years ago.",visualId:"history-timeline"},{id:"q-ex02-07",examNumber:2,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"In which English county does the prehistoric monument of Stonehenge stand?",options:["Wiltshire","Dorset","Suffolk","Kent"],correctIndices:[0],explanation:"Stonehenge still stands in what is now the English county of Wiltshire and was probably a special gathering place for seasonal ceremonies.",memoryHook:"Stones never wilt: Stonehenge stands in Wiltshire (don’t confuse with Maiden Castle in Dorset or Sutton Hoo in Suffolk).",visualId:"history-timeline"},{id:"q-ex02-08",examNumber:2,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Who led a Roman invasion of Britain in 55 BC that was unsuccessful?",options:["Emperor Claudius","Julius Caesar","Emperor Hadrian","Mark Antony"],correctIndices:[1],explanation:"Julius Caesar led a Roman invasion of Britain in 55 BC. This was unsuccessful, and for nearly 100 years Britain remained separate from the Roman Empire until Claudius invaded in AD 43.",memoryHook:'BC = "Before Conquest": Julius Caesar’s 55 BC invasion failed; Rome didn’t conquer Britain until AD 43 under Claudius.',visualId:"history-timeline"},{id:"q-ex02-09",examNumber:2,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Why did the Roman Emperor Hadrian build a wall in the north of England?",options:["To mark the border between England and Wales","To stop Viking longships sailing up the Thames","To divide Anglo-Saxon kingdoms from the Danelaw","To keep out the Picts (ancestors of the Scottish people)"],correctIndices:[3],explanation:"Areas of what is now Scotland were never conquered by the Romans, and Emperor Hadrian built Hadrian’s Wall in the north of England to keep out the Picts.",visualId:"history-timeline"},{id:"q-ex02-10",examNumber:2,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Where in Suffolk was a famous Anglo-Saxon king buried with treasure and armour inside a ship under a mound of earth?",options:["Maiden Castle","Sutton Hoo","Skara Brae","Vindolanda"],correctIndices:[1],explanation:"The burial place of one of the early Anglo-Saxon kings was found at Sutton Hoo in modern Suffolk; he was buried with treasure and armour, all placed in a ship covered by a mound of earth.",memoryHook:'"Who" is buried in the Saxon ship in Suffolk? Sutton Hoo (all Ss: Sutton, Suffolk, Saxon, Ship).',visualId:"history-timeline"},{id:"q-ex02-11",examNumber:2,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Which king united the Anglo-Saxon kingdoms in England and defeated the Vikings?",options:["King Alfred the Great","King Harold","King Kenneth MacAlpin","King John"],correctIndices:[0],explanation:"The Anglo-Saxon kingdoms in England united under King Alfred the Great, who defeated the Vikings while permitting many Danes to live peacefully in the Danelaw.",memoryHook:'A = A: Alfred the Great united the Anglo-Saxons in England against the Vikings (while "Mac"Alpin united Scotland).',visualId:"history-timeline"},{id:"q-ex02-12",examNumber:2,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"In 1348, the Black Death (a form of plague) came to Britain. Roughly what fraction of the population of England, Wales, and Scotland died?",options:["One tenth","One quarter","One third","Three quarters"],correctIndices:[2],explanation:"In 1348, the Black Death killed one third of the population in England, with similar proportions in Wales and Scotland: one of the worst disasters ever to strike Britain.",memoryHook:"Digit anchor: 1348 starts with 1 and 3, matching 1/3 (one third) of the population lost to the Black Death.",visualId:"history-timeline"},{id:"q-ex02-13",examNumber:2,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Who was the first person in England to print books using a printing press?",options:["Geoffrey Chaucer","John Barbour","William Shakespeare","William Caxton"],correctIndices:[3],explanation:"In the years leading up to 1485, William Caxton became the first person in England to print books using a printing press, including Geoffrey Chaucer’s Canterbury Tales.",memoryHook:"Spot the X in CaXton (like Xerox or teXt): William Caxton ran England’s first printing press, whereas CHaucer wrote the poems."},{id:"q-ex02-14",examNumber:2,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"boolean",prompt:"Is the British Monarch the head of the national Church of Scotland?",options:["Yes","No"],correctIndices:[1],explanation:"No! Unlike the Church of England, the national Church of Scotland is a Presbyterian church governed by ministers and elders (its leadership is the Moderator of the General Assembly), and the British Monarch is NOT its head."},{id:"q-ex02-15",examNumber:2,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Who became the first man in the world to run a mile in under four minutes in 1954?",options:["Sir Mo Farah","Sir Roger Bannister","Seb Coe","Sir Chris Hoy"],correctIndices:[1],explanation:"In 1954, Sir Roger Bannister (1929–2018) became the first man in the world to run a mile in under four minutes, at Oxford.",memoryHook:'Think "breaking the ban": Roger BANnister broke the 4-minute barrier in ’54 (both end in 4).'},{id:"q-ex02-16",examNumber:2,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:'Which famous event held in London each summer is the oldest tennis tournament in the world and the only "Grand Slam" played on grass?',options:["The Wimbledon Championships","Queen’s Club Championships","Royal Ascot","The Open Championship"],correctIndices:[0],explanation:"The Wimbledon Championships, held every year at the All England Croquet and Lawn Tennis Club, is the oldest tennis tournament in the world and the only Grand Slam event played on grass."},{id:"q-ex02-17",examNumber:2,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which Scottish doctor and writer created the world-famous fictional detective Sherlock Holmes in 1887?",options:["Robert Louis Stevenson","Ian Fleming","Charles Dickens","Sir Arthur Conan Doyle"],correctIndices:[3],explanation:"Sir Arthur Conan Doyle (1859–1930) was a Scottish doctor and writer best known for his stories about Sherlock Holmes, who was one of the first fictional detectives.",memoryHook:"D + D + D: Scottish Doctor Conan Doyle created Detective Sherlock Holmes (whereas Ian Fleming created James Bond)."},{id:"q-ex02-18",examNumber:2,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO of the following famous novels were written by Charles Dickens? (Choose TWO)",options:["Pride and Prejudice","Far from the Madding Crowd","Oliver Twist","Great Expectations"],correctIndices:[2,3],explanation:"Charles Dickens (1812–1870) wrote celebrated Victorian novels including Oliver Twist and Great Expectations, creating characters like Scrooge and Mr Micawber that are still referenced in everyday English."},{id:"q-ex02-19",examNumber:2,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"Who is the Head of State of the United Kingdom?",options:["The Prime Minister","The Monarch (His Majesty King Charles III)","The Lord Speaker","The Chief Justice of the Supreme Court"],correctIndices:[1],explanation:"The UK has a constitutional monarchy: His Majesty King Charles III is the Head of State, while the Prime Minister is the leader of the elected government.",visualId:"parliament-courts"},{id:"q-ex02-20",examNumber:2,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"What voting system is used to elect MPs to the House of Commons in a UK General Election?",options:["First Past the Post","Proportional Representation","Single Transferable Vote","Additional Member System"],correctIndices:[0],explanation:'MPs are elected to the House of Commons through the "First Past the Post" system: in each constituency, the candidate who receives the most votes wins the seat.',memoryHook:'Exam trap: Westminster MPs win by "First Past the Post" (one winner per constituency, like a horse race), whereas devolved assemblies use proportional representation.',visualId:"parliament-courts"},{id:"q-ex02-21",examNumber:2,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"Who chairs debates in the House of Commons and ensures that MPs follow parliamentary rules while remaining politically neutral?",options:["The Prime Minister","The Chief Whip","The Speaker","The Chancellor"],correctIndices:[2],explanation:"Debates in the House of Commons are chaired by the Speaker, who is the chief officer of the House of Commons, remains politically neutral, and keeps order during debates.",visualId:"parliament-courts"},{id:"q-ex02-22",examNumber:2,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"Can the House of Commons overrule the House of Lords if the Lords reject a proposed law?",options:["Yes","No"],correctIndices:[0],explanation:"Yes. While the House of Lords checks and suggests amendments to laws passed by the Commons, the democratically elected House of Commons is the more powerful chamber and can legally overrule the Lords.",visualId:"parliament-courts"},{id:"q-ex02-23",examNumber:2,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"Which senior Cabinet minister is responsible for crime, policing, and immigration?",options:["The Chancellor of the Exchequer","The Foreign Secretary","The Defence Secretary","The Home Secretary"],correctIndices:[3],explanation:"The Home Secretary is the Cabinet minister responsible for crime, policing, national security, and immigration.",memoryHook:'Think "homeland / domestic security" rather than housing: the Home Secretary handles policing, crime, and immigration inside the UK.',visualId:"parliament-courts"},{id:"q-ex02-24",examNumber:2,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"True or False: In the UK, the judiciary (judges) are independent of the government, so politicians cannot interfere in court cases.",options:["True","False"],correctIndices:[0],explanation:"Judges in the UK are strictly independent of the government and Parliament; ministers cannot tell judges how to decide legal cases, and judges can even rule that government actions are unlawful.",visualId:"parliament-courts"},{id:"q-ex03-01",examNumber:3,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"How much time are you allowed to complete the official Life in the UK Test?",options:["30 minutes","45 minutes","60 minutes","90 minutes"],correctIndices:[1],explanation:"Candidates have 45 minutes to answer the 24 multiple-choice questions in the official Life in the UK Test.",memoryHook:"One half of a football match = 45 minutes on the test clock."},{id:"q-ex03-02",examNumber:3,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"Which of the following is NOT a fundamental principle of British life?",options:["Individual liberty","Tolerance of those with different faiths and beliefs","Belonging to the established state church","Participation in community life"],correctIndices:[2],explanation:"Freedom of religion (including having no religion) and tolerance of different faiths and beliefs are core British principles; nobody is required to belong to a state church."},{id:"q-ex03-03",examNumber:3,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"boolean",prompt:"True or False: At a UK citizenship ceremony, people who do not wish to swear a religious oath can choose to make a non-religious Affirmation of Allegiance instead.",options:["True","False"],correctIndices:[0],explanation:'Those who do not wish to swear a religious Oath ("I swear by Almighty God...") can make a solemn non-religious Affirmation of Allegiance ("I do solemnly, sincerely and truly declare and affirm...") to King Charles III.'},{id:"q-ex03-04",examNumber:3,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"What is the capital city of Northern Ireland?",options:["Dublin","Derry / Londonderry","Belfast","Lisburn"],correctIndices:[2],explanation:"Belfast is the capital city of Northern Ireland (note that Dublin is the capital of the Republic of Ireland, an independent country).",visualId:"uk-map"},{id:"q-ex03-05",examNumber:3,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"Why does the red Welsh dragon NOT appear on the Union Flag?",options:["The Principality of Wales was already united with England when the first Union Flag was created in 1606","Wales chose to keep its flag completely secret","Wales only joined the United Kingdom in 1922","Red ink was reserved exclusively for St Patrick’s cross"],correctIndices:[0],explanation:"The Welsh dragon does not appear on the Union Flag because, when the first Union Flag was created in 1606 from the flags of Scotland and England, the Principality of Wales was already united with England.",visualId:"union-jack"},{id:"q-ex03-06",examNumber:3,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Around 4,000 years ago, people learned to make bronze. What structures did Bronze Age people build to bury their dead alongside bronze tools and gold ornaments?",options:["Hill forts","Roman amphitheatres","Norman motte-and-baileys","Round barrows"],correctIndices:[3],explanation:"During the Bronze Age, people lived in roundhouses and buried their dead in tombs called round barrows, crafting metal objects in bronze and gold.",memoryHook:"BRonze Age starts with B + R: Barrows (round barrows) and Roundhouses (don’t confuse with Iron Age hill forts).",visualId:"history-timeline"},{id:"q-ex03-07",examNumber:3,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Which tribal leader of the Iceni in what is now eastern England fought against the Romans and is remembered by a statue on Westminster Bridge?",options:["Boudicca","Cartimandua","Elizabeth I","Matilda"],correctIndices:[0],explanation:"One of the tribal leaders who fought against the Romans was Boudicca, the queen of the Iceni in what is now eastern England. Her statue stands on Westminster Bridge in London.",visualId:"history-timeline"},{id:"q-ex03-08",examNumber:3,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"After nearly 400 years in Britain, in what year did the Roman army leave Britain to defend other parts of the Roman Empire?",options:["AD 122","AD 310","AD 410","AD 597"],correctIndices:[2],explanation:"The Romans remained in Britain for nearly 400 years (from AD 43) until the Roman army left in AD 410 to defend other parts of the Roman Empire, never to return.",memoryHook:"Math check: Rome conquered Britain in AD 43 and stayed nearly 400 years (43 + ~370 puts departure in the early 400s: AD 410).",visualId:"history-timeline"},{id:"q-ex03-09",examNumber:3,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Which early Christian missionary founded a monastery on the island of Iona, off the coast of what is now Scotland?",options:["St Augustine","St Columba","St George","St David"],correctIndices:[1],explanation:"Missionaries from Ireland spread Christianity in the north, notably St Columba, who founded a monastery on the island of Iona, off the coast of what is now Scotland.",memoryHook:"Pair the two missionaries: Columba = Celtic north (island of Iona off Scotland); Augustine = Archbishop #1 in the south (Canterbury).",visualId:"history-timeline"},{id:"q-ex03-10",examNumber:3,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Who defeated the Saxon King Harold at the Battle of Hastings in 1066?",options:["King Cnut of Denmark","Robert the Bruce","King Edward I","William, Duke of Normandy"],correctIndices:[3],explanation:"In 1066, an invasion led by William, the Duke of Normandy (in northern France), defeated Harold, the Saxon king of England, at the Battle of Hastings. Harold was killed, and William became known as William the Conqueror.",visualId:"history-timeline"},{id:"q-ex03-11",examNumber:3,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"What was the Domesday Book, compiled on the orders of William the Conqueror?",options:["A record of all the towns, villages, people, land, and animals in England","A book of prayers used in Canterbury Cathedral","A collection of medieval poems written in Norman French","A peace treaty between England and Scotland"],correctIndices:[0],explanation:"William the Conqueror sent people all over England to draw up lists of all the towns and villages, the people who lived there, who owned the land, and what animals they owned. This was called the Domesday Book and still exists today.",memoryHook:'Don’t let the name fool you: "Domesday" wasn’t a prayer book, it was William’s nationwide tax census (nicknamed "Doomsday" because nobody could appeal its final count).',visualId:"history-timeline"},{id:"q-ex03-12",examNumber:3,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Which English king defeated a vastly larger French army at the Battle of Agincourt in 1415 during the Hundred Years War?",options:["King Edward I","King Henry V","King Richard III","King Henry VII"],correctIndices:[1],explanation:"One of the most famous battles of the Hundred Years War was the Battle of Agincourt in 1415, where King Henry V’s vastly outnumbered English army defeated the French.",memoryHook:"Digit anchor in 1415: 1 + 4 = 5, and the year ends in 5, pointing straight to King Henry V at Agincourt.",visualId:"history-timeline"},{id:"q-ex03-13",examNumber:3,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Which battle in 1485 ended the Wars of the Roses when Henry Tudor defeated King Richard III?",options:["The Battle of Hastings","The Battle of Bannockburn","The Battle of Bosworth Field","The Battle of Agincourt"],correctIndices:[2],explanation:"The Wars of the Roses ended with the Battle of Bosworth Field in 1485. King Richard III of the House of York was killed, and Henry Tudor of the House of Lancaster became King Henry VII.",memoryHook:"Roses grow in a field: the Wars of the Roses ended at the Battle of Bosworth Field (1485).",visualId:"history-timeline"},{id:"q-ex03-14",examNumber:3,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"What type of church is the national Church of Scotland?",options:["An Anglican church","A Roman Catholic church","A Presbyterian church","A Quaker meeting"],correctIndices:[2],explanation:"In Scotland, the national Church is the Church of Scotland, which is a Presbyterian church governed by ministers and elders."},{id:"q-ex03-15",examNumber:3,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Which Scottish former racing driver won the Formula 1 World Championship three times?",options:["Sir Jackie Stewart","Damon Hill","Sir Bradley Wiggins","Sir Roger Bannister"],correctIndices:[0],explanation:"Sir Jackie Stewart (born 1939) is a Scottish former racing driver who won the Formula 1 World Championship three times.",memoryHook:"Spot the royal Scottish surname: Stewart (House of Stuart) = Sir Jackie Stewart, the 3-time Scottish F1 champion (Damon Hill won once for England)."},{id:"q-ex03-16",examNumber:3,chapterId:"ch4",subtopicId:"ch4-sports",type:"multiple",prompt:"Which TWO universities compete against each other in the famous annual Boat Race along the River Thames in London? (Choose TWO)",options:["University of Oxford","University of Cambridge","University of Edinburgh","Durham University"],correctIndices:[0,1],explanation:"The Boat Race is a famous annual rowing race on the River Thames in London between crews from the Universities of Oxford and Cambridge."},{id:"q-ex03-17",examNumber:3,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO of the following famous adventure and mystery stories were written by Robert Louis Stevenson? (Choose TWO)",options:["Oliver Twist","Treasure Island","The Strange Case of Dr Jekyll and Mr Hyde","Sense and Sensibility"],correctIndices:[1,2],explanation:"Robert Louis Stevenson (1850–1894) wrote books that are still read by adults and children today, most famously Treasure Island, Kidnapped, and The Strange Case of Dr Jekyll and Mr Hyde."},{id:"q-ex03-18",examNumber:3,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"In which famous London theatre were many of William Shakespeare’s plays originally performed (with a modern replica standing near the site today)?",options:["The Royal Albert Hall","The London Palladium","The Old Bailey","The Globe Theatre"],correctIndices:[3],explanation:"Many of Shakespeare’s plays, such as Hamlet, Macbeth, and A Midsummer Night’s Dream, were performed in the Globe Theatre in London; a modern replica stands on the south bank of the Thames today.",memoryHook:'Connect Shakespeare’s famous line "All the world’s a stage" to the world itself: The Globe Theatre.'},{id:"q-ex03-19",examNumber:3,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"What happens during the King’s Speech at the State Opening of Parliament?",options:["King Charles III outlines the UK government’s policies and proposed new laws for the session","King Charles III announces his own personal political manifesto","MPs vote by show of hands to elect a new Prime Minister","Judges of the Supreme Court swear in local councillors"],correctIndices:[0],explanation:"King Charles III opens each new parliamentary session with the King’s Speech (written by the elected government), setting out the government’s policies and the Bills to be introduced to Parliament.",visualId:"parliament-courts"},{id:"q-ex03-20",examNumber:3,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"At least how often must a UK Parliamentary General Election be held?",options:["At least every 3 years","At least every 4 years","At least every 5 years","At least every 7 years"],correctIndices:[2],explanation:"MPs are elected at a General Election, which must be held at least every five years (though an election can be called earlier).",visualId:"parliament-courts"},{id:"q-ex03-21",examNumber:3,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"How often does Prime Minister’s Questions (PMQs) take place when Parliament is sitting?",options:["Every day","Once a week","Once a month","Twice a year"],correctIndices:[1],explanation:"The Opposition and MPs question the Prime Minister in the House of Commons every week (on Wednesdays) during Prime Minister’s Questions (PMQs) while Parliament is sitting.",visualId:"parliament-courts"},{id:"q-ex03-22",examNumber:3,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"What is Hansard?",options:["The ceremonial mace carried into the House of Commons","The country residence of the Prime Minister","The committee that sets interest rates at the Bank of England","The official verbatim published report of everything said in Parliamentary proceedings"],correctIndices:[3],explanation:"Proceedings in Parliament are broadcast on television and published in official reports known as Hansard, which are freely available in large libraries and online.",memoryHook:'Phonetic link: "Hansard" sounds like "hands heard", recording every word spoken in Parliament.',visualId:"parliament-courts"},{id:"q-ex03-23",examNumber:3,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO of the following are examples of Civil Law disputes rather than Criminal Law offences? (Choose TWO)",options:["Carrying an illegal weapon in public","Shoplifting from a supermarket","Housing disputes between landlords and tenants","Employment disputes such as unfair dismissal"],correctIndices:[2,3],explanation:"Civil law settles disputes between individuals or groups: including housing law (landlord/tenant), consumer rights, employment law (unfair dismissal/discrimination), and debt: whereas weapons offences and theft are criminal offences.",visualId:"parliament-courts"},{id:"q-ex03-24",examNumber:3,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"True or False: UK civil servants are politically neutral and continue to serve whichever political party is elected to form the government.",options:["True","False"],correctIndices:[0],explanation:"Civil servants support the government in developing and implementing policies and delivering public services. Unlike ministers, they are politically neutral (bound by integrity, honesty, objectivity, and impartiality) and are not replaced when governments change.",visualId:"parliament-courts"},{id:"q-ex04-01",examNumber:4,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"Unless exempt, what minimum level of English speaking and listening skill is required when applying for settlement or UK citizenship?",options:["CEFR level A1","CEFR level A2","CEFR level B1","University doctorate level (C2)"],correctIndices:[2],explanation:"Along with passing the Life in the UK Test, applicants usually need to demonstrate English speaking and listening skills at Common European Framework of Reference (CEFR) level B1 (intermediate) or higher.",memoryHook:'Wordplay: to "be one" (B1) of the UK’s permanent residents or citizens, you need CEFR level B1 English.'},{id:"q-ex04-02",examNumber:4,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"Which TWO of the following freedoms and rights does the UK offer to its residents and citizens in return for respecting its laws and values? (Choose TWO)",options:["Freedom of speech","Exemption from paying local taxes","A right to a fair trial","Guaranteed election to Parliament"],correctIndices:[0,2],explanation:"In return for fulfilling civic responsibilities, the UK offers: freedom of belief and religion, freedom of speech, freedom from unfair discrimination, a right to a fair trial, and a right to join in the election of a government."},{id:"q-ex04-03",examNumber:4,chapterId:"ch2",subtopicId:"ch2-territories",type:"boolean",prompt:"Are the Channel Islands and the Isle of Man officially part of the United Kingdom?",options:["Yes","No"],correctIndices:[1],explanation:'No. The Channel Islands and the Isle of Man are "Crown Dependencies": they are closely linked to the Crown and British Isles, have their own governments, and are NOT part of the UK.',visualId:"uk-map"},{id:"q-ex04-04",examNumber:4,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"What is the national flower of Scotland?",options:["The Thistle","The Daffodil","The Shamrock","The Rose"],correctIndices:[0],explanation:"The national flower of Scotland is the Thistle: a prickly-leaved purple flower originally used as a defensive symbol.",visualId:"national-emblems"},{id:"q-ex04-05",examNumber:4,chapterId:"ch2",subtopicId:"ch2-symbols",type:"multiple",prompt:"Which TWO nations of the UK have an official bank holiday for their patron saint’s day? (Choose TWO)",options:["England","Scotland","Wales","Northern Ireland"],correctIndices:[1,3],explanation:"Although all four nations celebrate their patron saints’ days, only Scotland (St Andrew’s Day, 30 November) and Northern Ireland (St Patrick’s Day, 17 March) have official public holidays for them.",memoryHook:"Geographic rule: head north for the day off. Only the two northern nations (Scotland and Northern Ireland) get an official patron saint bank holiday.",visualId:"national-emblems"},{id:"q-ex04-06",examNumber:4,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Which impressive Iron Age hill fort can still be seen today in the English county of Dorset?",options:["Sutton Hoo","Skara Brae","Vindolanda","Maiden Castle"],correctIndices:[3],explanation:"During the Iron Age, people often defended sites called hill forts. A very impressive hill fort can still be seen today at Maiden Castle, in the English county of Dorset.",memoryHook:'Think "Iron Maiden": Iron Age hill fort = Maiden Castle (in Dorset).',visualId:"history-timeline"},{id:"q-ex04-07",examNumber:4,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"multiple",prompt:"Which TWO Roman forts along Hadrian’s Wall can still be visited today as part of a UNESCO World Heritage Site? (Choose TWO)",options:["Maiden Castle","Housesteads","Conwy","Vindolanda"],correctIndices:[1,3],explanation:"Parts of Hadrian’s Wall: including the Roman forts of Housesteads and Vindolanda, can still be seen today and are a popular walking area and UNESCO World Heritage Site.",memoryHook:"Picture chilly Roman soldiers on Hadrian’s Wall sheltering in Houses (Housesteads) and warming up with Vino (Vindolanda).",visualId:"history-timeline"},{id:"q-ex04-08",examNumber:4,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"multiple",prompt:"Where did the Vikings come from when they first visited Britain in AD 789 to raid coastal towns? (Choose TWO)",options:["Denmark","Italy","Spain","Norway"],correctIndices:[0,3],explanation:"The Vikings came from Denmark and Norway. They first raided coastal towns and monasteries in AD 789 before staying to form their own communities in eastern England and Scotland.",visualId:"history-timeline"},{id:"q-ex04-09",examNumber:4,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"What name was given to the region of eastern and northern England where Danish Viking settlers lived after uniting peaceably alongside Anglo-Saxons?",options:["The Pale","The Danelaw","Wessex","Caledonia"],correctIndices:[1],explanation:"Many Viking invaders stayed in Britain: especially in the east and north of England, in an area known as the Danelaw (giving rise to place names like Grimsby and Scunthorpe).",visualId:"history-timeline"},{id:"q-ex04-10",examNumber:4,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Which famous linen embroidery, nearly 70 metres (230 feet) long, commemorates the 1066 Battle of Hastings?",options:["The Magna Carta","The Domesday Book","The Lindisfarne Gospels","The Bayeux Tapestry"],correctIndices:[3],explanation:"The Battle of Hastings is commemorated in a great piece of embroidery known as the Bayeux Tapestry, which is nearly 70 metres (230 feet) long and can still be seen in France today.",visualId:"history-timeline"},{id:"q-ex04-11",examNumber:4,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"What fundamental constitutional principle was established by the Magna Carta in 1215?",options:["Every adult man and woman had the right to vote","England and Scotland were united under one Parliament","Even the king was subject to the law","The Prime Minister could dismiss the Monarch"],correctIndices:[2],explanation:'The Magna Carta ("Charter of Liberties") established the idea that even the king was subject to the law. It protected the rights of the nobility and restricted the king’s power to collect taxes or make/change laws without consulting his nobles.',visualId:"history-timeline"},{id:"q-ex04-12",examNumber:4,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"What did King Edward I of England introduce in 1284 to annex Wales to the Crown of England?",options:["The Statute of Rhuddlan","The Magna Carta","The Domesday Book","The Treaty of Dover"],correctIndices:[0],explanation:"In 1284, King Edward I of England introduced the Statute of Rhuddlan, which annexed Wales to the Crown of England and was backed up by massive castles such as Conwy and Caernarfon.",memoryHook:'Spot the Welsh double-"dd" spelling in RhuDDlan: Edward I’s Statute of Rhuddlan (1284) annexed Wales.',visualId:"history-timeline"},{id:"q-ex04-13",examNumber:4,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"Who wrote The Bruce, a medieval poem in the Scots language celebrating Robert the Bruce’s victory at Bannockburn?",options:["John Barbour","Geoffrey Chaucer","Robert Burns","William Caxton"],correctIndices:[0],explanation:"In Scotland, many people continued to speak Gaelic and the Scots language also developed; the poet and chronicler John Barbour wrote The Bruce about the Battle of Bannockburn.",memoryHook:"BarBour has two Bs: he wrote The Bruce about Bannockburn (don’t confuse him with 18th-century poet Robert Burns)."},{id:"q-ex04-14",examNumber:4,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"Who is the spiritual leader of the Church of England?",options:["The Archbishop of Canterbury","The Moderator of the General Assembly","The Lord Chancellor","The Cardinal of Westminster"],correctIndices:[0],explanation:"While the Monarch (King Charles III) is the Supreme Governor of the Church of England, the Archbishop of Canterbury is the spiritual leader of the Church of England (and the worldwide Anglican Communion)."},{id:"q-ex04-15",examNumber:4,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Jayne Torvill and Christopher Dean won a legendary gold medal at the 1984 Winter Olympics in which sport?",options:["Ski jumping","Curling","Bobsleigh","Ice dancing"],correctIndices:[3],explanation:"Jayne Torvill and Christopher Dean won gold medals for ice dancing at the Olympic Games in 1984 (skating to Ravel’s Bolero) and in four consecutive world championships.",memoryHook:'Mixed pair + "D" for Dean = Ice Dancing (unlike solo ski jumping or 4-person curling and bobsleigh).'},{id:"q-ex04-16",examNumber:4,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Where is the famous Grand National horse race held every year?",options:["Ascot in Berkshire","Epsom in Surrey","Aintree near Liverpool","Newmarket in Suffolk"],correctIndices:[2],explanation:"Famous horse-racing events in the UK include Royal Ascot, the Scottish Grand National, and the Grand National at Aintree near Liverpool.",memoryHook:'The Grand National is famous for tall spruce-branch jump fences: think "tree" fences at Ain-tree (near Liverpool), whereas Royal Ascot is in Berkshire.'},{id:"q-ex04-17",examNumber:4,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which author wrote novels focused on rural society in south-west England, including Far from the Madding Crowd and Jude the Obscure?",options:["Charles Dickens","Sir Arthur Conan Doyle","Robert Louis Stevenson","Thomas Hardy"],correctIndices:[3],explanation:"Thomas Hardy (1840–1928) was an author and poet whose best-known novels focus on rural society in south-west England, including Far from the Madding Crowd and Jude the Obscure.",memoryHook:"Hard rural farming life in south-west England = Thomas Hardy (unlike Dickens’s urban London stories)."},{id:"q-ex04-18",examNumber:4,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"boolean",prompt:"True or False: The Tower of London was first built by William the Conqueror after he became king in 1066, and visitors can see the Crown Jewels there today.",options:["True","False"],correctIndices:[0],explanation:'The Tower of London was first built by William the Conqueror after he became king in 1066. Today visitors can tour the fortress, meet Yeoman Warders ("Beefeaters"), and view the Crown Jewels.',visualId:"uk-map"},{id:"q-ex04-19",examNumber:4,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"Once a Bill has been passed by both the House of Commons and the House of Lords, what must King Charles III formally grant for it to become an Act of Parliament (law)?",options:["A Privy Seal","A Speaker’s Warrant","A Referendum","Royal Assent"],correctIndices:[3],explanation:"In the UK’s constitutional monarchy, once both Houses of Parliament pass a Bill, the Monarch formally agrees to make it an Act of Parliament by granting Royal Assent.",visualId:"parliament-courts"},{id:"q-ex04-20",examNumber:4,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"What happens if an MP dies or resigns between UK General Elections?",options:["The Prime Minister personally picks a friend to take the seat","The seat remains empty for up to five years","A fresh election called a by-election is held in that MP’s constituency","A member of the House of Lords automatically takes the seat"],correctIndices:[2],explanation:"If an MP dies or resigns, there will be a fresh election, called a by-election, in his or her constituency alone.",memoryHook:'Phonetic pun: when a single MP says "bye", just that one constituency holds a "by-election".',visualId:"parliament-courts"},{id:"q-ex04-21",examNumber:4,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"How is the Speaker of the House of Commons chosen?",options:["Elected by fellow MPs in a secret ballot","Appointed personally by the Prime Minister","Inherited from the oldest peer in the House of Lords","Chosen at random from the public electoral register"],correctIndices:[0],explanation:"The Speaker is an MP elected by other MPs in a secret ballot to chair debates impartially in the House of Commons.",visualId:"parliament-courts"},{id:"q-ex04-22",examNumber:4,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"Which senior Cabinet minister is responsible for managing the UK’s relationships with foreign countries?",options:["The Home Secretary","The Chancellor of the Exchequer","The Leader of the House","The Foreign Secretary"],correctIndices:[3],explanation:"The Foreign Secretary (Secretary of State for Foreign, Commonwealth and Development Affairs) is responsible for managing relationships with foreign countries and British diplomacy abroad.",visualId:"parliament-courts"},{id:"q-ex04-23",examNumber:4,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"Can a 17-year-old vote in a UK Parliamentary General Election?",options:["Yes","No"],correctIndices:[1],explanation:"No. To vote in a UK Parliamentary General Election (Westminster), you must be aged 18 or over and registered on the electoral register.",memoryHook:"Exam trap: although 16- and 17-year-olds can vote in some Scottish and Welsh devolved elections, UK Parliamentary General Elections (Westminster) require voters to be 18 or over.",visualId:"parliament-courts"},{id:"q-ex04-24",examNumber:4,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Which branch of law relates to offences against society, usually investigated by the police and prosecuted on behalf of the state?",options:["Criminal law","Civil law","Employment tribunal law","Small claims procedure"],correctIndices:[0],explanation:"Laws in the UK are divided into criminal law and civil law. Criminal law relates to crimes against society, which are investigated by the police or another authority and punished by the courts.",visualId:"parliament-courts"},{id:"q-ex05-01",examNumber:5,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"From what age are applicants automatically exempt from both the Life in the UK Test and the English language requirement when applying for settlement or citizenship?",options:["55 or over","60 or over","65 or over","70 or over"],correctIndices:[2],explanation:"Applicants aged 65 or over (as well as those under 18, or with certain permanent physical or mental conditions) are exempt from taking the Life in the UK Test and proving B1 English."},{id:"q-ex05-02",examNumber:5,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"True or False: Forced marriage and female genital mutilation (FGM) are illegal criminal offences in the United Kingdom.",options:["True","False"],correctIndices:[0],explanation:"Forced marriage (forcing someone to marry against their will), FGM (including taking a girl abroad for FGM), and domestic violence are serious criminal offences in the UK."},{id:"q-ex05-03",examNumber:5,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"Alongside the Oath or Affirmation of Allegiance to the King, what do new citizens promise in the Citizenship Pledge?",options:["To never travel outside the United Kingdom for five years","To join a British political party within six months","To give loyalty to the UK, respect its rights and freedoms, uphold its democratic values, and observe its laws","To purchase property in England, Scotland, Wales, or Northern Ireland"],correctIndices:[2],explanation:'In the Citizenship Pledge, new citizens promise: "I will give my loyalty to the United Kingdom and respect its rights and freedoms. I will uphold its democratic values. I will observe its laws faithfully and fulfil my duties and obligations as a British citizen."'},{id:"q-ex05-04",examNumber:5,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"What is the approximate distance from John O’Groats on the north coast of Scotland to Land’s End in the south-west corner of England?",options:["About 300 miles (480 km)","About 550 miles (885 km)","About 870 miles (1,400 km)","About 1,500 miles (2,400 km)"],correctIndices:[2],explanation:"The longest distance on the mainland, from John O’Groats on the north coast of Scotland to Land’s End in the south-west corner of England, is about 870 miles (approximately 1,400 km). Britain is about 300 miles across at its widest point.",memoryHook:"Exam trap: 300 miles is Britain’s width; top-to-bottom length steps down 8-7-0 (about 870 miles / 1,400 km).",visualId:"uk-map"},{id:"q-ex05-05",examNumber:5,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"On what date is St George’s Day, the patron saint’s day of England, celebrated?",options:["1 March","17 March","23 April","30 November"],correctIndices:[2],explanation:"St George is the patron saint of England, and St George’s Day is celebrated on 23 April (traditionally also remembered as William Shakespeare’s birthday and death date!).",memoryHook:"In UK date format (DD/MM), 23 April is 23/4: just count 2, 3, 4 for England’s St George’s Day.",visualId:"national-emblems"},{id:"q-ex05-06",examNumber:5,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"People in Iron Age Britain made the first coins to be minted in Britain. What was inscribed on some of these coins?",options:["Portraits of the Archbishop of Canterbury","Quotes from the Magna Carta in Latin","Drawings of Stonehenge","The names of Iron Age kings"],correctIndices:[3],explanation:"During the Iron Age, people made the first coins to be minted in Britain, some inscribed with the names of Iron Age kings: marking the beginnings of British history.",visualId:"history-timeline"},{id:"q-ex05-07",examNumber:5,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"boolean",prompt:"Did the Roman Empire ever conquer the whole of Scotland?",options:["Yes","No"],correctIndices:[1],explanation:"No. Although the Romans occupied almost all of Britain after AD 43, areas of what is now Scotland were never conquered by the Romans: which is why Emperor Hadrian built Hadrian’s Wall.",visualId:"history-timeline"},{id:"q-ex05-08",examNumber:5,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"multiple",prompt:"Alongside the Jutes, which TWO other tribes from northern Europe invaded and settled in Britain after the Romans left in AD 410? (Choose TWO)",options:["The Angles","The Picts","The Normans","The Saxons"],correctIndices:[0,3],explanation:"After the Roman army left in AD 410, Britain was invaded by tribes from northern Europe: the Jutes, the Angles, and the Saxons. Their languages formed the basis of modern English, and kingdoms were established by about AD 600.",memoryHook:'Think of the era name "Anglo-Saxon" (left out of the prompt): Angles + Saxons, alongside the Jutes.',visualId:"history-timeline"},{id:"q-ex05-09",examNumber:5,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:'In the north of Britain, the threat of Viking attack encouraged people to unite under one king, and the term "Scotland" began to be used. Who was that king?',options:["Kenneth MacAlpin","Alfred the Great","Robert the Bruce","Harold Godwinson"],correctIndices:[0],explanation:"In the north, the threat of attack by Vikings encouraged the people to unite under one king, Kenneth MacAlpin, and the term Scotland began to be used to describe that country.",memoryHook:'Spot the Gaelic "Mac" prefix: Kenneth MacAlpin united early Scotland against the Vikings (Robert the Bruce fought England centuries later in 1314).',visualId:"history-timeline"},{id:"q-ex05-10",examNumber:5,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"multiple",prompt:"Which TWO huge Welsh castles were built by King Edward I to maintain his power after annexing Wales in 1284? (Choose TWO)",options:["Edinburgh Castle","Conwy Castle","Caernarfon Castle","Windsor Castle"],correctIndices:[1,2],explanation:"After introducing the Statute of Rhuddlan in 1284, Edward I built huge castles to maintain his power in Wales, including Conwy and Caernarfon, many of which are still standing today.",memoryHook:'C + C with Welsh spellings ("w" as a vowel in Conwy, "ae" in Caernarfon) = Edward I’s two Welsh castles.',visualId:"history-timeline"},{id:"q-ex05-11",examNumber:5,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"During the Middle Ages in England, Parliament developed into two Houses. Who sat in the early House of Commons?",options:["Great landowners and senior bishops","Knights and wealthy people from towns and cities","Every adult man and woman in England","Judges appointed by the Pope in Rome"],correctIndices:[1],explanation:"In medieval England, the nobility, great landowners, and bishops sat in the House of Lords, while knights (usually smaller landowners) and wealthy people from towns and cities were elected to sit in the House of Commons.",visualId:"history-timeline"},{id:"q-ex05-12",examNumber:5,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"By AD 1400, after centuries in which monarchs and nobles spoke Norman French and official documents used Latin, which language became the preferred language of the royal court and Parliament in England?",options:["Gaelic","Norman French","Latin","English"],correctIndices:[3],explanation:"By 1400, Norman French and Anglo-Saxon words had blended into Middle English, and official documents were being written in English, which had become the preferred language of the royal court and Parliament.",visualId:"history-timeline"},{id:"q-ex05-13",examNumber:5,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"multiple",prompt:"In 1455, a civil war called the Wars of the Roses began to decide who should be king of England. Which TWO royal houses fought against each other? (Choose TWO)",options:["The House of Lancaster","The House of Stuart","The House of Windsor","The House of York"],correctIndices:[0,3],explanation:"The Wars of the Roses (1455–1485) was fought between the supporters of two families: the House of Lancaster (symbolised by a red rose) and the House of York (symbolised by a white rose).",memoryHook:"Think of England’s northern neighbours, Lancashire vs Yorkshire: House of Lancaster (Red rose, L-R = Left-Right) vs House of York (White rose).",visualId:"history-timeline"},{id:"q-ex05-14",examNumber:5,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"boolean",prompt:"Is there an official established state church in Wales or Northern Ireland?",options:["Yes","No"],correctIndices:[1],explanation:"No. There is no established church in Wales or Northern Ireland (unlike England with the Church of England, and Scotland with its national Presbyterian Church of Scotland)."},{id:"q-ex05-15",examNumber:5,chapterId:"ch4",subtopicId:"ch4-sports",type:"multiple",prompt:"Alongside England, Scotland, Wales, and Ireland, which TWO other European countries compete in the annual Six Nations Rugby Championship? (Choose TWO)",options:["Spain","France","Germany","Italy"],correctIndices:[1,3],explanation:"The most famous rugby union competition is the Six Nations Championship between England, Ireland, Scotland, Wales, France, and Italy."},{id:"q-ex05-16",examNumber:5,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:'Which prestigious golf tournament hosted in the UK is the only "Major" championship held outside the United States?',options:["The Masters","The Ryder Cup","The Open Championship","The PGA Championship"],correctIndices:[2],explanation:'The Open Championship is the only golf "Major" tournament held outside the United States and is hosted by a different British golf course every year.'},{id:"q-ex05-17",examNumber:5,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO of the following famous stage plays were written by William Shakespeare? (Choose TWO)",options:["A Midsummer Night’s Dream","The Mousetrap","Macbeth","Pygmalion"],correctIndices:[0,2],explanation:"Shakespeare’s most famous plays include A Midsummer Night’s Dream, Hamlet, Macbeth, and Romeo and Juliet (whereas Agatha Christie wrote The Mousetrap and George Bernard Shaw wrote Pygmalion)."},{id:"q-ex05-18",examNumber:5,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:'Which Scottish poet, known in Scotland as "The Bard", wrote Auld Lang Syne and is celebrated with haggis and poetry on 25 January?',options:["John Barbour","Thomas Hardy","Robert Louis Stevenson","Robert Burns"],correctIndices:[3],explanation:'Robert Burns (1759–1796), known in Scotland as "The Bard", wrote in Scots and English; his best-known work is Auld Lang Syne (sung at New Year), and Scots celebrate Burns Night every 25 January.'},{id:"q-ex05-19",examNumber:5,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"After a UK General Election, whom does King Charles III invite to become Prime Minister and form His Majesty’s Government?",options:["The MP who won the largest personal vote in a single town","The Speaker of the House of Commons","The leader of the political party with a majority of MPs in the House of Commons","The longest-serving peer in the House of Lords"],correctIndices:[2],explanation:"The Monarch appoints as Prime Minister the leader of the political party that wins a majority of seats in the House of Commons at a General Election (or can command a majority through a coalition).",visualId:"parliament-courts"},{id:"q-ex05-20",examNumber:5,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"What does each of the 650 MPs in the House of Commons represent?",options:["One parliamentary constituency","An entire historic county","Only the people who voted for their political party","A trade union or business guild"],correctIndices:[0],explanation:"Each MP represents a parliamentary constituency (a small geographical area of the country) and has a duty to represent EVERYONE in their constituency: whether they voted for that MP or not!",visualId:"parliament-courts"},{id:"q-ex05-21",examNumber:5,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"multiple",prompt:"Members of the House of Lords (known as peers) are not elected by the public. Which TWO of the following groups sit in the House of Lords? (Choose TWO)",options:["Life peers appointed by the Monarch on the Prime Minister’s advice","Local Police and Crime Commissioners","26 senior bishops of the Church of England","Members of the Scottish Youth Parliament"],correctIndices:[0,2],explanation:"The House of Lords comprises life peers (appointed for their lifetime for achievements and expertise), 26 senior bishops of the Church of England, and a small number of hereditary peers.",visualId:"parliament-courts"},{id:"q-ex05-22",examNumber:5,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:'What is the role of party "Whips" in the UK Parliament?',options:["To guard the entrances to the Palace of Westminster","To write the official Hansard transcripts of speeches","To maintain party discipline and ensure MPs attend and vote as their party leadership wishes","To count ballot papers at local polling stations"],correctIndices:[2],explanation:'Both the government and opposition parties appoint MPs and peers called "Whips" to maintain discipline within their party and ensure members attend key parliamentary votes.',memoryHook:'Word origin: "Whip" comes from the hunting term "whipper-in", who keeps the pack from straying, just as party Whips keep MPs in line for votes.',visualId:"parliament-courts"},{id:"q-ex05-23",examNumber:5,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:'Who appoints the "Shadow Cabinet" and what is its purpose?',options:["The Monarch appoints it to manage Royal Palaces","The Leader of the Opposition appoints senior opposition MPs to challenge government ministers and put forward alternative policies","The Speaker appoints it to chair select committees secretly","The Supreme Court appoints it to review criminal sentences"],correctIndices:[1],explanation:'The second-largest party in the House of Commons is called the Opposition. The Leader of the Opposition leads the party, points out what they see as the government’s failures, and appoints senior opposition MPs to the "Shadow Cabinet".',memoryHook:'Think "mirroring", not secrecy: each Shadow minister shadows (matches one-for-one) a government Cabinet minister to challenge their department.',visualId:"parliament-courts"},{id:"q-ex05-24",examNumber:5,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO of the following are Criminal offences in the UK rather than Civil disputes? (Choose TWO)",options:["Carrying a weapon in public","A disagreement over money owed to a builder","Faulty goods bought online from a shop","Selling tobacco to anyone under the age of 18"],correctIndices:[0,3],explanation:"Carrying a weapon, selling tobacco or alcohol to someone under 18, smoking in enclosed public places, and drinking and driving are criminal offences. Debt and faulty consumer goods are civil law matters.",visualId:"parliament-courts"},{id:"q-ex06-01",examNumber:6,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"True or False: Under UK law, women and men have equal rights to work, own property, marry, divorce, and protection from unfair discrimination.",options:["True","False"],correctIndices:[0],explanation:"True! UK law protects equal rights for men and women and prohibits unfair discrimination based on sex, age, race, religion, disability, marital status, or sexual orientation."},{id:"q-ex06-02",examNumber:6,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"multiple",prompt:"If you apply to settle in either of these TWO Crown Dependencies, your Life in the UK Test will include local island-specific questions alongside UK questions. Which TWO are they? (Choose TWO)",options:["The Channel Islands","The Isle of Wight","Anglesey","The Isle of Man"],correctIndices:[0,3],explanation:"In the Channel Islands (Jersey and Guernsey) and the Isle of Man, local questions supplement the UK Life in the UK Test. (Note: the Isle of Wight and Anglesey are ordinary parts of England and Wales!).",memoryHook:'Exam trap (Isle of Man vs Isle of Wight): the Isle of Man is "its own man" (a self-governing Crown Dependency alongside the Channel Islands), whereas the Isle of Wight and Anglesey are ordinary parts of England and Wales.',visualId:"uk-map"},{id:"q-ex06-03",examNumber:6,chapterId:"ch2",subtopicId:"ch2-nations",type:"multiple",prompt:"Which TWO of the following are major cities in Scotland? (Choose TWO)",options:["Swansea","Glasgow","Bristol","Aberdeen"],correctIndices:[1,3],explanation:"Major cities in Scotland include Edinburgh (the capital), Glasgow, Aberdeen, and Dundee. Swansea is in Wales, and Bristol is in south-west England.",memoryHook:'Acronym "EGAD" for the handbook’s four main Scottish cities: Edinburgh, Glasgow, Aberdeen, Dundee.',visualId:"uk-map"},{id:"q-ex06-04",examNumber:6,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"Which cross on the Union Flag represents St Andrew, the patron saint of Scotland?",options:["A diagonal white cross on a blue ground","An upright red cross on a white ground","A diagonal red cross on a white ground","A yellow cross on a black ground"],correctIndices:[0],explanation:"The Saltire: the cross of St Andrew, patron saint of Scotland, is a diagonal white cross on a blue ground. (St George is an upright red cross on white; St Patrick is a diagonal red cross on white).",memoryHook:"All Ss: Scotland’s Saltire = Snow-white diagonal X on a Sky-blue background (the only blue background among the three crosses).",visualId:"union-jack"},{id:"q-ex06-05",examNumber:6,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"Which plant is the national emblem of Northern Ireland, traditionally worn on St Patrick’s Day (17 March)?",options:["The Leek","The Thistle","The Tudor Rose","The Shamrock"],correctIndices:[3],explanation:"The Shamrock (a three-leaved plant) is the national flower/emblem associated with Northern Ireland and Ireland, worn on St Patrick’s Day on 17 March.",visualId:"national-emblems"},{id:"q-ex06-06",examNumber:6,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"Around 6,000 years ago, the first farmers arrived in Britain, building houses, tombs, and monuments. Where did the ancestors of these first farmers probably come from?",options:["South-east Europe","Northern Scandinavia","North America","Southern Africa"],correctIndices:[0],explanation:"The first farmers arrived in Britain around 6,000 years ago. The ancestors of these first farmers probably came from south-east Europe, bringing farming and Neolithic monument-building to Britain.",memoryHook:"Farming spread into Europe from the Fertile Crescent (Middle East), entering via the continent’s nearest corner: South-east Europe.",visualId:"history-timeline"},{id:"q-ex06-07",examNumber:6,chapterId:"ch3",subtopicId:"ch3-early-roman",type:"single",prompt:"When did the first Christian communities begin to appear in Britain?",options:["During the Bronze Age (around 2000 BC)","During Julius Caesar’s invasion in 55 BC","During the 3rd and 4th centuries AD under Roman rule","Only after the Norman Conquest in AD 1066"],correctIndices:[2],explanation:"It was during the 3rd and 4th centuries AD: while Britain was part of the Roman Empire, that the first Christian communities began to appear in Britain.",memoryHook:'Eliminate the BC options immediately ("BC" = Before Christ, so Christianity didn’t exist in 2000 BC or 55 BC): the first British Christians appeared under Roman rule in the 3rd and 4th centuries AD.',visualId:"history-timeline"},{id:"q-ex06-08",examNumber:6,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"Which famous Anglo-Saxon poem tells of its hero’s battles against monsters and is still translated into modern English today?",options:["The Canterbury Tales","The Bruce","Paradise Lost","Beowulf"],correctIndices:[3],explanation:"The famous Anglo-Saxon poem Beowulf tells of its hero’s battles against monsters (such as Grendel) and is still translated into modern English.",visualId:"history-timeline"},{id:"q-ex06-09",examNumber:6,chapterId:"ch3",subtopicId:"ch3-anglo-norman",type:"single",prompt:"After the Norman Conquest of 1066, what language did the new ruling class speak, influencing the development of the English language?",options:["Norman French","High German","Classical Greek","Old Norse"],correctIndices:[0],explanation:'Following 1066, Normandy’s ruling noblemen spoke Norman French while peasants continued speaking Anglo-Saxon. Over time the two languages combined into Middle and Modern English (for instance, "park", "beauty", and "cow/beef").',visualId:"history-timeline"},{id:"q-ex06-10",examNumber:6,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:'In medieval Scotland, the Parliament had three Houses known as the "Estates". What were those three Estates?',options:["The knights, the farmers, and the sailors","The lords, the clergy, and the towns","The King, the Cabinet, and the Supreme Court","The Highland clans, the Vikings, and the Normans"],correctIndices:[1],explanation:"While England’s Parliament split into Lords and Commons, in medieval Scotland the Parliament had three Houses called Estates: the lords, the clergy, and the towns.",memoryHook:'Three-word picture, "Lords pray in towns": medieval Scotland’s three Estates were the lords, the clergy, and the towns.',visualId:"history-timeline"},{id:"q-ex06-11",examNumber:6,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"multiple",prompt:"Which TWO major social changes occurred in Britain following the Black Death of 1348? (Choose TWO)",options:["Severe labour shortages allowed peasants to demand higher wages","The feudal system became much stricter and wages fell to zero","New social classes appeared, including owners of large areas of land called the gentry","Everyone abandoned towns permanently and returned to hunter-gathering"],correctIndices:[0,2],explanation:"After one third of the population died in 1348, the smaller population meant less need to grow cereal crops and severe labour shortages: peasants could demand higher wages, feudalism declined, people moved to towns, and new classes like the gentry emerged.",visualId:"history-timeline"},{id:"q-ex06-12",examNumber:6,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"During the Middle Ages in Ireland, what was the name of the area around Dublin that was directly controlled by the English king?",options:["The Danelaw","The Marches","The Pale","Wessex"],correctIndices:[2],explanation:'In the Middle Ages, the English first went to Ireland as troops to help the Irish king and remained to build settlements; by 1200, the English ruled an area around Dublin known as the Pale (giving us the phrase "beyond the pale"!).',visualId:"history-timeline"},{id:"q-ex06-13",examNumber:6,chapterId:"ch3",subtopicId:"ch3-middle-ages",type:"single",prompt:"How was the red-and-white Tudor rose symbol created after the Battle of Bosworth Field in 1485?",options:["King Henry VII of Lancaster married King Richard III’s niece, Elizabeth of York, uniting the two families","Geoffrey Chaucer painted it on the cover of The Canterbury Tales","Edward I combined the Welsh leek with the Scottish thistle","The Pope sent a red-and-white banner to Canterbury"],correctIndices:[0],explanation:"After defeating Richard III in 1485, Henry Tudor (House of Lancaster: red rose) became King Henry VII and married Elizabeth of York (House of York: white rose), uniting the two families under the red-and-white Tudor rose.",visualId:"national-emblems"},{id:"q-ex06-14",examNumber:6,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"boolean",prompt:"True or False: Although the UK is historically a Christian country, everyone has the legal right to choose their own religion or to choose not to practise any religion.",options:["True","False"],correctIndices:[0],explanation:"True. While the UK is historically Christian, people of many faiths (Muslim, Hindu, Sikh, Jewish, Buddhist, and others) and non-religious people live freely in the UK, and everyone has the legal right to follow any religion or none."},{id:"q-ex06-15",examNumber:6,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Where did the game of rugby originate in England in the early 19th century?",options:["Eton College","Harrow School","Rugby School","St Andrews"],correctIndices:[2],explanation:"Rugby originated in England in the early 19th century at Rugby School (in Warwickshire) and is very popular throughout the UK today in two codes with different rules: Rugby Union and Rugby League."},{id:"q-ex06-16",examNumber:6,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Which famous five-day horse-racing event in Berkshire is attended by King Charles III and members of the Royal Family?",options:["The Grand National","Cowes Week","Silverstone Grand Prix","Royal Ascot"],correctIndices:[3],explanation:"Royal Ascot is a prestigious five-day horse-racing meeting in Berkshire attended by members of the Royal Family, famous for both top-class flat racing and spectacular hats."},{id:"q-ex06-17",examNumber:6,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"Who chairs the General Assembly of the Church of Scotland and serves as its leader for one year only?",options:["The Archbishop of York","The Moderator of the General Assembly","The First Minister of Scotland","The Sovereign of the United Kingdom"],correctIndices:[1],explanation:"The chairperson of the General Assembly of the Church of Scotland is the Moderator, who is appointed for one year only and often speaks on behalf of that Church.",memoryHook:'No bishops in Scotland’s Presbyterian Kirk: an Assembly debate is chaired ("moderated") by the Moderator.'},{id:"q-ex06-18",examNumber:6,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Several medieval British cathedrals: such as York Minster, are famous for intricate windows made with which craft to tell stories about the Bible and Christian saints?",options:["Stained glass","Bronze sculpture","Pop art silkscreens","Watercolour frescoes"],correctIndices:[0],explanation:"During the Middle Ages, cathedrals such as Lincoln and York Minster were built, and several had windows of stained glass telling stories about the Bible and Christian saints: the glass in York Minster is a famous example."},{id:"q-ex06-19",examNumber:6,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"boolean",prompt:"As a constitutional Monarch, does King Charles III campaign for political parties or take partisan sides in elections?",options:["Yes","No"],correctIndices:[1],explanation:"No. King Charles III has important ceremonial and constitutional roles, represents the UK internationally, and serves as a focus for national identity and unity, remaining strictly politically neutral above party politics.",visualId:"parliament-courts"},{id:"q-ex06-20",examNumber:6,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:"How often does the Prime Minister normally meet privately with King Charles III to discuss government business while Parliament is in session?",options:["Every morning","Once a week","Once every six months","Only after a General Election"],correctIndices:[1],explanation:"The Monarch has regular meetings with the Prime Minister: normally once a week, and can advise, warn, and encourage the government in strict confidence while all policy decisions are made by the PM and Cabinet.",memoryHook:"Pair the PM’s two weekly appointments: PMQs in the Commons = once a week, and private audience with the King = once a week.",visualId:"parliament-courts"},{id:"q-ex06-21",examNumber:6,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"What is the official London residence and office of the UK Prime Minister?",options:["Buckingham Palace","Clarence House","Windsor Castle","10 Downing Street"],correctIndices:[3],explanation:"The official London home and office of the Prime Minister is 10 Downing Street in Westminster (near the Houses of Parliament), while Chequers is the PM’s country house.",visualId:"parliament-courts"},{id:"q-ex06-22",examNumber:6,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"To be able to vote in a parliamentary or local election in the UK, what must your name be on?",options:["The Domesday Book","The electoral register","Hansard","A jury summons list only"],correctIndices:[1],explanation:"To be able to vote in a parliamentary, devolved, or local election, you must have your name on the electoral register (maintained by your local council electoral registration office and updated every autumn).",visualId:"parliament-courts"},{id:"q-ex06-23",examNumber:6,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"In the UK, does your employer, spouse, or any official have the legal right to force you to reveal how you voted in an election?",options:["Yes","No"],correctIndices:[1],explanation:"No! Voting in the UK is strictly by secret ballot in a private polling booth; no one has the right to know or force you to say how you voted, and you must cast your own vote personally (unless you have arranged a postal or proxy vote).",visualId:"parliament-courts"},{id:"q-ex06-24",examNumber:6,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"What is the primary purpose of Civil Law in the United Kingdom?",options:["To prosecute murder, armed robbery, and treason on behalf of the Crown","To command police patrols at football matches","To settle disputes between individuals or groups, such as housing, consumer rights, debt, or family matters","To elect Members of Parliament to Westminster"],correctIndices:[2],explanation:"Civil law is used to settle disputes between individuals or groups: covering housing law, consumer rights, employment law, family law, and debt claims.",visualId:"parliament-courts"}],t=[{id:"q-ex07-01",examNumber:7,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"You move into a UK street where your neighbours hold very different religious and political views from yours. Which action best reflects the responsibilities of living in the UK?",options:["Insisting that neighbours adopt the majority belief on the street","Respecting their rights and opinions and treating everyone with fairness","Reporting neighbours to the local council for holding different political views","Avoiding all shared community spaces until everyone agrees"],correctIndices:[1],explanation:"Everyone living in the UK shares the responsibility to respect the rights of others, including their opinions and faiths, and to treat fellow residents with fairness to maintain community harmony."},{id:"q-ex07-02",examNumber:7,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"multiple",prompt:"Which TWO of the following may exempt an applicant for UK citizenship or settlement from taking a separate B1 English language speaking and listening test? (Choose TWO)",options:["Holding a qualifying academic degree that was taught or researched in English","Having visited London as a tourist at least three times","Being aged 65 or over at the time of application","Owning a motor vehicle registered in Great Britain"],correctIndices:[0,2],explanation:"Applicants are normally required to prove English at CEFR level B1, unless exempt, for example, citizens of majority English-speaking countries, holders of a qualifying degree taught or researched in English, or applicants aged 65 or over (or with a qualifying long-term physical or mental condition)."},{id:"q-ex07-03",examNumber:7,chapterId:"ch2",subtopicId:"ch2-territories",type:"single",prompt:"What is Tynwald, the parliament of the Isle of Man, famous for being?",options:["The largest parliament building in the European Union","A sub-committee of the Scottish Parliament in Edinburgh","The oldest continuous parliamentary assembly in the world","A court reserved exclusively for maritime piracy trials"],correctIndices:[2],explanation:"The Isle of Man is a Crown Dependency with its own government called Tynwald, which has operated for over a thousand years and is the oldest continuous parliamentary assembly in the world.",memoryHook:'Phonetic link: "Tynwald" sounds like "time-old", matching the world’s oldest continuous parliament.',visualId:"national-emblems"},{id:"q-ex07-04",examNumber:7,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Approximately how far is the longest mainland distance in Great Britain, from John O’Groats on the north coast of Scotland to Land’s End in south-west England?",options:["About 300 miles (480 km)","About 540 miles (870 km)","About 1,250 miles (2,010 km)","About 870 miles (1,400 km)"],correctIndices:[3],explanation:"The longest distance on the mainland of Great Britain, stretching from John O’Groats in northern Scotland to Land’s End in Cornwall, is about 870 miles (approximately 1,400 km).",memoryHook:"Digit pattern: 8-7-0 counts downward from top to bottom (870 miles from John O’Groats down to Land’s End).",visualId:"uk-map"},{id:"q-ex07-05",examNumber:7,chapterId:"ch2",subtopicId:"ch2-territories",type:"multiple",prompt:"Which TWO of the following are Crown Dependencies closely linked to the Crown, with their own governments, rather than being part of the United Kingdom? (Choose TWO)",options:["The Channel Islands (such as Jersey and Guernsey)","Orkney and Shetland","The Isle of Wight","The Isle of Man"],correctIndices:[0,3],explanation:"The Channel Islands and the Isle of Man are Crown Dependencies closely linked to the Crown with their own legislatures and tax systems; unlike the Isle of Wight or Orkney, they are not part of the UK.",memoryHook:'Think "A Man in the Channel": only the Isle of Man and the Channel Islands are Crown Dependencies (Wight and Orkney are part of the UK).',visualId:"national-emblems"},{id:"q-ex07-06",examNumber:7,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Why did King Henry VIII break away from the Church of Rome and establish the Church of England?",options:["The Pope refused to grant him a divorce from his first wife, Catherine of Aragon","He wanted to abolish the monarchy and create a Protestant republic","Spain invaded Kent and forced England to adopt a new Bible","Parliament voted to merge the English Church with the Kirk of Scotland"],correctIndices:[0],explanation:"To secure a male heir, Henry VIII wanted to divorce Catherine of Aragon and marry Anne Boleyn. When the Pope refused, Henry broke away from Rome and established the Church of England with the monarch as head.",visualId:"history-timeline"},{id:"q-ex07-07",examNumber:7,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Which of King Henry VIII’s six wives was his last wife and survived him?",options:["Jane Seymour","Anne of Cleves","Catherine Parr","Catherine Howard"],correctIndices:[2],explanation:'Catherine Parr was a widow who married Henry VIII late in his life; Henry died before her, making her the "survived" in the famous rhyme of his six wives.',memoryHook:'Six-wives rhyme: "Divorced, Beheaded, Died, Divorced, Beheaded, Survived." Wife #6, Catherine Parr, beat the par and outlived Henry.'},{id:"q-ex07-08",examNumber:7,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"What major naval victory occurred in 1588 during the reign of Queen Elizabeth I?",options:["Admiral Nelson defeated France at the Battle of Trafalgar","The English fleet defeated the Spanish Armada sent to conquer England","Francis Drake captured New York from the Dutch fleet","Henry V sank the French navy before the Battle of Agincourt"],correctIndices:[1],explanation:"In 1588, Protestant England under Elizabeth I defeated the Spanish Armada, a large fleet of ships sent by Catholic Spain to invade England and restore Catholicism.",visualId:"history-timeline"},{id:"q-ex07-09",examNumber:7,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"boolean",prompt:"When King James VI of Scotland became King James I of England in 1603, Scotland and England immediately merged into one single country with one shared Parliament.",options:["True","False"],correctIndices:[1],explanation:'1603 was the "Union of the Crowns": one monarch ruled both realms, but Scotland and England remained separate countries with their own parliaments for another 104 years until the 1707 Act of Union.'},{id:"q-ex07-10",examNumber:7,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Under which monarch was the Act of Union in 1707 agreed, uniting England (with Wales) and Scotland into the Kingdom of Great Britain?",options:["Queen Elizabeth I","Queen Victoria","King George III","Queen Anne"],correctIndices:[3],explanation:"Queen Anne had no surviving children, creating uncertainty over the succession in Scotland and England. During her reign, the Act of Union in 1707 created the Kingdom of Great Britain.",memoryHook:'Rhyme: "In 1707, Queen Anne had a plan to unite Scot and Englishman."',visualId:"history-timeline"},{id:"q-ex07-11",examNumber:7,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Who served from 1721 to 1742 and is regarded as the first Prime Minister in British history?",options:["Sir Robert Walpole","Oliver Cromwell","William Wilberforce","The Duke of Wellington"],correctIndices:[0],explanation:"Because the Hanoverian King George I spoke very little English, he relied heavily on his ministers; the most important minister in Parliament became known as the Prime Minister, beginning with Sir Robert Walpole (1721–1742).",memoryHook:"Wal-POLE took pole position as #1 Prime Minister, and his dates double neatly: 1721 to 1742 (21 x 2 = 42)."},{id:"q-ex07-12",examNumber:7,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"During the 18th-century Scottish Enlightenment, what field did Adam Smith famously develop ideas about?",options:["Steam locomotive engineering","Modern nursing and hospital hygiene","Economics","Pre-Raphaelite landscape painting"],correctIndices:[2],explanation:"Adam Smith was a leading thinker of the Scottish Enlightenment who developed influential ideas about economics (such as in The Wealth of Nations) that are still referred to today.",memoryHook:"Scottish Enlightenment trio: Adam Smith = Economics (wealth), David Hume = Human nature (philosophy), James Watt = Steam power (watts)."},{id:"q-ex07-13",examNumber:7,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"What landmark business did Bengal-born Sake Dean Mahomed open on George Street in London in 1810?",options:["Britain’s first mechanized cotton spinning mill","The Hindoostane Coffee House, the first curry house to open in Britain","The first daily newspaper printing office on Fleet Street","The first maritime insurance exchange for steamships"],correctIndices:[1],explanation:"Sake Dean Mahomed came to Britain in 1782 and in 1810 opened the Hindoostane Coffee House on George Street, London, the very first curry house in Britain."},{id:"q-ex07-14",examNumber:7,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:'Diwali, the Hindu and Sikh "Festival of Lights", is celebrated across the UK in October or November. Which English city is especially famous for its huge Diwali celebrations?',options:["Norwich","Plymouth","Leicester","Carlisle"],correctIndices:[2],explanation:"Diwali normally falls in October or November and lasts for five days; there is a famous celebration in Leicester that is one of the largest outside India.",memoryHook:"Alliteration: Festival of Lights = Leicester (both start with L)."},{id:"q-ex07-15",examNumber:7,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"boolean",prompt:"On April Fool’s Day (1 April), people in the UK traditionally play jokes on one another only until 12:00 noon.",options:["True","False"],correctIndices:[0],explanation:"In the UK, April Fool’s Day jokes and misleading media stories are traditionally played only until midday (12:00 noon) on 1 April."},{id:"q-ex07-16",examNumber:7,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Which British athlete won gold medals in rowing in five consecutive Olympic Games and is considered one of Britain’s greatest Olympians?",options:["Sir Steve Redgrave","Sir Roger Bannister","Sir Jackie Stewart","Christopher Dean"],correctIndices:[0],explanation:"Sir Steve Redgrave won gold medals in rowing at five consecutive Olympic Games (from 1984 to 2000) and is celebrated as one of Britain’s greatest Olympic athletes.",memoryHook:"Alliteration: R for Redgrave = R for Rowing (gold at 5 straight Olympics)."},{id:"q-ex07-17",examNumber:7,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"What sporting achievement made Dame Ellen MacArthur famous in 2004?",options:["Winning double gold in the 800m and 1500m Olympic track finals","Becoming the fastest person to sail around the world single-handed","Captaining the British Olympic ice-dancing team","Winning six Paralympic wheelchair marathons in London"],correctIndices:[1],explanation:"Dame Ellen MacArthur is a British yachtswoman who in 2004 became the fastest person to sail around the world single-handed (solo).",memoryHook:"Solo-sailing trio trap: Francis Chichester = first with one stop (1967); Robin Knox-Johnston = first non-stop (1969); Ellen MacArthur = fastest (2004)."},{id:"q-ex07-18",examNumber:7,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO British poets were inspired by their experiences in the First World War to write moving poems about the realities of war? (Choose TWO)",options:["Wilfred Owen","Lord Byron","William Blake","Siegfried Sassoon"],correctIndices:[0,3],explanation:"Wilfred Owen (who wrote Anthem for Doomed Youth) and Siegfried Sassoon were both First World War soldiers whose poetry vividly portrayed the human cost of the trenches, whereas Blake and Byron lived a century earlier.",memoryHook:'Rhyme: "Owen and Sassoon in the WWI platoon" (Blake and Byron were Romantic poets a century earlier).'},{id:"q-ex07-19",examNumber:7,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"How many elected Members of the Scottish Parliament (MSPs) sit in the Scottish Parliament in Edinburgh?",options:["60 MSPs","90 MSPs","129 MSPs","650 MSPs"],correctIndices:[2],explanation:"The Scottish Parliament sits at Holyrood in Edinburgh and has 129 Members of the Scottish Parliament (MSPs), elected by a form of proportional representation.",memoryHook:"Climb north up the map as seats grow: Cardiff (south) = 60, Belfast (mid) = 90, Edinburgh (north) = 129.",visualId:"parliament-courts"},{id:"q-ex07-20",examNumber:7,chapterId:"ch5",subtopicId:"ch5-devolution",type:"multiple",prompt:'Which TWO policy areas remain "reserved" under the control of the central UK Parliament in Westminster rather than devolved administrations? (Choose TWO)',options:["Defence","Primary and secondary school curricula","Local hospital management","Foreign affairs"],correctIndices:[0,3],explanation:"Policy and laws governing defence, foreign affairs, immigration, taxation, and social security remain under central UK Parliament control, whereas education and health are devolved.",visualId:"parliament-courts"},{id:"q-ex07-21",examNumber:7,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:'What is the role of the "Shadow Cabinet" in the UK Parliament?',options:["Senior civil servants who draft tax budgets in secret before election day","Senior opposition MPs appointed by the Leader of the Opposition to challenge the government and propose alternative policies","Judges of the UK Supreme Court who review bills before Royal Assent","Backbench MPs from the governing party who count votes in Commons lobbies"],correctIndices:[1],explanation:"The Leader of the Opposition (head of the second-largest party in the House of Commons) appoints senior opposition MPs to the Shadow Cabinet to scrutinise Cabinet ministers and put forward alternative policies.",visualId:"parliament-courts"},{id:"q-ex07-22",examNumber:7,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"Proceedings in Parliament are published in official reports called Hansard, which the public can read for free online and in large libraries.",options:["True","False"],correctIndices:[0],explanation:"Parliamentary debates in both Houses are broadcast on television and published verbatim in official reports known as Hansard, available free online and in reference libraries.",memoryHook:'Sound link: "Hansard" sounds like "hands hard" writing down every word spoken in Parliament.'},{id:"q-ex07-23",examNumber:7,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"Who is the ceremonial Head of the 56-member Commonwealth of Nations?",options:["The Secretary-General of the United Nations","The UK Prime Minister","His Majesty King Charles III","The Speaker of the House of Commons"],correctIndices:[2],explanation:"The Commonwealth is a voluntary association of 56 independent states (mostly former territories of the British Empire), and His Majesty King Charles III serves as its ceremonial Head."},{id:"q-ex07-24",examNumber:7,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"In the UK, people aged 16 and 17 are legally permitted to buy National Lottery tickets and scratchcards.",options:["True","False"],correctIndices:[1],explanation:"You must be aged 18 or over to participate in the National Lottery (including Lotto tickets and scratchcards) in the UK; those under 18 are barred from gambling products.",memoryHook:"Outdated-notes trap: Older study guides say 16, but the National Lottery minimum age was raised to 18 (matching voting age)."},{id:"q-ex08-01",examNumber:8,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"Which TWO of the following practices are serious criminal offences in the UK, even if someone claims they are part of a cultural tradition? (Choose TWO)",options:["Forced marriage","Having an arranged marriage where both adults freely consent","Female genital mutilation (FGM)","Choosing to affirm rather than swear in court"],correctIndices:[0,2],explanation:"Forced marriage (where one or both parties do not or cannot consent) and female genital mutilation (FGM, including taking a girl abroad for FGM) are completely unacceptable and are criminal offences in the UK."},{id:"q-ex08-02",examNumber:8,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"Samir does not hold any religious beliefs and is attending his British citizenship ceremony. What can he choose to make instead of swearing a religious Oath of Allegiance?",options:["A written petition to the Privy Council","An Affirmation of Allegiance","A statutory tax declaration","A silent bow before the local Mayor without speaking"],correctIndices:[1],explanation:'At a citizenship ceremony, those who do not wish to swear a religious oath ("I swear by Almighty God...") may make a non-religious Affirmation of Allegiance ("I do solemnly, sincerely and truly declare and affirm...") before speaking the Pledge.',memoryHook:"A for Affirmation = Atheist/Agnostic option (non-religious declaration, whereas the Oath swears by Almighty God)."},{id:"q-ex08-03",examNumber:8,chapterId:"ch2",subtopicId:"ch2-territories",type:"boolean",prompt:"Northern Ireland and Scotland have their own banknotes which are valid everywhere in the UK, although shops are not legally obliged to accept them.",options:["True","False"],correctIndices:[0],explanation:"Certain banks in Scotland and Northern Ireland issue their own Pound Sterling banknotes. They are valid currency across the UK, even though shops and businesses do not have a strict legal obligation to accept them."},{id:"q-ex08-04",examNumber:8,chapterId:"ch2",subtopicId:"ch2-nations",type:"multiple",prompt:"Which TWO of the following UK cities are located in Scotland? (Choose TWO)",options:["Swansea","Aberdeen","Dundee","Lisburn"],correctIndices:[1,2],explanation:"Edinburgh (the capital), Glasgow, Aberdeen, and Dundee are major cities in Scotland. Swansea is in Wales, and Lisburn is in Northern Ireland.",memoryHook:"Acronym AGED for Scotland’s four handbook cities: Aberdeen, Glasgow, Edinburgh, Dundee.",visualId:"uk-map"},{id:"q-ex08-05",examNumber:8,chapterId:"ch2",subtopicId:"ch2-territories",type:"single",prompt:"Which of the following is a British Overseas Territory located in the South Atlantic Ocean rather than being part of the United Kingdom itself?",options:["Guernsey","Anglesey","The Hebrides","The Falkland Islands"],correctIndices:[3],explanation:"The Falkland Islands (like Gibraltar and St Helena) are a British Overseas Territory linked to the UK, not part of it. Anglesey is in Wales, the Hebrides are in Scotland, and Guernsey is a Crown Dependency.",memoryHook:'Geography rule: Distant ocean territories (Falklands, St Helena, Gibraltar) are Overseas Territories ("over the seas"); islands right beside Britain (Channel Islands, Isle of Man) are Crown Dependencies.'},{id:"q-ex08-06",examNumber:8,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"multiple",prompt:"Which TWO of King Henry VIII’s six wives were executed? (Choose TWO)",options:["Catherine of Aragon","Anne Boleyn","Anne of Cleves","Catherine Howard"],correctIndices:[1,3],explanation:"Henry VIII’s second wife, Anne Boleyn (mother of Elizabeth I), and his fifth wife, Catherine Howard (Anne Boleyn’s cousin), were both accused of treasonous adultery and executed.",memoryHook:'Six-wives rhyme: "Divorced, Beheaded (#2), Died, Divorced, Beheaded (#5), Survived" points to #2 Anne Boleyn and #5 Catherine Howard (cousins).'},{id:"q-ex08-07",examNumber:8,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"During the reign of which Tudor monarch was Wales formally united with England under the Acts for the Government of Wales?",options:["Henry VIII","Mary I","Richard III","James I"],correctIndices:[0],explanation:"During Henry VIII’s reign, Wales became formally united with England under the Acts for the Government of Wales; the Welsh sent representatives to the House of Commons and the Welsh legal system was reformed.",memoryHook:"Exam trap: Edward I annexed Wales militarily in 1284 (Statute of Rhuddlan), whereas Henry VIII formally united Wales with England in Parliament."},{id:"q-ex08-08",examNumber:8,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Sir Francis Drake, one of the commanders who fought the Spanish Armada, is also famous because his ship, the Golden Hind, achieved what feat?",options:["It carried the first steam engine across the Atlantic to New York","It was one of the first ships to sail right around (circumnavigate) the world","It rescued King Charles II during the Restoration of 1660","It transported the stones of Stonehenge up the River Thames"],correctIndices:[1],explanation:"Elizabethan sailor Sir Francis Drake helped defeat the Spanish Armada and sailed the Golden Hind, one of the first ships to sail completely around the world."},{id:"q-ex08-09",examNumber:8,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"What was the Gunpowder Plot of November 1605?",options:["A Viking raid that burned down Westminster Abbey","A plan by Oliver Cromwell to abolish Christmas celebrations","A failed plot by a group of Catholics led by Guy Fawkes to blow up the King in Parliament","An uprising by Scottish Jacobites at the Battle of Culloden"],correctIndices:[2],explanation:"In 1605, a group of Catholics led by Guy Fawkes failed in their secret plan to blow up the Protestant King James I and the Houses of Parliament with barrels of gunpowder.",memoryHook:'Digit anchor: 5 November 1605 has a 5 in the date and a 5 at the end of the year ("Remember, remember the 5th of November").',visualId:"history-timeline"},{id:"q-ex08-10",examNumber:8,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:'At which 1746 battle was Charles Edward Stuart ("Bonnie Prince Charlie"), supported by Scottish clansmen, defeated by King George II’s army?',options:["The Battle of Bannockburn","The Battle of Bosworth Field","The Battle of Marston Moor","The Battle of Culloden"],correctIndices:[3],explanation:"In 1745 there was another attempt to put a Stuart king back on the throne; Charles Edward Stuart (Bonnie Prince Charlie) was defeated by George II’s army at the Battle of Culloden in 1746 and fled to Europe.",memoryHook:"Alliteration C-C-C: Bonnie Prince Charlie and his Clansmen were defeated at Culloden (1746), unlike Bruce at Bannockburn (1314).",visualId:"history-timeline"},{id:"q-ex08-11",examNumber:8,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which Scottish pioneer of the Enlightenment and Industrial Revolution made crucial improvements to steam power that helped drive factory machinery and railways?",options:["James Watt","Sir Alexander Fleming","John Logie Baird","Robert Adam"],correctIndices:[0],explanation:"James Watt’s work on steam power during the 18th-century Scottish Enlightenment accelerated the Industrial Revolution by providing reliable power for factories, mines, and later transport.",memoryHook:'Think of the unit of power named after him, the "watt": James Watt supercharged steam power.'},{id:"q-ex08-12",examNumber:8,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"What did the Slave Trade Act of 1807 make illegal?",options:["Owning enslaved people anywhere in North or South America","Trading enslaved people in British ships or from British ports","Importing sugar or cotton from outside the Commonwealth","Employing children under 18 in Yorkshire coal mines"],correctIndices:[1],explanation:"In 1807, it became illegal to trade slaves in British ships or from British ports. Slavery itself throughout the British Empire was later abolished completely by the Emancipation Act of 1833.",memoryHook:'Two-date trap: 1807 banned the slave TRADE (ships and ports); 1833 abolished SLAVERY itself across the Empire ("three-three set them free").'},{id:"q-ex08-13",examNumber:8,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:'Alongside opening Britain’s first curry house, Sake Dean Mahomed and his Irish wife Jane Daly introduced "shampooing": the Indian art of head massage, to Britain.',options:["True","False"],correctIndices:[0],explanation:'Sake Dean Mahomed eloped with Irishwoman Jane Daly in 1786, returned to England, opened the Hindoostane Coffee House in 1810, and also introduced "shampooing" (Indian therapeutic head massage) to Britain.'},{id:"q-ex08-14",examNumber:8,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"What does the Muslim festival of Eid al-Fitr celebrate?",options:["The prophet Ibrahim’s willingness to sacrifice his son","The end of Ramadan, when Muslims have fasted for a month","An eight-day winter festival of candle lighting","The spring harvest on 14 April"],correctIndices:[1],explanation:"Eid al-Fitr celebrates the end of Ramadan, when Muslims have fasted for a month and thank Allah for giving them the strength to complete the fast.",memoryHook:"Letter link for the two Eids: F in Fitr = Fasting Finishes (end of Ramadan); A in Adha = Abraham/Ibrahim’s willingness to sacrifice."},{id:"q-ex08-15",examNumber:8,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"Which Sikh festival is celebrated on 14 April each year with parades, dancing, and singing to mark the founding of the Sikh community known as the Khalsa?",options:["Hanukkah","Hogmanay","Vaisakhi","Ash Wednesday"],correctIndices:[2],explanation:"Vaisakhi is a Sikh festival that celebrates the founding of the Sikh community known as the Khalsa and is celebrated on 14 April each year.",memoryHook:"Spelling link: Vai-S-a-KH-i contains the consonants S-K-H right inside it, matching the Sikh festival on 14 April."},{id:"q-ex08-16",examNumber:8,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"What Olympic triumph did Dame Kelly Holmes achieve at the 2004 Games?",options:["Winning gold in the women’s heptathlon in London","Winning five consecutive rowing gold medals","Winning two gold medals for running (800m and 1500m)","Winning mixed doubles lawn tennis gold at Wimbledon"],correctIndices:[2],explanation:"Dame Kelly Holmes won two Olympic gold medals for middle-distance running, in both the 800 metres and 1,500 metres, at the 2004 Athens Olympic Games.",memoryHook:'H is the 8th letter of the alphabet: Holmes won the 800m (and 1,500m) middle-distance double, whereas Mo "Far-ah" won the far 5,000m and 10,000m.'},{id:"q-ex08-17",examNumber:8,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"In 2012, Sir Bradley Wiggins became the first Briton to win which prestigious sporting event?",options:["The Formula 1 World Championship","The Men’s Singles title at Wimbledon","The Open Golf Championship at St Andrews","The Tour de France"],correctIndices:[3],explanation:"In 2012, cyclist Sir Bradley Wiggins became the very first Briton to win the gruelling Tour de France road race, as well as winning Olympic time-trial gold at London 2012.",memoryHook:"British cycling split: Bradley Wiggins = first Briton to win the road Tour de France (2012); Chris Hoy = 6 Olympic golds on the indoor track."},{id:"q-ex08-18",examNumber:8,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which Welsh poet and writer is best known for his play Under Milk Wood and the poem Do Not Go Gentle into That Good Night?",options:["Dylan Thomas","Robert Burns","John Barbour","Thomas Hardy"],correctIndices:[0],explanation:"Swansea-born Welsh poet Dylan Thomas (1914–1953) often read and performed his work in public; among his most famous works are Under Milk Wood (first performed after his death in 1954) and Do Not Go Gentle into That Good Night."},{id:"q-ex08-19",examNumber:8,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"How many elected Members of the Senedd (MSs) sit in Senedd Cymru (the Welsh Parliament) in Cardiff?",options:["60 members","90 members","129 members","200 members"],correctIndices:[0],explanation:"Senedd Cymru (the Welsh Parliament), based in Cardiff, has 60 elected members (MSs) and exercises devolved legislative powers over matters such as education, health, agriculture, and the Welsh language.",memoryHook:"Climb north up the map as seats grow: Cardiff Senedd = 60, Belfast Stormont = 90, Edinburgh Holyrood = 129.",visualId:"parliament-courts"},{id:"q-ex08-20",examNumber:8,chapterId:"ch5",subtopicId:"ch5-devolution",type:"boolean",prompt:"Members of the Scottish Parliament, the Senedd in Wales, and the Northern Ireland Assembly are all elected using forms of proportional representation rather than First Past the Post.",options:["True","False"],correctIndices:[0],explanation:"While UK General Elections to the Westminster House of Commons use First Past the Post, the devolved legislatures in Edinburgh, Cardiff, and Belfast all use forms of proportional representation so seats closely reflect party vote shares.",visualId:"parliament-courts"},{id:"q-ex08-21",examNumber:8,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:'In the UK Parliament, what is the role of party "Whips"?',options:["Ceremonial guards who lock the gates of the Tower of London each night","MPs or peers appointed by party leaders to maintain party discipline and ensure attendance for parliamentary votes","Independent election officials who count ballot papers at local town halls","Clerks who read bills aloud to the Monarch before Royal Assent"],correctIndices:[1],explanation:'Each major political party appoints "Whips" in the House of Commons and House of Lords to organise party business, ensure MPs or peers attend key votes, and encourage them to vote along party lines.',visualId:"parliament-courts"},{id:"q-ex08-22",examNumber:8,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"After a General Election, a different political party wins a majority and forms a new UK Government. What happens to career civil servants working in government ministries?",options:["They are all dismissed and replaced by members of the winning political party","They must stand for confirmation in local council by-elections","They remain in post and serve the new elected government impartially, as civil servants are politically neutral","They transfer automatically to the Shadow Cabinet"],correctIndices:[2],explanation:"Civil servants in the UK are appointed on merit, are politically neutral, and are bound by core values of integrity, honesty, objectivity, and impartiality, continuing to carry out government policy regardless of which party is elected."},{id:"q-ex08-23",examNumber:8,chapterId:"ch5",subtopicId:"ch5-devolution",type:"boolean",prompt:"When the United Kingdom left the European Union in January 2020, it also ceased to be a member of the Council of Europe.",options:["True","False"],correctIndices:[1],explanation:"The Council of Europe is completely separate from the European Union. The UK remains a founding and active member of the Council of Europe, which drafted the European Convention on Human Rights."},{id:"q-ex08-24",examNumber:8,chapterId:"ch5",subtopicId:"ch5-devolution",type:"multiple",prompt:"The UK is one of five permanent members of the 15-member United Nations Security Council. Alongside Russia and China, which TWO other countries are permanent members? (Choose TWO)",options:["Germany","The United States","Japan","France"],correctIndices:[1,3],explanation:"The UN Security Council recommends action during international crises and crises threatening peace. There are 15 members in total, including five permanent members: the UK, the USA, France, Russia, and China.",memoryHook:"Think WWII Allied victors: the 5 permanent seats belong to the UK, USA, France, Russia, and China (never WWII Axis powers Germany or Japan)."},{id:"q-ex09-01",examNumber:9,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"Which of the following is NOT one of the shared responsibilities of everyone living in the UK?",options:["Respecting and obeying the law","Looking after yourself and your family","Joining a registered political party","Looking after the area in which you live and the environment"],correctIndices:[2],explanation:"Residents are expected to obey the law, respect others’ rights, treat others fairly, care for themselves and their families, and look after their local area and environment. Joining a political party is completely voluntary."},{id:"q-ex09-02",examNumber:9,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"boolean",prompt:"If you apply for settlement or citizenship in the Channel Islands or the Isle of Man, the Knowledge of Life in the UK test includes local island-specific questions.",options:["True","False"],correctIndices:[0],explanation:"Because Jersey, Guernsey, and the Isle of Man are self-governing Crown Dependencies with their own institutions and history, applicants there sit a version of the test that includes local island-specific questions."},{id:"q-ex09-03",examNumber:9,chapterId:"ch2",subtopicId:"ch2-nations",type:"boolean",prompt:"In Wales, many people speak Welsh, a completely different Celtic language from English, which is taught in schools and universities and appears alongside English on road signs and official documents.",options:["True","False"],correctIndices:[0],explanation:"Welsh is an ancient Celtic language distinct from English; in Wales, public signs and official documents are bilingual in Welsh and English, and Welsh is widely taught in schools and universities."},{id:"q-ex09-04",examNumber:9,chapterId:"ch2",subtopicId:"ch2-territories",type:"single",prompt:"Which of the following coin denominations is NOT part of UK Pound Sterling (£) currency?",options:["20p","25p","50p","£2"],correctIndices:[1],explanation:'Official UK circulating coins are 1p, 2p, 5p, 10p, 20p, 50p, £1, and £2. Unlike US/Canadian "quarters", there is no standard circulating 25p coin.',memoryHook:"1-2-5 pattern: Every standard UK coin and banknote begins with 1, 2, or 5 (1p, 2p, 5p; 10p, 20p, 50p; £1, £2; £5, £10, £20, £50), never 25!"},{id:"q-ex09-05",examNumber:9,chapterId:"ch2",subtopicId:"ch2-nations",type:"multiple",prompt:"Alongside its capital Cardiff, which TWO of the following cities are in Wales? (Choose TWO)",options:["Swansea","Dundee","Newport","Southampton"],correctIndices:[0,2],explanation:"Cardiff, Swansea, and Newport are key cities in south Wales. Dundee is in Scotland, and Southampton is on the south coast of England.",visualId:"uk-map"},{id:"q-ex09-06",examNumber:9,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"During the reign of Henry VIII’s strongly Protestant son, King Edward VI, what famous text was written to be used in the Church of England?",options:["The Domesday Book","The Book of Common Prayer","The Canterbury Tales","Magna Carta"],correctIndices:[1],explanation:"Edward VI was strongly Protestant; during his short reign, Archbishop Thomas Cranmer wrote the Book of Common Prayer to be used in English church services, a version of which is still used in some churches today.",memoryHook:"Royal church-text trap: Edward VI = Book of Common Prayer; James I = King James Version of the Bible."},{id:"q-ex09-07",examNumber:9,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:'Why did Tudor monarch Queen Mary I become known as "Bloody Mary"?',options:["She led English troops personally at the Battle of Bosworth Field","She introduced gruesome surgical theatres to London hospitals","She was a devout Catholic who persecuted Protestants during her reign","She executed her cousin Mary, Queen of Scots, at Fotheringhay"],correctIndices:[2],explanation:'Queen Mary I (daughter of Henry VIII and Catherine of Aragon) was a devout Catholic who sought to reverse the Protestant Reformation and persecuted Protestants, earning her the nickname "Bloody Mary".',memoryHook:'Tudor faith pendulum: Edward VI (Protestant) -> Mary I (Catholic, persecuted Protestants = "Bloody Mary") -> Elizabeth I (Protestant).'},{id:"q-ex09-08",examNumber:9,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"multiple",prompt:"Which TWO of the following famous plays were written by William Shakespeare? (Choose TWO)",options:["A Midsummer Night’s Dream","The Hound of the Baskervilles","Macbeth","Pride and Prejudice"],correctIndices:[0,2],explanation:"Playwright and poet William Shakespeare (1564–1616) wrote A Midsummer Night’s Dream, Macbeth, Hamlet, and Romeo and Juliet. Pride and Prejudice is by Jane Austen, and The Hound of the Baskervilles is by Sir Arthur Conan Doyle."},{id:"q-ex09-09",examNumber:9,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"When civil war broke out between King Charles I and Parliament in 1642, what were the two opposing sides called?",options:["Lancastrians and Yorkists","Suffragists and Chartists","Jacobites and Hanoverians","Cavaliers (supporting the King) and Roundheads (supporting Parliament)"],correctIndices:[3],explanation:"The English Civil War began in 1642 and split the country into those who supported King Charles I (the Cavaliers) and those who supported Parliament (the Roundheads).",memoryHook:"Alliteration C-C-C: Cavaliers fought for Charles and the Crown; Roundheads (short-cropped hair) fought for Parliament.",visualId:"history-timeline"},{id:"q-ex09-10",examNumber:9,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"What area of thought was Scottish Enlightenment figure David Hume especially famous for?",options:["Philosophy, particularly ideas about human nature","Designing suspension bridges and ocean steamships","Discovering penicillin mould in London","Writing operas for King George I on the River Thames"],correctIndices:[0],explanation:"David Hume was a major thinker of the 18th-century Scottish Enlightenment whose philosophical ideas about human nature continue to influence philosophers around the world.",memoryHook:"Name link: David HUME = HUMAN nature (Scottish Enlightenment philosophy)."},{id:"q-ex09-11",examNumber:9,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Originally trained as a barber and wig-maker, how did Richard Arkwright transform British industry in the late 18th century?",options:["He invented the jet engine for high-altitude flight","He improved the carding machine, ran efficient spinning mills, and pioneered modern factory management","He built the Channel Tunnel between Kent and France","He discovered the structure of the DNA molecule"],correctIndices:[1],explanation:"Richard Arkwright began working in textiles when wigs went out of fashion; he improved the carding machine (preparing fibres for spinning), used horse and then steam power in mills, and is remembered for efficient, profitable factory management."},{id:"q-ex09-12",examNumber:9,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"In which year did the Emancipation Act abolish slavery throughout the British Empire?",options:["1776","1801","1833","1885"],correctIndices:[2],explanation:"Following decades of campaigning by Quakers and William Wilberforce, the Emancipation Act of 1833 abolished slavery throughout the British Empire, and the Royal Navy patrolled the seas to stop slave ships from other nations.",memoryHook:'Date rhyme: "1833, three-three sets the Empire free" (whereas 1807 only banned the slave trade on British ships).',visualId:"history-timeline"},{id:"q-ex09-13",examNumber:9,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"What did the Act of Union of 1800 (which took effect in 1801) create?",options:["The European Economic Community","The Commonwealth of Nations","The Principality of Wales","The United Kingdom of Great Britain and Ireland"],correctIndices:[3],explanation:"In 1801, Ireland became unified with England, Scotland, and Wales under the Act of Union of 1800, creating the United Kingdom of Great Britain and Ireland.",memoryHook:"Union timeline: 1603 = Union of Crowns; 1707 = Kingdom of Great Britain (+ Scotland); 1801 = United Kingdom of Great Britain and Ireland (+ Ireland).",visualId:"history-timeline"},{id:"q-ex09-14",examNumber:9,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"For how many days is the Jewish festival of Hanukkah celebrated, with a candle lit on a stand called a menorah on each day?",options:["Five days","Eight days","Twelve days","Forty days"],correctIndices:[1],explanation:"Hanukkah is in November or December and is celebrated for eight days to remember the Jews’ struggle for religious freedom; on each of the eight days a candle is lit on a menorah.",memoryHook:"Count the letters: H-A-N-U-K-K-A-H has 8 letters for 8 days and 8 candles (Diwali = 5 days, Lent = 40 days)."},{id:"q-ex09-15",examNumber:9,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"boolean",prompt:"Lent is the 40-day period of preparation before Easter, and the day before Lent starts is called Shrove Tuesday (or Pancake Day).",options:["True","False"],correctIndices:[0],explanation:"Lent begins on Ash Wednesday and lasts 40 days before Easter. The day before Lent begins is Shrove Tuesday (Pancake Day), when people traditionally ate pancakes to use up eggs, fat, and milk before fasting."},{id:"q-ex09-16",examNumber:9,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Baroness Tanni Grey-Thompson is one of Britain’s most celebrated Paralympians. What sport did she compete in to win 16 Paralympic medals (including 11 golds)?",options:["Solo round-the-world yacht racing","Wheelchair racing on the athletics track","Figure skating and ice dancing","Equestrian showjumping"],correctIndices:[1],explanation:"Baroness Tanni Grey-Thompson is an athlete who uses a wheelchair; she won 16 Paralympic medals, including 11 gold medals, in wheelchair racing across five Paralympic Games and won the London Marathon six times."},{id:"q-ex09-17",examNumber:9,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Which British distance runner, born in Somalia, became the first Briton to win Olympic gold medals in both the 5,000 metres and 10,000 metres at the 2012 London Olympics?",options:["Sir Mo Farah","Sir Chris Hoy","David Weir","Sir Roger Bannister"],correctIndices:[0],explanation:"Sir Mo Farah is a British distance runner born in Somalia who won gold in both the 5,000m and 10,000m at the 2012 London Olympics, the first Briton ever to win Olympic gold in those events.",memoryHook:'Surname pun: Mo "FAR-ah" ran the FAR distances (5,000m and 10,000m golds, vs Kelly Holmes in the shorter 800m and 1,500m).'},{id:"q-ex09-18",examNumber:9,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Who wrote The Lord of the Rings, which was voted the country’s best-loved novel in 2003?",options:["Ian Fleming","Graham Greene","J.R.R. Tolkien","Evelyn Waugh"],correctIndices:[2],explanation:"J.R.R. Tolkien wrote The Lord of the Rings, which topped the BBC’s nationwide poll in 2003 as the country’s best-loved novel."},{id:"q-ex09-19",examNumber:9,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"Where does the Northern Ireland Assembly meet, and how many elected Members of the Legislative Assembly (MLAs) does it have?",options:["Cardiff Bay, with 60 MLAs","Holyrood in Edinburgh, with 129 MLAs","Stormont in Belfast, with 90 MLAs","Guildhall in Derry/Londonderry, with 150 MLAs"],correctIndices:[2],explanation:"The Northern Ireland Assembly meets in the Parliament Buildings at Stormont in Belfast and has 90 elected Members of the Legislative Assembly (MLAs).",memoryHook:"Climb north up the map as seats grow: Cardiff (Senedd) = 60 MSs; Belfast (Stormont) = 90 MLAs; Edinburgh (Holyrood) = 129 MSPs.",visualId:"parliament-courts"},{id:"q-ex09-20",examNumber:9,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"Which of the following matters is NOT devolved to the Scottish Parliament and remains decided by the UK Parliament at Westminster?",options:["Education and school policy","Immigration and nationality law","Health services in Scotland","Planning and local civil law"],correctIndices:[1],explanation:"Immigration, defence, foreign affairs, and social security remain reserved to the central UK Parliament at Westminster, while Scotland legislates on health, education, planning, and Scots civil and criminal law.",visualId:"parliament-courts"},{id:"q-ex09-21",examNumber:9,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:'When is a parliamentary "by-election" held in the UK?',options:["Every autumn when local councils update the electoral register","Whenever the House of Lords amends a government bill","If an MP dies or resigns between General Elections, to choose a new MP for that constituency","Whenever two parties form a coalition government"],correctIndices:[2],explanation:"If a Member of Parliament (MP) dies or resigns during a parliamentary term, a fresh election called a by-election is held solely in their constituency to elect a replacement MP.",memoryHook:'Wordplay: When an MP says "bye-bye" mid-term (dies or resigns), that constituency holds a "by-election".',visualId:"parliament-courts"},{id:"q-ex09-22",examNumber:9,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"At what time of year is the UK electoral register updated annually, when local councils contact every household?",options:["Every January after New Year’s Day","Every April at the start of the tax year","Every July before Parliament’s summer recess","Every autumn (September/October)"],correctIndices:[3],explanation:"To vote in a parliamentary or local election you must be on the electoral register, which is updated every year in September/October (autumn) by local council electoral registration offices.",memoryHook:"Admin-calendar trap: The tax year starts in April, but household voter registration forms go out every autumn (September/October)."},{id:"q-ex09-23",examNumber:9,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"Which UK law incorporated the principles of the European Convention on Human Rights directly into British domestic law?",options:["The Habeas Corpus Act 1679","The Bill of Rights 1689","The Great Reform Act 1832","The Human Rights Act 1998"],correctIndices:[3],explanation:"Britain helped draft the Council of Europe’s European Convention on Human Rights, and the Human Rights Act 1998 incorporated its protections into domestic UK law so public bodies and courts must respect Convention rights.",memoryHook:"Rights-laws timeline: 1679 Habeas Corpus (court hearing for prisoners) -> 1689 Bill of Rights (limited monarch) -> 1998 Human Rights Act (ECHR in UK law)."},{id:"q-ex09-24",examNumber:9,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO features distinguish a serious criminal jury trial in Scotland from a Crown Court jury trial in England and Wales? (Choose TWO)",options:["A Scottish criminal jury has 15 members instead of 12","Scottish juries are selected only from retired police officers",'A Scottish jury can return a third verdict of "not proven" alongside "guilty" and "not guilty"',"Defendants in Scotland are not allowed legal representation"],correctIndices:[0,2],explanation:'In England, Wales, and Northern Ireland, a criminal jury has 12 members and two verdicts (guilty or not guilty). In Scotland, a jury has 15 members and three possible verdicts: guilty, not guilty, and "not proven".',visualId:"parliament-courts"},{id:"q-ex10-01",examNumber:10,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"In the UK, domestic violence between married partners inside their own home is treated by police as a private family dispute rather than a criminal offence.",options:["True","False"],correctIndices:[1],explanation:"Brutality and violence in the home are serious crimes in the UK. Anyone who is violent towards their partner, whether they are a man or a woman, married or living together, can be prosecuted."},{id:"q-ex10-02",examNumber:10,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"To whom do new British citizens swear or affirm their Oath (or Affirmation) of Allegiance during a citizenship ceremony?",options:["The Prime Minister and the Cabinet","The Speaker of the House of Commons","His Majesty King Charles the Third, His Heirs and Successors","The Lord Chief Justice of England and Wales"],correctIndices:[2],explanation:"During a UK citizenship ceremony, new citizens swear or affirm that on becoming a British citizen they will be faithful and bear true allegiance to His Majesty King Charles the Third, His Heirs and Successors, according to law.",memoryHook:"Ceremony split: The Oath/Affirmation pledges allegiance to the Monarch (King Charles III); the Pledge promises loyalty to the UK, its democracy, and its laws."},{id:"q-ex10-03",examNumber:10,chapterId:"ch2",subtopicId:"ch2-territories",type:"multiple",prompt:"Which TWO of the following places are British Overseas Territories linked to the UK rather than part of it? (Choose TWO)",options:["Gibraltar","Jersey","St Helena","Anglesey"],correctIndices:[0,2],explanation:"Gibraltar (at the southern tip of Spain) and St Helena (in the South Atlantic) are British Overseas Territories. Jersey is a Crown Dependency, and Anglesey is an island county in Wales.",visualId:"national-emblems"},{id:"q-ex10-04",examNumber:10,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Derry/Londonderry and Lisburn are major cities in which part of the United Kingdom?",options:["Scotland","Northern Ireland","Wales","England"],correctIndices:[1],explanation:"Alongside the capital Belfast, Derry/Londonderry and Lisburn are major cities in Northern Ireland.",visualId:"uk-map"},{id:"q-ex10-05",examNumber:10,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"Why does the official Union Flag NOT contain the Red Dragon of Wales?",options:["Wales voted in a 1999 referendum to remove the dragon from the Union Flag","Only patron saint crosses painted in blue are permitted on UK flags","The Principality of Wales was already united with England when the first Union Flag was created in 1606","The Red Dragon is reserved solely for the personal standard of the Prime Minister"],correctIndices:[2],explanation:"When the first Union Flag was created in 1606 from the flags of Scotland and England, the Principality of Wales was already united with England; therefore the Welsh dragon does not appear on the Union Flag.",visualId:"union-jack"},{id:"q-ex10-06",examNumber:10,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"William Shakespeare was born in Stratford-upon-Avon in England. Which famous London theatre is closely associated with the performance of his plays?",options:["The Royal Albert Hall","The Palladium","The Old Bailey","The Globe Theatre"],correctIndices:[3],explanation:"Born in Stratford-upon-Avon in 1564, William Shakespeare worked in London as an actor and playwright, where many of his plays were performed at the open-air Globe Theatre (a modern reconstruction stands near the original site today).",memoryHook:'Quote link: "All the world’s a stage" points straight to Shakespeare’s Globe ("world") Theatre.'},{id:"q-ex10-07",examNumber:10,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"What lasting religious achievement was commissioned by King James VI and I in the early 17th century?",options:['A new English translation of the Bible known as the "King James Version" or "Authorised Version"',"The construction of Canterbury Cathedral after the Viking raids","The Act of Toleration granting votes to Quakers and Catholics","The founding of the Salvation Army in East London"],correctIndices:[0],explanation:'One major achievement of King James’s reign was a new translation of the Bible into English, known as the "King James Version" or "Authorised Version": notable as a Protestant translation rather than a Roman Catholic one, and still used in many Protestant churches today.'},{id:"q-ex10-08",examNumber:10,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:'King Charles I believed in the "Divine Right of Kings". How did this belief shape his relationship with Parliament before the English Civil War?',options:["He invited MPs to elect a new Prime Minister every two years","He believed he was appointed directly by God and tried to rule and raise money for 11 years without Parliament’s approval","He handed control of the Royal Navy and taxation voluntarily to the House of Commons","He merged the English Parliament with the French National Assembly"],correctIndices:[1],explanation:'Charles I believed kings were appointed directly by God ("Divine Right of Kings") and should be able to act without seeking Parliament’s approval; when Parliament challenged his religious and foreign policies, he ruled for 11 years without calling Parliament.'},{id:"q-ex10-09",examNumber:10,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"multiple",prompt:"At which TWO decisive battles during the English Civil War was King Charles I’s army defeated by Parliament’s forces? (Choose TWO)",options:["Marston Moor","Agincourt","Naseby","Waterloo"],correctIndices:[0,2],explanation:"King Charles I’s Cavalier army was defeated by Parliament’s Roundhead army at the Battles of Marston Moor (1644) and Naseby (1645); by 1646 it was clear that Parliament had won the war.",memoryHook:"Alphabetical and chronological pair M -> N: Marston Moor (1644) followed by Naseby (1645).",visualId:"history-timeline"},{id:"q-ex10-10",examNumber:10,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Just before Queen Victoria came to the throne, father and son George and Robert Stephenson pioneered the railway engine. What was their famous steam locomotive called?",options:["The Golden Hind","The Spitfire","The Rocket","HMS Victory"],correctIndices:[2],explanation:"George and Robert Stephenson pioneered the steam railway locomotive, most famously Stephenson’s Rocket, ushering in a major expansion of railway building across the Victorian Empire."},{id:"q-ex10-11",examNumber:10,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"multiple",prompt:"Engineer Isambard Kingdom Brunel, originally from Portsmouth, was responsible for which TWO famous Victorian engineering landmarks? (Choose TWO)",options:["The Clifton Suspension Bridge spanning the Avon Gorge at Bristol","Hadrian’s Wall across northern England","The Great Western Railway (running from Paddington to the south-west and Wales)","The Thames Barrier at Woolwich"],correctIndices:[0,2],explanation:"Isambard Kingdom Brunel built tunnels, bridges, railway lines, and ships, including the Great Western Railway (from London Paddington to the south-west and Wales) and the iconic Clifton Suspension Bridge in Bristol.",memoryHook:"B for Brunel = Bristol and West Country engineering: Great Western Railway, Bristol’s Clifton Suspension Bridge, and the SS Great Britain (in Bristol)."},{id:"q-ex10-12",examNumber:10,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which Christian group set up the first formal anti-slavery organisations in Britain in the late 1700s and petitioned Parliament to ban the slave trade?",options:["The Cavaliers","The Quakers","The Jacobites","The Suffragettes"],correctIndices:[1],explanation:"Although slavery was illegal within Britain itself, British ships and overseas colonies relied heavily on enslaved labour until the Quakers set up the first formal anti-slavery groups in the late 1700s, campaigning alongside Olaudah Equiano and William Wilberforce."},{id:"q-ex10-13",examNumber:10,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:"In 1776, 13 British colonies in North America declared their independence, stating that people had a right to establish their own governments after clashing with Britain over taxation.",options:["True","False"],correctIndices:[0],explanation:"By the 1760s–1770s, substantial British colonies in North America objected to being taxed by the British Parliament without representation; 13 colonies declared independence in 1776 and defeated the British army by 1783."},{id:"q-ex10-14",examNumber:10,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"What does the Muslim festival of Eid ul Adha remember?",options:["The end of the month-long fast of Ramadan","That the prophet Ibrahim was willing to sacrifice his son when God ordered him to","An ancient Celtic harvest marking the start of winter","The translation of religious texts in 1611"],correctIndices:[1],explanation:"Eid ul Adha remembers that the prophet Ibrahim was willing to sacrifice his son when God ordered him to, reminding Muslims of their own commitment to God.",memoryHook:"Letter link for the two Eids: A in Adha = Abraham/Ibrahim’s willingness to sacrifice; F in Fitr = Fasting Finishes (end of Ramadan)."},{id:"q-ex10-15",examNumber:10,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"In Scotland, what is 31 December (New Year’s Eve) traditionally called?",options:["Vaisakhi","Eisteddfod","Burns Night","Hogmanay"],correctIndices:[3],explanation:"New Year’s Eve on 31 December is called Hogmanay in Scotland, where New Year is often an even bigger celebration than Christmas, and 2 January is also a public bank holiday in Scotland.",memoryHook:"Scottish winter dates: 31 December = Hogmanay (New Year’s Eve); 25 January = Burns Night (haggis and Robert Burns’s poetry)."},{id:"q-ex10-16",examNumber:10,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Which Scottish athlete won six gold and one silver Olympic medals in track cycling?",options:["Sir Chris Hoy","Sir Andy Murray","Sir Jackie Stewart","Damon Hill"],correctIndices:[0],explanation:"Sir Chris Hoy is a Scottish track cyclist who won six Olympic gold medals and one silver medal across the 2000, 2004, 2008, and 2012 Olympic Games.",memoryHook:"Scottish sports trio: Chris Hoy = track cycling (6 Olympic golds); Andy Murray = tennis; Jackie Stewart = Formula 1."},{id:"q-ex10-17",examNumber:10,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Dame Jessica Ennis-Hill was one of the stars of the 2012 London Olympics, winning the gold medal in which athletics event?",options:["The women’s marathon","The 10,000 metres track final","The heptathlon (seven different track and field events)","Single sculls rowing"],correctIndices:[2],explanation:"Dame Jessica Ennis-Hill won the Olympic gold medal at London 2012 in the heptathlon, an all-round athletics competition comprising seven different track and field events.",memoryHook:"Letter count: J-E-S-S-I-C-A has 7 letters and Hill starts with H, matching the Heptathlon (7 events)."},{id:"q-ex10-18",examNumber:10,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:'Scots around the world celebrate Burns Night on 25 January by eating haggis and reading poems by Robert Burns ("The Bard"). Which famous New Year song did Robert Burns write?',options:["Land of Hope and Glory","Rule, Britannia!","Jerusalem","Auld Lang Syne"],correctIndices:[3],explanation:'Scottish poet Robert Burns (1759–1796), known in Scotland as "The Bard", wrote in Scots and English with Scots words; his best-known work is the song Auld Lang Syne, sung as the clock strikes midnight at New Year.'},{id:"q-ex10-19",examNumber:10,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"How are ministerial offices allocated in the Northern Ireland Assembly, and what happens if local political leaders cannot agree to work together?",options:["Only the single largest party holds all ministries, and the UN takes over if talks fail","Ministerial offices are distributed on a power-sharing basis among the main parties, and the UK Government has the power to suspend the Assembly","Ministers are chosen by lottery from jurors in Belfast for one-year terms","The Irish President in Dublin appoints the Northern Ireland Cabinet directly"],correctIndices:[1],explanation:"Established after the 1998 Belfast (Good Friday) Agreement, the Northern Ireland Assembly operates with a power-sharing executive distributing ministerial posts among the main parties; the UK Government can suspend the Assembly if leaders no longer work together.",visualId:"parliament-courts"},{id:"q-ex10-20",examNumber:10,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"What legal authority does the Commonwealth have over its 56 independent member countries?",options:["It sets income tax rates across all member countries every five years","It has no power over its members, although it can suspend membership","Its courts can strike down Acts passed by the Westminster Parliament","It commands a permanent standing army stationed in London"],correctIndices:[1],explanation:"The Commonwealth is based on core values of democracy, good government, and rule of law, but it has no legal power over its member states, although it can suspend a country’s membership for serious violations."},{id:"q-ex10-21",examNumber:10,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"multiple",prompt:"Alongside UK citizens aged 18 or over on the electoral register, which TWO other groups resident in the UK have the right to vote in all UK parliamentary General Elections? (Choose TWO)",options:["Citizens of the Republic of Ireland resident in the UK","Short-stay tourists visiting on a six-month visitor visa","Qualifying Commonwealth citizens resident in the UK","Any adult living anywhere in North or South America"],correctIndices:[0,2],explanation:"Adult British citizens, together with qualifying citizens of the Commonwealth and citizens of the Republic of Ireland who are resident in the UK and aged 18 or over on the electoral register, can vote in all public UK elections.",visualId:"parliament-courts"},{id:"q-ex10-22",examNumber:10,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"boolean",prompt:"When His Majesty King Charles III opens a new parliamentary session with the King’s Speech, he writes the speech personally to announce his own political policies.",options:["True","False"],correctIndices:[1],explanation:"In the UK’s constitutional monarchy, the King opens each parliamentary session and delivers the King’s Speech, which outlines the legislative plans written by the elected Government, not personal political policies of the Monarch.",visualId:"parliament-courts"},{id:"q-ex10-23",examNumber:10,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"What is the main purpose of the North Atlantic Treaty Organization (NATO), of which the UK is a member?",options:["Organising international football and Olympic tournaments","Managing a shared currency across Europe and North America","A group of European and North American countries that have agreed to help each other if they come under attack","Issuing passports to Crown Dependencies in the English Channel"],correctIndices:[2],explanation:"NATO is a group of European and North American countries that have agreed to help defend each other if any member comes under armed attack, aiming to maintain peace between all members."},{id:"q-ex10-24",examNumber:10,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"You live in England and need to recover £3,500 owed to you for faulty building work without hiring an expensive lawyer. Up to what claim value can the informal Small Claims Procedure normally be used in England and Wales?",options:["Up to £1,000","Up to £5,000","Up to £10,000","Up to £50,000"],correctIndices:[2],explanation:"The Small Claims Procedure is an informal way of helping people settle minor civil disputes without spending a lot of time and money using a lawyer: it covers claims under £10,000 in England and Wales (and £5,000 in Scotland and Northern Ireland).",memoryHook:"Number trick: England and Wales share a 2-nation jurisdiction = £10,000 (2 x £5k); Scotland (1 nation) = £5,000; Northern Ireland (1 nation) = £5,000.",visualId:"parliament-courts"},{id:"q-ex11-01",examNumber:11,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"A resident repeatedly dumps household rubbish in a local woodland and damages public park benches. Which core UK resident responsibility are they failing to uphold?",options:["Standing for election as a local councillor","Looking after the area in which you live and the environment","Serving on a 15-person Scottish jury","Attending weekly Prime Minister’s Questions"],correctIndices:[1],explanation:"Everyone living in the UK has a shared responsibility to look after the area in which they live and the environment, including disposing of litter responsibly and respecting public spaces."},{id:"q-ex11-02",examNumber:11,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"multiple",prompt:"In the Citizenship Pledge spoken at a UK citizenship ceremony, which TWO commitments does a new citizen promise? (Choose TWO)",options:["To uphold the UK’s democratic values","To vote for the governing political party in every General Election","To observe the UK’s laws faithfully and fulfil their duties and obligations as a British citizen","To surrender any foreign university qualifications"],correctIndices:[0,2],explanation:'The Citizenship Pledge states: "I will give my loyalty to the United Kingdom and respect its rights and freedoms. I will uphold its democratic values. I will observe its laws faithfully and fulfil my duties and obligations as a British citizen."'},{id:"q-ex11-03",examNumber:11,chapterId:"ch2",subtopicId:"ch2-territories",type:"single",prompt:"Which option lists ALL four standard banknote denominations of Pound Sterling (£) in the UK?",options:["£1, £5, £10, and £20","£5, £10, £20, and £50","£5, £10, £25, and £100","£2, £5, £20, and £50"],correctIndices:[1],explanation:"Standard UK banknotes are issued in denominations of £5, £10, £20, and £50, while £1 and £2 are coins (though some Scottish/NI banks also print £1 or £100 notes locally, the four standard UK denominations are £5, £10, £20, and £50).",memoryHook:"US-expat trap: Unlike the $1 bill, £1 and £2 are coins in the UK; standard banknotes start at £5 (£5, £10, £20, £50)."},{id:"q-ex11-04",examNumber:11,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Roughly what is the widest distance across Great Britain from the east coast to the west coast?",options:["About 90 miles","About 300 miles","About 620 miles","About 870 miles"],correctIndices:[1],explanation:"While Great Britain is about 870 miles long from John O’Groats to Land’s End, its widest distance from the east coast to the west coast is about 300 miles.",memoryHook:'Visual trick: Turn the W in "Wide" on its side and it looks like a 3 -> about 300 miles wide.',visualId:"uk-map"},{id:"q-ex11-05",examNumber:11,chapterId:"ch2",subtopicId:"ch2-symbols",type:"multiple",prompt:"All four nations of the UK celebrate patron saints’ days, but in which TWO nations is the patron saint’s day an official public (bank) holiday? (Choose TWO)",options:["England (St George’s Day, 23 April)","Scotland (St Andrew’s Day, 30 November)","Wales (St David’s Day, 1 March)","Northern Ireland (St Patrick’s Day, 17 March)"],correctIndices:[1,3],explanation:"Only Scotland (30 November, St Andrew’s Day) and Northern Ireland (17 March, St Patrick’s Day) have official public holidays for their patron saints’ days (though in Scotland not all businesses close).",memoryHook:"North vs South rule: Only the two northern nations, Northern Ireland (17 Mar) and Scotland (30 Nov), have official bank holidays for their patron saints; England and Wales do not.",visualId:"national-emblems"},{id:"q-ex11-06",examNumber:11,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"What happened to Catholic monarch Mary, Queen of Scots, after she fled Scotland to England during the reign of her Protestant cousin, Queen Elizabeth I?",options:["She married Francis Drake and settled peacefully in Plymouth","Elizabeth gave her an army to reconquer Edinburgh immediately","She was kept prisoner for 20 years and eventually executed after being suspected of plotting against Elizabeth I","She sailed to North America to found the colony of Virginia"],correctIndices:[2],explanation:'Mary Stuart ("Mary, Queen of Scots") fled to England giving her throne to her infant son James VI; Elizabeth I saw Mary as a Catholic rival to the English throne, kept her prisoner for 20 years, and had her executed in 1587 for treasonous plotting.',memoryHook:'Two-Marys trap: Mary I ("Bloody Mary") was Henry VIII’s daughter who ruled England; Mary, Queen of Scots (Mary Stuart) was Elizabeth I’s cousin, imprisoned 20 years and executed in 1587.'},{id:"q-ex11-07",examNumber:11,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"After King Charles I was executed in 1649 and England was declared a republic called the Commonwealth, what title was given to Oliver Cromwell as leader of the republic?",options:["First Prime Minister","Speaker of the Estates","Lord Protector","Supreme Governor"],correctIndices:[2],explanation:"Following Charles I’s execution in 1649 and Cromwell’s military campaigns in Ireland and Scotland, Oliver Cromwell was given the title of Lord Protector in the 1650s and ruled until his death in 1658.",visualId:"history-timeline"},{id:"q-ex11-08",examNumber:11,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:'In May 1660, Parliament invited which exiled monarch back from the Netherlands to reclaim the throne in the event known as "The Restoration"?',options:["King Charles II","King William III","Bonnie Prince Charlie","King Henry VII"],correctIndices:[0],explanation:"After Oliver Cromwell died and his son Richard failed to provide clear leadership, Parliament invited the executed king’s son, Charles II (who had famously hidden in an oak tree after the Battle of Worcester in 1651), back from exile in 1660.",memoryHook:"Netherlands trap: 1660 Restoration = exiled King Charles II invited back; 1688 Glorious Revolution = Dutch Prince William III of Orange invited over to replace James II.",visualId:"history-timeline"},{id:"q-ex11-09",examNumber:11,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"After the Great Fire of London in 1666 destroyed much of the city, which famous architect designed the rebuilt St Paul’s Cathedral?",options:["Sir Edwin Lutyens","Charles Barry","Robert Adam","Sir Christopher Wren"],correctIndices:[3],explanation:"In 1665 London suffered the Great Plague, and in 1666 a great fire destroyed much of the city, including the original St Paul’s Cathedral. London was rebuilt with a magnificent new St Paul’s designed by Sir Christopher Wren.",memoryHook:"Picture a wren (bird) perched atop St Paul’s dome: Christopher Wren rebuilt St Paul’s after 1666 (Barry = Parliament, Lutyens = Cenotaph)."},{id:"q-ex11-10",examNumber:11,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Why was the Habeas Corpus Act of 1679 a vital milestone in British legal history?",options:["It gave every landowner the right to print banknotes","It guaranteed that no person could be held prisoner unlawfully and every prisoner has a right to a court hearing","It introduced trial by 15 jurors in England and Wales","It abolished the death penalty for all offences"],correctIndices:[1],explanation:'Habeas corpus is Latin for "you must present the person in court". Passed in 1679 during Charles II’s reign, the Act ensured no one could be locked up unlawfully without being brought before a judge.',memoryHook:'Latin root: "Corpus" means body (like corpse). Habeas Corpus literally means "present the body in court" so no one can be locked up unlawfully.'},{id:"q-ex11-11",examNumber:11,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which evangelical Christian and Member of Parliament played a leading part in turning public and parliamentary opinion against the slave trade in the late 18th and early 19th centuries?",options:["William Wilberforce","Richard Arkwright","Sir Robert Walpole","Aneurin Bevan"],correctIndices:[0],explanation:"William Wilberforce was an evangelical Christian and MP who worked tirelessly alongside abolitionists and the Quakers to pass the 1807 Slave Trade Act and pave the way for the 1833 Emancipation Act."},{id:"q-ex11-12",examNumber:11,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Who commanded the British fleet to victory against combined French and Spanish fleets at the Battle of Trafalgar in 1805 aboard HMS Victory?",options:["The Duke of Wellington","Sir Francis Drake","Admiral Horatio Nelson","Lord Louis Mountbatten"],correctIndices:[2],explanation:"In 1805, Admiral Nelson led the Royal Navy to victory over the combined French and Spanish fleets at the Battle of Trafalgar (where he was killed in action). Nelson’s Column stands in Trafalgar Square, and HMS Victory can be visited in Portsmouth.",memoryHook:"Napoleonic pair (10 years apart): 1805 Trafalgar at SEA = Admiral Nelson (Navy); 1815 Waterloo on LAND = Duke of Wellington.",visualId:"history-timeline"},{id:"q-ex11-13",examNumber:11,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:"Under the 1707 Act of Union with England, Scotland abolished its own legal system, education system, and Presbyterian Church.",options:["True","False"],correctIndices:[1],explanation:"Although Scotland was no longer an independent country with a separate parliament after the 1707 Act of Union, it expressly kept its own distinct legal and education systems and its Presbyterian Church of Scotland."},{id:"q-ex11-14",examNumber:11,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"single",prompt:"When is Mothering Sunday (Mother’s Day) celebrated each year in the UK?",options:["The second Sunday in May","The Sunday three weeks before Easter","The third Sunday in June","Always on 14 February"],correctIndices:[1],explanation:"In the UK, Mothering Sunday is celebrated on the Sunday three weeks before Easter (unlike in the US, where Mother’s Day is in May). Father’s Day in the UK is the third Sunday in June.",memoryHook:"Halfway through 6-week Lent = 3 weeks before Easter (don’t pick the US May date!)."},{id:"q-ex11-15",examNumber:11,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:'Which TWO poets from the late 18th and early 19th centuries wrote The Tyger ("Tyger! Tyger! burning bright") and She Walks in Beauty respectively? (Choose TWO)',options:["William Blake","Wilfred Owen","Lord Byron","Dylan Thomas"],correctIndices:[0,2],explanation:"Artist and poet William Blake wrote The Tyger (and the lines that became the hymn Jerusalem), while Romantic poet Lord Byron wrote She Walks in Beauty and Childe Harold’s Pilgrimage.",memoryHook:'Double-B Romantic poets: Blake ("Tyger, Tyger, Burning bright") and Byron ("She Walks in Beauty").'},{id:"q-ex11-16",examNumber:11,chapterId:"ch4",subtopicId:"ch4-sports",type:"single",prompt:"Why did Scottish tennis player Sir Andy Murray make British sporting history in 2012 and 2013?",options:["He invented modern grass-court lawn tennis rules at Wimbledon","He became the first British man since 1936 to win a Men’s Singles Grand Slam tournament (2012 US Open, followed by Wimbledon)","He won five consecutive Olympic doubles titles between 1984 and 2000","He coached both Oxford and Cambridge in the Thames Boat Race"],correctIndices:[1],explanation:"Sir Andy Murray won the Men’s Singles at the 2012 US Open, becoming the first British man since 1936 to win a Grand Slam singles title, won Olympic gold and silver in 2012, and went on to win Wimbledon Men’s Singles in 2013 and 2016."},{id:"q-ex11-17",examNumber:11,chapterId:"ch4",subtopicId:"ch4-sports",type:"multiple",prompt:"Which TWO athletes are celebrated British Paralympic multi-gold medallists, one in wheelchair track/marathon racing and the other in Paralympic swimming? (Choose TWO)",options:["David Weir","Lewis Hamilton","Ellie Simmonds","Jayne Torvill"],correctIndices:[0,2],explanation:"David Weir won six gold medals across two Paralympic Games (including four at London 2012) and won the London Marathon six times; Ellie Simmonds is a Paralympian swimmer who won gold medals at the 2008, 2012, and 2016 Games (becoming the youngest Briton to win gold in 2008).",memoryHook:"Alliteration pair: W for Weir = Wheelchair racing; S for Simmonds = Swimming."},{id:"q-ex11-18",examNumber:11,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which 20th-century British novelist wrote satirical novels including Decline and Fall and Brideshead Revisited?",options:["Evelyn Waugh","Robert Louis Stevenson","Charles Dickens","Sir Arthur Conan Doyle"],correctIndices:[0],explanation:"Evelyn Waugh (1903–1966) wrote satirical novels about upper-class society and faith, including Decline and Fall and his best-known novel, Brideshead Revisited.",memoryHook:'Surname link: Evelyn Waugh (a man, surname pronounced "War") wrote Decline and Fall and WWII-framed Brideshead Revisited.'},{id:"q-ex11-19",examNumber:11,chapterId:"ch5",subtopicId:"ch5-devolution",type:"boolean",prompt:"Since 2011, Senedd Cymru (the Welsh Parliament) has been able to pass laws on devolved Welsh matters, such as education, health, and the Welsh language, without needing prior agreement from the UK Parliament.",options:["True","False"],correctIndices:[0],explanation:"Following a referendum in March 2011, the Welsh legislature gained primary law-making powers in 21 devolved areas (such as education, health, transport, and the Welsh language) without needing agreement from Westminster.",visualId:"parliament-courts"},{id:"q-ex11-20",examNumber:11,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"When was the United Nations (UN) established, and what is its primary aim?",options:["In 1815 after Waterloo, to regulate European coal tariffs","After the Second World War, with over 190 member countries working to prevent war and promote international peace and security","In 1973 in Brussels, to create a single European currency","In 1999 in Edinburgh, to coordinate devolved parliaments"],correctIndices:[1],explanation:"The UK is part of the United Nations (UN), an international organisation with more than 190 countries set up after the Second World War to prevent war and promote international peace and security."},{id:"q-ex11-21",examNumber:11,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"boolean",prompt:"In Great Britain, eligible voters register to vote using an individual registration system, meaning each eligible adult in a household is responsible for registering themselves.",options:["True","False"],correctIndices:[0],explanation:'Under individual electoral registration, every person in a household who is eligible to vote registers individually (providing personal identifiers such as date of birth and National Insurance number) rather than one "head of household" registering everyone.'},{id:"q-ex11-22",examNumber:11,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"multiple",prompt:"Most UK, Irish, or qualifying Commonwealth citizens aged 18 or over can stand for election as an MP, EXCEPT for certain groups. Which TWO groups are disqualified from standing as an MP? (Choose TWO)",options:["Members of the armed forces","Primary school teachers","Civil servants","Shop owners and company directors"],correctIndices:[0,2],explanation:"Members of the armed forces, civil servants, and people found guilty of certain criminal offences (as well as peers sitting in the House of Lords and certain judges/police officers) cannot stand for election as an MP in the House of Commons.",visualId:"parliament-courts"},{id:"q-ex11-23",examNumber:11,chapterId:"ch5",subtopicId:"ch5-democracy-constitution",type:"single",prompt:'Why is the British constitution described as "unwritten"?',options:["Because UK laws are passed orally and never printed on paper","Because its constitutional rules, Acts of Parliament, common law, and conventions have never been collected into one single formal document","Because only the Monarch is allowed to read the secret constitution scroll","Because every General Election automatically cancels all previous laws"],correctIndices:[1],explanation:'Unlike the USA or France, the UK does not have one single written constitutional document; instead, its "unwritten" (uncodified) constitution is formed by Acts of Parliament, court judgments, treaties, and long-standing conventions.',visualId:"parliament-courts"},{id:"q-ex11-24",examNumber:11,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In England and Wales, what is the role of directly elected Police and Crime Commissioners (PCCs)?",options:["Acting as prosecution barristers in Crown Court murder trials","Setting local police priorities and the local policing budget","Personally arresting suspects during 999 emergency calls","Appointing judges to the UK Supreme Court"],correctIndices:[1],explanation:"Voters in England and Wales directly elect Police and Crime Commissioners (PCCs) to hold the police accountable, set local police priorities, and set the local policing budget, while operational policing remains independent under the Chief Constable.",memoryHook:"Acronym PCC = Priorities and Cash Control (sets local police priorities and budget, while the Chief Constable runs daily operations).",visualId:"parliament-courts"},{id:"q-ex12-01",examNumber:12,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"An employer refuses to interview a well-qualified job applicant solely because of her religion and marital status. Which fundamental guarantee offered by the UK to its residents does this violate?",options:["Freedom from unfair discrimination","The right to stand as a hereditary peer","Exemption from paying Income Tax","Compulsory membership of a trade union"],correctIndices:[0],explanation:"In return for residents respecting laws and shared responsibilities, the UK offers freedom of belief and religion, freedom of speech, freedom from unfair discrimination, a right to a fair trial, and a right to join in electing a government. UK equality law prohibits unfair discrimination based on age, disability, sex, marital status, pregnancy, race, religion, or sexual orientation."},{id:"q-ex12-02",examNumber:12,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"Unless exempt, what minimum level of English speaking and listening on the Common European Framework of Reference (CEFR) is required to apply for UK settlement or naturalisation?",options:["Level A1","Level B1","Level C2","No English test is required if you pass the Life in the UK Test"],correctIndices:[1],explanation:"Alongside passing the Life in the UK Test, applicants for permanent residence (settlement) or citizenship must normally demonstrate English speaking and listening skills at CEFR level B1 (intermediate) or higher.",memoryHook:'Pun: Want to "BE ONE" with the UK? You need English Level B1 (not A1 or C2).'},{id:"q-ex12-03",examNumber:12,chapterId:"ch2",subtopicId:"ch2-territories",type:"boolean",prompt:"Residents of Jersey and Guernsey in the Channel Islands elect Members of Parliament (MPs) to represent them in the Westminster House of Commons.",options:["True","False"],correctIndices:[1],explanation:"Jersey and Guernsey are self-governing Crown Dependencies with their own island legislatures and tax systems; because they are not part of the UK, they do not elect MPs to the Westminster House of Commons."},{id:"q-ex12-04",examNumber:12,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Which of the following UK cities is NOT located in England?",options:["Plymouth","Norwich","Swansea","Southampton"],correctIndices:[2],explanation:"Plymouth, Norwich, and Southampton are all cities in England, whereas Swansea is a major coastal city in south Wales.",visualId:"uk-map"},{id:"q-ex12-05",examNumber:12,chapterId:"ch2",subtopicId:"ch2-symbols",type:"single",prompt:"Which cross was added to the crosses of St George and St Andrew in 1801 to create the modern design of the Union Flag?",options:["The yellow cross of St David on a black ground","The diagonal red cross of St Patrick on a white ground","The white cross of St Columba on a green ground","The gold cross of St Augustine on a purple ground"],correctIndices:[1],explanation:"Following the Act of Union with Ireland taking effect in 1801, the Irish cross of St Patrick (a diagonal red cross on a white ground) was combined with the crosses of St George (England) and St Andrew (Scotland) to form today’s Union Flag.",visualId:"union-jack"},{id:"q-ex12-06",examNumber:12,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Born in Lincolnshire, which famous member of the Royal Society discovered gravity, showed how white light is made of rainbow colours, and published Philosophiae Naturalis Principia Mathematica?",options:["Sir Isaac Newton","Sir Edmund Halley","Francis Crick","Ernest Rutherford"],correctIndices:[0],explanation:"Sir Isaac Newton (1643–1727) was a towering figure in science and the Royal Society; his Principia Mathematica showed how gravity applies across the whole universe, and he also discovered that white light is composed of the colours of the rainbow."},{id:"q-ex12-07",examNumber:12,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:'Why was the event of 1688, when Protestant ruler William of Orange took the throne from Catholic King James II, called the "Glorious Revolution"?',options:["Because William conquered Paris and Madrid in the same summer","Because there was no fighting in England and the revolution guaranteed the power of Parliament","Because gold was discovered beneath the Tower of London","Because every adult man and woman was immediately given the right to vote"],correctIndices:[1],explanation:'In 1688, important Protestants in England invited William of Orange (married to James II’s Protestant daughter Mary) to proclaim himself king. James II fled to France; because there was no fighting in England and it permanently guaranteed Parliament’s power, it was called the "Glorious Revolution".',visualId:"history-timeline"},{id:"q-ex12-08",examNumber:12,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"boolean",prompt:"The Bill of Rights of 1689 confirmed the rights of Parliament, placed limits on the King’s power, and stated that the monarch must be a Protestant.",options:["True","False"],correctIndices:[0],explanation:"At the coronation of William III and Mary II, the Declaration of Rights was read and confirmed by the Bill of Rights 1689, ending any claim that a monarch could rule or raise taxes/an army without Parliament and requiring the sovereign to be Protestant.",visualId:"history-timeline"},{id:"q-ex12-09",examNumber:12,chapterId:"ch3",subtopicId:"ch3-tudors-stuarts",type:"single",prompt:"Which 17th-century Englishman wrote a famous diary describing everyday life in London during the 1665 Great Plague and the 1666 Great Fire?",options:["Geoffrey Chaucer","William Caxton","Samuel Pepys","Rudyard Kipling"],correctIndices:[2],explanation:"Naval administrator Samuel Pepys wrote an eyewitness diary of 1660s Restoration London, vividly recording both the Great Plague of 1665 and the Great Fire of London in 1666, which is still read today.",memoryHook:'Pronunciation trick: Pepys is pronounced "Peeps". Samuel Pepys "peeped" at 1660s London (1665 Plague and 1666 Fire) in his eyewitness diary.'},{id:"q-ex12-10",examNumber:12,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:'Who defeated Emperor Napoleon at the Battle of Waterloo in 1815, became known as the "Iron Duke", and later served as Prime Minister?',options:["The Duke of Wellington","Admiral Horatio Nelson","Oliver Cromwell","Sir Winston Churchill"],correctIndices:[0],explanation:'In 1815, the French Wars ended with the defeat of Emperor Napoleon by the Duke of Wellington at the Battle of Waterloo. Wellington was known as the "Iron Duke" and later became Prime Minister.',memoryHook:"Alliteration W-W: Waterloo (1815 land battle) = Wellington; N-N: Navy at Trafalgar (1805 sea battle) = Nelson.",visualId:"history-timeline"},{id:"q-ex12-11",examNumber:12,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"What major political change did the Great Reform Act of 1832 introduce?",options:["It gave all women aged 21 and over the right to vote",'It abolished old "pocket" and "rotten" boroughs, gave more parliamentary seats to industrial cities, and increased the number of men eligible to vote',"It created the Scottish Parliament and Welsh Assembly","It replaced First Past the Post with proportional representation"],correctIndices:[1],explanation:"The Reform Act of 1832 greatly increased the number of (property-owning) male voters and abolished old pocket and rotten boroughs with tiny electorates, shifting more parliamentary seats to fast-growing industrial towns and cities.",memoryHook:"Voting-reform dates: 1832 abolished rotten boroughs and expanded male voting; 1918 gave votes to women 30+; 1928 equalised women at 21+."},{id:"q-ex12-12",examNumber:12,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:'What were the "Highland Clearances" in Scotland following the 1745–1746 Jacobite rebellion?',options:["The demolition of Roman forts along Hadrian’s Wall","A process in which Scottish landlords took away individual small farms (crofts) to make space for large flocks of sheep and cattle, leading many Scots to emigrate to North America","A government campaign to plant oak forests across Orkney","The transfer of the Crown Jewels from Edinburgh to Cardiff"],correctIndices:[1],explanation:'After the Battle of Culloden (1746), Scottish chieftains became landlords if they had the favour of the English king, and clansmen became tenants. In the "Highland Clearances", landlords evicted crofters to make room for sheep and cattle, prompting huge Scottish emigration to North America.'},{id:"q-ex12-13",examNumber:12,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:"Victorian engineer Isambard Kingdom Brunel designed the SS Great Britain, a pioneering iron-hulled steamship that is preserved in Bristol today.",options:["True","False"],correctIndices:[0],explanation:"Alongside bridges and railways, Isambard Kingdom Brunel revolutionised ocean transport with iron steamships such as the SS Great Britain, launched in 1843 and still open to visitors in Bristol."},{id:"q-ex12-14",examNumber:12,chapterId:"ch4",subtopicId:"ch4-religion-customs",type:"multiple",prompt:"Which TWO statements accurately match a traditional celebration in the UK with its correct calendar date? (Choose TWO)",options:['Halloween is celebrated on 31 October, when people carve pumpkin lanterns and dress up for "trick or treat"',"Valentine’s Day is celebrated on 14 March","Boxing Day is a public holiday celebrated on 26 December, the day after Christmas Day","Bonfire Night is celebrated on 11 November with a two-minute silence"],correctIndices:[0,2],explanation:"Halloween falls on 31 October and Boxing Day is on 26 December. Valentine’s Day is on 14 February (not March), and Bonfire Night is on 5 November (11 November is Remembrance Day)."},{id:"q-ex12-15",examNumber:12,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"single",prompt:"On Remembrance Day (11 November), people wear red poppies and observe a two-minute silence at 11:00 am. Which Whitehall monument, designed by Sir Edwin Lutyens, is the centrepiece of the ceremony in London?",options:["Nelson’s Column","The Cenotaph","The Angel of the North","Marble Arch"],correctIndices:[1],explanation:"Remembrance Day (11 November) commemorates those who died fighting for the UK and its allies. Wreaths are laid at the Cenotaph in Whitehall, London, designed by architect Sir Edwin Lutyens and unveiled in 1920.",memoryHook:'Word root: "Cenotaph" means "empty tomb", matching Lutyens’s Whitehall memorial to fallen soldiers buried abroad.'},{id:"q-ex12-16",examNumber:12,chapterId:"ch4",subtopicId:"ch4-sports",type:"multiple",prompt:"Motor-car racing has a proud history in the UK. Which TWO British racing drivers listed below have won the Formula 1 World Championship? (Choose TWO)",options:["Damon Hill","Sir Bradley Wiggins","Lewis Hamilton","Bobby Moore"],correctIndices:[0,2],explanation:"Recent British winners of the Formula 1 World Championship include Damon Hill, Lewis Hamilton, and Jenson Button (following earlier three-time champion Sir Jackie Stewart). Wiggins is a cyclist and Moore captained the 1966 England football team."},{id:"q-ex12-17",examNumber:12,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO authors created two of Britain’s most famous modern fictional characters, secret agent James Bond and young wizard Harry Potter? (Choose TWO)",options:["Ian Fleming","Thomas Hardy","J.K. Rowling","John Constable"],correctIndices:[0,2],explanation:'Ian Fleming introduced James Bond ("007") in 1952/1953, while J.K. Rowling wrote the hugely successful Harry Potter series of books for children and adults.'},{id:"q-ex12-18",examNumber:12,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO of the following figures are celebrated 20th-century British novelists highlighted in the Life in the UK handbook? (Choose TWO)",options:["Kingsley Amis",'Lancelot "Capability" Brown',"Graham Greene","Sir Frank Whittle"],correctIndices:[0,2],explanation:"Kingsley Amis (author of Lucky Jim) and Graham Greene (whose thrillers and novels such as Brighton Rock and The Heart of the Matter were often influenced by his religious and moral discoveries) are major 20th-century British novelists. Capability Brown was an 18th-century garden designer, and Frank Whittle invented the jet engine.",memoryHook:"Acronym WAG for the handbook’s 20th-century novelist trio: Evelyn Waugh, Kingsley Amis, and Graham Greene."},{id:"q-ex12-19",examNumber:12,chapterId:"ch5",subtopicId:"ch5-devolution",type:"multiple",prompt:"Which TWO matters can the Scottish Parliament in Edinburgh pass legislation on? (Choose TWO)",options:["Civil and criminal law in Scotland","UK military defence and NATO treaties","Education and health services in Scotland","UK immigration and asylum borders"],correctIndices:[0,2],explanation:"The Scottish Parliament can legislate on anything not specifically reserved to the UK Parliament, including civil and criminal law, health, education, planning, and additional tax-raising powers, while defence and immigration are reserved to Westminster.",visualId:"parliament-courts"},{id:"q-ex12-20",examNumber:12,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"Which of the following is NOT one of the fundamental protections contained in the European Convention on Human Rights?",options:["Right to life and prohibition of torture","Prohibition of slavery and forced labour","Right to free university tuition in any European country","Freedom of thought, conscience and religion, and freedom of expression"],correctIndices:[2],explanation:"Among the core rights in the European Convention on Human Rights are the right to life, prohibition of torture, prohibition of slavery and forced labour, right to liberty and security, right to a fair trial, and freedoms of thought, religion, and expression, not free university tuition."},{id:"q-ex12-21",examNumber:12,chapterId:"ch5",subtopicId:"ch5-parliament-elections",type:"single",prompt:"You want to meet your local Member of Parliament (MP) in person in your local area to ask for help with a community or public-service issue. What are these regular local drop-in or appointment sessions held by MPs called?",options:['Constituency "surgeries"',"Select committees","By-elections","Royal Assent hearings"],correctIndices:[0],explanation:'Residents can contact MPs by letter, phone, or email at Westminster or their constituency office, and many MPs hold regular local sessions called "surgeries", where constituents can go in person to talk about issues of concern.',memoryHook:'British English link: Just as you visit a local GP’s "surgery" for a consultation, you visit your MP’s local "surgery" for one-to-one help.',visualId:"parliament-courts"},{id:"q-ex12-22",examNumber:12,chapterId:"ch5",subtopicId:"ch5-devolution",type:"boolean",prompt:"The modern Scottish Parliament, Welsh Assembly (now Senedd), and Northern Ireland Assembly were established in 1998 and 1999 following referendums.",options:["True","False"],correctIndices:[0],explanation:"Following devolution referendums under the Labour government elected in 1997, the Northern Ireland Assembly was formed after the 1998 Belfast (Good Friday) Agreement, and the Welsh Assembly and Scottish Parliament opened in 1999.",visualId:"parliament-courts"},{id:"q-ex12-23",examNumber:12,chapterId:"ch5",subtopicId:"ch5-devolution",type:"single",prompt:"What is true about the Council of Europe?",options:["It is the executive cabinet of the European Union in Brussels","It is separate from the EU, has no power to make laws, and draws up charters and conventions such as the European Convention on Human Rights","It sets UK interest rates and prints Euro banknotes","Only the five permanent members of the UN Security Council belong to it"],correctIndices:[1],explanation:"The Council of Europe (of which the UK is a member alongside around 46 European states) is separate from the EU; it has no power to make binding laws directly, but draws up conventions and charters, most famously the European Convention on Human Rights."},{id:"q-ex12-24",examNumber:12,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"How can local residents aged 18 or over volunteer to help set the strategic direction of a local state school, ensure accountability, and monitor financial performance in England?",options:["By applying to become a school governor (or member of a Parent Council in Scotland)","By joining the Shadow Cabinet","By registering as a parliamentary Whip","By applying to the Crown Prosecution Service"],correctIndices:[0],explanation:"People aged 18 or over can apply to serve as unpaid school governors (or on school boards / Parent Councils in Scotland), playing a vital community role in raising school standards: setting strategic direction, ensuring accountability, and monitoring financial performance."}],i=[{id:"q-ex13-01",examNumber:13,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"Can a person in the UK be prosecuted for violence towards their husband, wife, or partner inside marriage?",options:["Yes","No"],correctIndices:[0],explanation:"Domestic violence and abuse are serious crimes in the UK. Anyone who is violent towards their spouse or partner: whether they are married or living together, can be prosecuted under criminal law."},{id:"q-ex13-02",examNumber:13,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"How does the Life in the UK Test differ if you apply for settlement or citizenship in the Channel Islands or the Isle of Man?",options:["Some UK questions are replaced by questions specific to that island","You are exempt from taking any test altogether","The test takes 90 minutes and has 50 questions","The test is conducted orally in French or Manx Gaelic"],correctIndices:[0],explanation:"Although the Channel Islands and the Isle of Man use the Life in the UK Test framework for settlement and citizenship, applicants there sit a version containing local questions specific to their island alongside core UK material."},{id:"q-ex13-03",examNumber:13,chapterId:"ch2",subtopicId:"ch2-symbols",type:"multiple",prompt:"Which TWO parts of the United Kingdom have an official public bank holiday on their patron saint’s day? (Choose TWO)",options:["Scotland","Northern Ireland","England","Wales"],correctIndices:[0,1],explanation:"Although all four nations celebrate their patron saints, only Scotland (St Andrew’s Day on 30 November) and Northern Ireland (St Patrick’s Day on 17 March) have an official bank holiday for the occasion (though not every business closes in Scotland). England (St George’s Day) and Wales (St David’s Day) do not.",memoryHook:'Compass rule: only the two "northern" nations (Scotland in the north and Northern Ireland) get an official patron-saint bank holiday; England and Wales do not.',visualId:"national-emblems"},{id:"q-ex13-04",examNumber:13,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Which is the longest river in the United Kingdom, flowing for about 220 miles (354 km) through Wales and England?",options:["The River Thames","The River Clyde","The River Trent","The River Severn"],correctIndices:[3],explanation:"The River Severn (220 miles / 354 km) rises in Wales and flows through western England to the Bristol Channel, making it the UK’s longest river. The River Thames (215 miles) is the longest river entirely within England, but second overall in the UK!",memoryHook:'"Severn = Several": the Severn flows through several nations (Wales and England) as the UK’s #1 longest river, while the Thames is longest inside England alone.',visualId:"uk-map"},{id:"q-ex13-05",examNumber:13,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which British admiral commanded HMS Victory and defeated the combined French and Spanish fleets at the Battle of Trafalgar in 1805, losing his life in action?",options:["Sir Francis Drake","Admiral Horatio Nelson","The Duke of Wellington","Sir Walter Raleigh"],correctIndices:[1],explanation:"Admiral Horatio Nelson led the Royal Navy victory against the combined French and Spanish fleets at Trafalgar in 1805 and was killed during the battle. Nelson’s Column in Trafalgar Square honours him, and his flagship HMS Victory can still be visited in Portsmouth.",visualId:"history-timeline"},{id:"q-ex13-06",examNumber:13,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Who led the British and allied army that finally defeated Emperor Napoleon at the Battle of Waterloo in 1815?",options:["Sir Robert Walpole","Oliver Cromwell","The Duke of Wellington","Lord Palmerston"],correctIndices:[2],explanation:'In 1815, the French Wars ended when Emperor Napoleon was defeated by the Duke of Wellington at the Battle of Waterloo. Known as the "Iron Duke", Wellington later served as Prime Minister.',memoryHook:"You wear Wellington boots in water: the Duke of Wellington won at Waterloo (1815).",visualId:"history-timeline"},{id:"q-ex13-07",examNumber:13,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:"True or False: In 1846, Parliament repealed the Corn Laws, which had previously prevented the import of cheap grain into Britain.",options:["True","False"],correctIndices:[0],explanation:"During the Victorian era, Britain promoted free trade by abolishing taxes on imported goods. A landmark moment was the repeal of the Corn Laws in 1846, allowing cheaper imported grain and helping factory workers and manufacturers."},{id:"q-ex13-08",examNumber:13,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"Which event on 28 June 1914 set off the chain of events that led directly to the outbreak of the First World War?",options:["The assassination of Archduke Franz Ferdinand of Austria","Germany’s invasion of Poland","The sinking of the RMS Titanic","The signing of the Treaty of Versailles"],correctIndices:[0],explanation:"Although rising nationalism, militarism, and rival alliances created deep tension across Europe, the immediate trigger for the First World War in 1914 was the assassination of Archduke Franz Ferdinand of Austria on 28 June 1914.",visualId:"history-timeline"},{id:"q-ex13-09",examNumber:13,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"In which First World War offensive did British forces suffer around 60,000 casualties on the very first day, 1 July 1916?",options:["The Battle of Waterloo","The Battle of Britain","The Battle of Culloden","The Battle of the Somme"],correctIndices:[3],explanation:"The British attack on the Somme in July 1916 resulted in about 60,000 British casualties on the first day alone (1 July 1916). Over the whole First World War, there were more than 2 million British casualties (killed or wounded).",memoryHook:'"Somme = Sixty": around 60,000 British casualties on day one (1 July 1916).',visualId:"history-timeline"},{id:"q-ex13-10",examNumber:13,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"Which Scottish doctor discovered penicillin in 1928 while researching influenza, transforming modern medicine?",options:["John Macleod","Sir Alexander Fleming","Sir Ian Wilmut","Joseph Lister"],correctIndices:[1],explanation:"Born in Scotland, Alexander Fleming moved to London and discovered penicillin in 1928. Scientists Howard Florey and Ernst Chain later developed it into a mass-produced antibiotic drug, and Fleming won the Nobel Prize in Medicine in 1945.",memoryHook:'"Fl-eming" was researching "fl-u" (influenza) in 1928 when he spotted penicillin mould (unlike Lister = antiseptic or Macleod = insulin).'},{id:"q-ex13-11",examNumber:13,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"multiple",prompt:'Which TWO of the following were among the "Five Giant Evils" identified in William Beveridge’s famous 1942 report on welfare reform? (Choose TWO)',options:["Want","Inflation","Squalor","Taxation"],correctIndices:[0,2],explanation:"Economist William Beveridge’s 1942 report (Social Insurance and Allied Services) recommended that the government fight Five Giant Evils: Want, Disease, Ignorance, Squalor, and Idleness. It became the blueprint for Britain’s post-1945 welfare state.",memoryHook:'Mnemonic "SWIID": Squalor, Want, Ignorance, Idleness, Disease (watch the trap: the two I’s are Ignorance and Idleness, never Inflation).',visualId:"history-timeline"},{id:"q-ex13-12",examNumber:13,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"boolean",prompt:"Did the United Kingdom join the European Economic Community (EEC) when it was first established in 1957?",options:["Yes","No"],correctIndices:[1],explanation:"When West Germany, France, Belgium, Italy, Luxembourg, and the Netherlands formed the EEC in 1957, the UK chose not to join at first. The UK eventually joined the EEC in 1973 (alongside Denmark and the Republic of Ireland)."},{id:"q-ex13-13",examNumber:13,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which British Royal Air Force engineer developed the jet engine in the 1930s?",options:["Sir Robert Watson-Watt","Sir Christopher Cockerell","Sir Frank Whittle","Alan Turing"],correctIndices:[2],explanation:"Born in Coventry, RAF officer Sir Frank Whittle (1907–1996) invented and tested the turbojet engine in the 1930s, transforming global aviation.",memoryHook:'Phonetic link: Frank Whittle made the jet engine "whistle" through the sky.'},{id:"q-ex13-14",examNumber:13,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which Scottish physicist developed radar in the 1930s, using radio waves to detect approaching enemy aircraft before they could be seen?",options:["Sir Robert Watson-Watt","John Logie Baird","Sir Peter Mansfield","James Watt"],correctIndices:[0],explanation:"Sir Robert Watson-Watt (1892–1973) proposed using radio reflections to detect aircraft and conducted the first successful radar test in 1935, giving Britain a crucial defensive edge in the 1940 Battle of Britain.",memoryHook:"Double surname like a bouncing radar echo: Watson-Watt = radar (don’t confuse with James Watt = steam engine)."},{id:"q-ex13-15",examNumber:13,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which English artist (1776–1837) is famous for landscape paintings of Dedham Vale on the Suffolk–Essex border, including The Hay Wain?",options:["Hans Holbein","David Allan","David Hockney","John Constable"],correctIndices:[3],explanation:'John Constable (1776–1837) was one of Britain’s greatest landscape painters, celebrated for scenes of Dedham Vale ("Constable Country") such as The Hay Wain (1821). By contrast, Joseph Turner painted dramatic seascapes/light, Thomas Gainsborough painted portraits in landscapes, and David Allan ("the Scottish Hogarth") painted Scottish domestic scenes.'},{id:"q-ex13-16",examNumber:13,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO famous musical works were composed by German-born British citizen George Frideric Handel? (Choose TWO)",options:["Water Music","The Planets","Pomp and Circumstance Marches","Messiah"],correctIndices:[0,3],explanation:"George Frideric Handel (1695–1759) settled in Britain, became a British citizen in 1727, and wrote Water Music for King George I, Music for the Royal Fireworks for George II, and the choral masterpiece Messiah. (Gustav Holst wrote The Planets, and Sir Edward Elgar wrote the Pomp and Circumstance Marches.)",memoryHook:'Handel "handled" the elements and heaven: Water (Water Music), Fire (Music for the Royal Fireworks), and Messiah.'},{id:"q-ex13-17",examNumber:13,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"What is the prestigious Booker Prize awarded for every year?",options:["The best British classical music album","The best eligible novel in fiction","The best contemporary visual artwork displayed at Tate Britain","The best West End theatre direction"],correctIndices:[1],explanation:"Awarded annually since 1969, the Booker Prize recognises the best fiction novel (past winners include Salman Rushdie, Ian McEwan, and Hilary Mantel). Contemporary art is honoured by the Turner Prize, theatre by the Laurence Olivier Awards, and music by the BRIT Awards and Mercury Prize."},{id:"q-ex13-18",examNumber:13,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"single",prompt:"How many National Parks are there across England, Wales, and Scotland?",options:["8","12","15","24"],correctIndices:[2],explanation:"There are 15 National Parks in England, Wales, and Scotland: protected areas of natural countryside where people live, work, and visit (including the Lake District, Snowdonia in North Wales, and Loch Lomond and the Trossachs in Scotland).",memoryHook:"Think of 15 rugby players on green grass: 15 green National Parks across England, Wales, and Scotland.",visualId:"uk-map"},{id:"q-ex13-19",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In England, Wales, and Northern Ireland, in which court are most minor criminal offences heard?",options:["A Crown Court","A Sheriff Court","A Magistrates’ Court","The High Court"],correctIndices:[2],explanation:"In England, Wales, and Northern Ireland, most minor criminal cases are heard in a Magistrates’ Court by unpaid volunteer Justices of the Peace (magistrates) or a paid legally qualified District Judge, without a jury.",memoryHook:'"M for Minor = M for Magistrates’ Court" (serious criminal offences go to the Crown Court).',visualId:"parliament-courts"},{id:"q-ex13-20",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"How many people sit on a jury in a Scottish criminal trial, compared with 12 in England, Wales, and Northern Ireland?",options:["9","12","15","18"],correctIndices:[2],explanation:"In Scotland, serious criminal offences tried before a jury (in a Sheriff Court or the High Court of Justiciary) have a jury of 15 members, whereas juries in England, Wales, and Northern Ireland have 12 members.",memoryHook:'Scotland’s "Rule of 3": 3 extra jurors (15 instead of 12) and a 3rd verdict ("not proven").',visualId:"parliament-courts"},{id:"q-ex13-21",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"What is the maximum limit for using the informal small claims procedure in England and Wales (compared with £5,000 in Scotland and Northern Ireland)?",options:["£2,500","£5,000","£10,000","£25,000"],correctIndices:[2],explanation:"The small claims procedure helps people settle minor civil disputes (such as unpaid money or faulty goods) informally without high legal costs. It applies to claims under £10,000 in England and Wales, and £5,000 in Scotland and Northern Ireland.",memoryHook:'Visual digit anchor: the "S" in Scotland looks like a "5" (£5,000 in Scotland and NI), while England and Wales double it to £10,000.',visualId:"parliament-courts"},{id:"q-ex13-22",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"What is the minimum legal age to buy a National Lottery ticket or scratchcard in the UK?",options:["16","17","18","21"],correctIndices:[2],explanation:"People under 18 are not allowed to participate in the National Lottery (including Lotto draws and scratchcards); the minimum age was raised from 16 to 18 in 2021.",memoryHook:"Exam trap: older study guides still say 16, but the Lottery age is now 18, matching voting, buying alcohol, and buying tobacco."},{id:"q-ex13-23",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"For most salaried employees in the UK, which TWO payments are automatically deducted from wages by their employer through the PAYE (Pay As You Earn) system? (Choose TWO)",options:["Council Tax","Income Tax","National Insurance contributions","Vehicle Excise Duty (road tax)"],correctIndices:[1,2],explanation:"Under PAYE (Pay As You Earn), employers automatically deduct Income Tax and National Insurance contributions from employees’ pay and send them directly to HM Revenue & Customs (HMRC). Self-employed people pay via Self Assessment."},{id:"q-ex13-24",examNumber:13,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"True or False: People summoned for jury service in the UK are selected at random from the electoral register.",options:["True","False"],correctIndices:[0],explanation:"Anyone who is on the electoral register (register of electors) and within the eligible age range can be randomly selected to serve on a jury. Unless exempt or excused for good reason, you must attend."},{id:"q-ex14-01",examNumber:14,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"Which TWO of the following practices are serious criminal offences in the United Kingdom? (Choose TWO)",options:["An arranged marriage where both adults freely consent","Forced marriage, where one or both parties do not or cannot consent","Making a non-religious affirmation in court","Female genital mutilation (FGM)"],correctIndices:[1,3],explanation:"Forced marriage (forcing someone to marry against their will, distinguishable from a consensual arranged marriage) and female genital mutilation (FGM: or taking someone abroad for FGM) are severe criminal offences carrying prison sentences in the UK."},{id:"q-ex14-02",examNumber:14,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"boolean",prompt:"Do applicants without religious beliefs have to swear a religious oath on a holy book at a UK citizenship ceremony?",options:["Yes","No"],correctIndices:[1],explanation:'No. Reflecting freedom of religion and belief in the UK, those who do not wish to swear a religious oath ("I swear by Almighty God...") may make a solemn, non-religious affirmation ("I do solemnly, sincerely and truly declare and affirm...") instead.'},{id:"q-ex14-03",examNumber:14,chapterId:"ch2",subtopicId:"ch2-territories",type:"boolean",prompt:"True or False: The Channel Islands and the Isle of Man are part of the United Kingdom and are represented by MPs at Westminster.",options:["True","False"],correctIndices:[1],explanation:"False! The Channel Islands (such as Jersey and Guernsey) and the Isle of Man are Crown Dependencies: closely linked to the Crown, but NOT part of the UK. They have their own governments and tax systems and do not elect MPs to Westminster.",visualId:"uk-map"},{id:"q-ex14-04",examNumber:14,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Which mountain in the Scottish Highlands is the highest peak in the entire United Kingdom?",options:["Ben Nevis","Snowdon (Yr Wyddfa)","Scafell Pike","Slieve Donard"],correctIndices:[0],explanation:"Ben Nevis in Scotland (1,345m / 4,413 ft) is the highest mountain in both Scotland and the whole UK. For comparison, Snowdon is highest in Wales, Scafell Pike is highest in England, and Slieve Donard is highest in Northern Ireland.",visualId:"uk-map"},{id:"q-ex14-05",examNumber:14,chapterId:"ch2",subtopicId:"ch2-territories",type:"multiple",prompt:"Which TWO of the following are British Overseas Territories rather than Crown Dependencies? (Choose TWO)",options:["The Isle of Man","Guernsey","St Helena","Gibraltar"],correctIndices:[2,3],explanation:"St Helena (in the South Atlantic), Gibraltar (at the southern tip of Spain), and the Falkland Islands are British Overseas Territories linked to the UK, whereas the Isle of Man and Guernsey (Channel Islands) are Crown Dependencies.",memoryHook:"Map rule: islands right off Britain’s coast (Isle of Man, Channel Islands) are Crown Dependencies; distant outposts (Gibraltar, St Helena, Falklands) are Overseas Territories.",visualId:"national-emblems"},{id:"q-ex14-06",examNumber:14,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Where in London was the Great Exhibition of 1851 held to showcase exhibits from across the world and Britain’s industrial leadership?",options:["The Royal Albert Hall in Kensington","The Millennium Dome in Greenwich","Somerset House on the Strand","The Crystal Palace in Hyde Park"],correctIndices:[3],explanation:"Organised largely by Prince Albert, the Great Exhibition opened in 1851 in Hyde Park inside the Crystal Palace: a huge building constructed cleanly out of iron and glass.",visualId:"history-timeline"},{id:"q-ex14-07",examNumber:14,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"multiple",prompt:"Which TWO statements are true about the Crimean War (1853–1856), in which Britain fought with Turkey and France against Russia? (Choose TWO)",options:["It was the first war to be extensively covered by the media through news stories and photographs","Queen Victoria introduced the Victoria Cross medal to honour acts of valour by soldiers","It resulted in the immediate independence of India in 1856","It was the first war in which RAF Spitfire fighter aircraft were used"],correctIndices:[0,1],explanation:"The Crimean War (1853–56) was the first war extensively documented by newspaper correspondents and photographers, and during it Queen Victoria instituted the Victoria Cross (still Britain’s highest military honour for valour).",memoryHook:"Triple-C link: Crimea = Cameras (first media/photo war) + Crosses (the Victoria Cross)."},{id:"q-ex14-08",examNumber:14,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"boolean",prompt:"True or False: Florence Nightingale, who pioneered modern nursing at the military hospital in Scutari during the Crimean War, was born in Italy.",options:["True","False"],correctIndices:[0],explanation:"True! Florence Nightingale (1820–1910) was born in Italy (and named after the city of Florence) to English parents. In 1854 she went to Turkey to improve sanitation at the Scutari hospital, dramatically cutting mortality rates, and in 1860 established the Nightingale Training School for nurses at St Thomas’ Hospital in London."},{id:"q-ex14-09",examNumber:14,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"At what time and date did fighting in the First World War officially end?",options:["12.00 noon on 1 July 1916","11.00 am on 11 November 1918","9.00 am on 3 September 1939","6.00 am on 6 June 1944"],correctIndices:[1],explanation:'The First World War ended with the Armistice at 11.00 am on 11 November 1918 ("the eleventh hour of the eleventh day of the eleventh month") after Allied victory and more than 2 million British casualties.',visualId:"history-timeline"},{id:"q-ex14-10",examNumber:14,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"What name is given to the armed uprising by Irish nationalists in Dublin in April 1916 against British rule?",options:["The Jacobite Rising","The Easter Rising","The Glorious Revolution","The Peasants’ Revolt"],correctIndices:[1],explanation:"In April 1916, Irish nationalists staged the Easter Rising in Dublin and proclaimed an Irish Republic. Nationalist leaders were executed, and a guerrilla war against the British army and police followed until the 1921 Peace Treaty."},{id:"q-ex14-11",examNumber:14,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"multiple",prompt:"Which TWO fighter aircraft flown by the Royal Air Force were decisive in winning the aerial Battle of Britain in the summer of 1940? (Choose TWO)",options:["The Spitfire","Concorde","The Hurricane","The Harrier Jump Jet"],correctIndices:[0,2],explanation:"In the crucial aerial battle against the German Luftwaffe in the summer of 1940: the Battle of Britain, the Royal Air Force prevented a German invasion using British-built fighter planes: the Hawker Hurricane and the Supermarine Spitfire.",memoryHook:'Think "Fire and Wind": the Spitfire and the Hurricane won the 1940 Battle of Britain.'},{id:"q-ex14-12",examNumber:14,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Who became Prime Minister in 1945 when the Labour Party won a landslide general election victory at the end of the Second World War in Europe?",options:["Winston Churchill","Harold Macmillan","Clement Attlee","Neville Chamberlain"],correctIndices:[2],explanation:"Although Winston Churchill led Britain through WWII, voters seeking post-war social reform elected a Labour government in 1945 led by Clement Attlee (who had been Churchill’s wartime Deputy PM). Attlee’s government nationalised major industries and created the NHS and modern social security system.",visualId:"history-timeline"},{id:"q-ex14-13",examNumber:14,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Which famous ship arrived in Britain in 1948 carrying hundreds of people from the West Indies invited to come and help rebuild the post-war economy?",options:["HMT Empire Windrush","HMS Victory","SS Great Britain","The Golden Hind"],correctIndices:[0],explanation:'Faced with severe labour shortages after WWII, Britain encouraged workers from the West Indies, India, Pakistan, and later Bangladesh to work in transport, the NHS, and textiles. The arrival of HMT Empire Windrush in 1948 became a lasting symbol of the "Windrush generation".'},{id:"q-ex14-14",examNumber:14,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which Scottish inventor developed television in the 1920s and made the first transatlantic television broadcast between London and New York in 1928?",options:["Sir Tim Berners-Lee","Alexander Graham Bell","Guglielmo Marconi","John Logie Baird"],correctIndices:[3],explanation:"Scottish engineer John Logie Baird (1888–1946) demonstrated the first working television system in the 1920s and in 1932 made the first outdoor broadcast (showing the Derby horse race).",memoryHook:"Comms-pioneer check: Bell rings (telephone), Marconi sends radio, Baird broadcasts TV, Berners-Lee weaves the Web."},{id:"q-ex14-15",examNumber:14,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which British inventor experimented with tin cans and a vacuum-cleaner motor before inventing the hovercraft in the 1950s?",options:["Sir Frank Whittle","Sir Christopher Cockerell","Sir Clive Sinclair","Trevor Baylis"],correctIndices:[1],explanation:"Sir Christopher Cockerell (1910–1999) invented the hovercraft in the 1950s, enabling passenger and vehicle craft to glide smoothly on a cushion of air over water and land.",memoryHook:"Visual pun: a cockerel (rooster) can’t fly high, it just flaps and hovers above the ground (Cockerell = Hovercraft)."},{id:"q-ex14-16",examNumber:14,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which two British inventors are credited with pioneering the automatic teller machine (ATM) or cash dispenser in the late 1960s?",options:["Patrick Steptoe and Robert Edwards","Sir Ian Wilmut and Keith Campbell","James Goodfellow and John Shepherd-Barron","Charles Barry and Augustus Pugin"],correctIndices:[2],explanation:"Scottish inventor James Goodfellow (who patented PIN-based cash machine technology in 1966) and John Shepherd-Barron (whose first cash dispenser was installed by Barclays Bank in Enfield, north London, in 1967) pioneered the ATM.",memoryHook:'Name wordplay: getting cash from an ATM makes you feel like a rich "Baron" and a "Goodfellow" (Shepherd-Barron and Goodfellow).'},{id:"q-ex14-17",examNumber:14,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"In the 19th century, which TWO figures collaborated on the Gothic Revival rebuilding of the Houses of Parliament (Palace of Westminster), designing its exterior architecture and ornate interiors? (Choose TWO)",options:["Sir Charles Barry","Sir Christopher Wren","Robert Adam","Augustus Pugin"],correctIndices:[0,3],explanation:'In the 19th century, medieval Gothic style revived ("Gothic Revival"). Architect Sir Charles Barry won the competition to rebuild the Houses of Parliament after the 1834 fire, while Augustus Pugin designed its famous Gothic interiors, wallpaper, furniture, and the Elizabeth Tower clock face. (Wren built St Paul’s; Robert Adam was 18th-century neoclassical.)',memoryHook:"Alliteration: Barry built the Building (exterior); Pugin polished the Pointed Gothic interiors."},{id:"q-ex14-18",examNumber:14,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"single",prompt:"Which is England’s largest National Park, home to Windermere and to Wastwater (voted Britain’s favourite view in 2007)?",options:["The Lake District","Snowdonia","The Peak District","Dartmoor"],correctIndices:[0],explanation:"Covering 885 square miles (2,292 sq km) in north-west England, the Lake District is England’s largest National Park, famous for its lakes and mountains and inspiring poets like William Wordsworth and author Beatrix Potter. In 2007, viewers voted Wastwater in the Lake District Britain’s favourite view.",visualId:"uk-map"},{id:"q-ex14-19",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:'In Scotland, a criminal jury can return "guilty" or "not guilty", as well as which unique third verdict?',options:["Adjourned","No contest","Unlawful","Not proven"],correctIndices:[3],explanation:'Unlike courts in England, Wales, and Northern Ireland (which only have "guilty" and "not guilty"), a 15-person Scottish jury has a third possible verdict: "not proven" (which acquits the accused with the same legal effect as not guilty).',visualId:"parliament-courts"},{id:"q-ex14-20",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In Scotland, minor criminal offences are handled in which court (while more serious cases go to a Sheriff Court or the High Court)?",options:["A Crown Court","A Justice of the Peace Court","A County Court","A Coroners’ Court"],correctIndices:[1],explanation:"In Scotland, minor criminal offences go to a Justice of the Peace Court. Serious cases in Scotland are heard in a Sheriff Court (with either a sheriff alone or a sheriff plus a 15-person jury) or, for the most serious crimes such as murder, the High Court of Justiciary.",visualId:"parliament-courts"},{id:"q-ex14-21",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Which telephone number should you dial in the UK to contact the police when reporting a non-emergency crime (for example, a stolen bicycle with no immediate danger)?",options:["999","112","101","111"],correctIndices:[2],explanation:"You should dial 999 or 112 ONLY in genuine emergencies requiring immediate police, fire, ambulance, or coastguard assistance. For non-emergency police matters across the UK, dial 101 (whereas 111 is for non-emergency NHS medical advice).",memoryHook:'101 vs 111 trick: the "0" in 101 looks like a handcuff ring (Police non-emergency), while 111 looks like three thermometers (NHS non-emergency).'},{id:"q-ex14-22",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"Can a 16- or 17-year-old legally drink wine, beer, or cider with a meal in a hotel or restaurant in the UK if accompanied by someone aged 18 or over?",options:["Yes","No"],correctIndices:[0],explanation:"Yes! Although it is a criminal offence anywhere in the UK to sell alcohol to anyone under 18, there is one narrow exception: people aged 16 or 17 may drink wine, beer, or cider (not spirits!) with a table meal in a hotel or restaurant when accompanied by an adult who buys it."},{id:"q-ex14-23",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Once a car reaches what age must it pass an annual MOT (Ministry of Transport) test to remain legal on UK public roads?",options:["One year old","Two years old","Three years old","Five years old"],correctIndices:[2],explanation:"If your vehicle is over three years old, you must take it for a Ministry of Transport (MOT) test every year to verify roadworthiness and exhaust emissions. It is an offence to drive without a valid driving licence, motor insurance, road tax, or required MOT certificate.",memoryHook:"Letter count: M-O-T has 3 letters, and a car needs an annual MOT once it is 3 years old."},{id:"q-ex14-24",examNumber:14,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Which tax, based on the valuation band of a residential property, is collected by local authorities to help pay for local services such as libraries, street lighting, and rubbish collection?",options:["Council Tax","Value Added Tax (VAT)","Corporation Tax","National Insurance"],correctIndices:[0],explanation:"Local authorities are funded by money from central government and by Council Tax, paid by households based on property value (with discounts or exemptions available, such as for single occupants or full-time students). Note: Northern Ireland uses a domestic rates system for the same purpose."},{id:"q-ex15-01",examNumber:15,chapterId:"ch1",subtopicId:"ch1-principles",type:"single",prompt:"What is the core purpose of UK equality and anti-discrimination laws (consolidated in Great Britain under the Equality Act)?",options:["To guarantee identical salaries for all jobs regardless of skill or hours worked","To require every private business to employ an equal number of people from all four UK nations","To abolish competitive job interviews in the civil service","To ensure nobody is treated unfairly because of characteristics such as age, disability, sex, race, religion, marital status, or sexual orientation"],correctIndices:[3],explanation:"UK laws protect citizens and residents from unfair discrimination in work, housing, and public services on grounds including age, disability, sex, pregnancy/maternity, race, religion or belief, marital/civil partnership status, gender reassignment, and sexual orientation."},{id:"q-ex15-02",examNumber:15,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"multiple",prompt:"Besides passing the Life in the UK Test, settlement/citizenship applicants usually need B1-level speaking and listening in English, Welsh, or Scottish Gaelic. Which TWO groups are exempt from taking a separate English test? (Choose TWO)",options:["Anyone who has visited London as a tourist three times","Applicants aged 65 or over","Citizens of recognised majority English-speaking countries (or holders of a recognised degree taught in English)","Anyone who holds a full UK driving licence"],correctIndices:[1,2],explanation:"Applicants usually demonstrate English at CEFR level B1 (ESOL Entry Level 3), unless exempt: notably applicants aged 65+ (or with a qualifying long-term physical/mental condition), nationals of majority English-speaking countries, or those holding an approved academic degree taught or researched in English."},{id:"q-ex15-03",examNumber:15,chapterId:"ch2",subtopicId:"ch2-nations",type:"boolean",prompt:'Does the name "Great Britain" include Northern Ireland?',options:["Yes","No"],correctIndices:[1],explanation:'No! "Great Britain" refers ONLY to England, Scotland, and Wales (the largest island). The official name of the sovereign country including Northern Ireland is "The United Kingdom of Great Britain and Northern Ireland".',memoryHook:'Grammar proof inside the full name: "United Kingdom of Great Britain AND Northern Ireland" uses "and" because Northern Ireland is separate from Great Britain.',visualId:"uk-map"},{id:"q-ex15-04",examNumber:15,chapterId:"ch2",subtopicId:"ch2-territories",type:"single",prompt:"Where is Tynwald, which has met continuously for over 1,000 years and is often called the oldest continuous parliament in the world?",options:["Jersey","The Isle of Man","Orkney","Gibraltar"],correctIndices:[1],explanation:"The Isle of Man (a Crown Dependency in the Irish Sea) has its own parliament called Tynwald, which has Norse origins and is the world’s oldest continuous parliamentary body.",memoryHook:'Phonetic link: "Tyn-wald" sounds like the "Tin Man", pointing straight to the Isle of Man.'},{id:"q-ex15-05",examNumber:15,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"multiple",prompt:"Which TWO famous Victorian engineering projects were built by Isambard Kingdom Brunel (originally from Portsmouth)? (Choose TWO)",options:["St Paul’s Cathedral in London","The Great Western Railway (running from Paddington to the south-west and Wales)","The Cenotaph on Whitehall","The Clifton Suspension Bridge spanning the Avon Gorge in Bristol"],correctIndices:[1,3],explanation:"Isambard Kingdom Brunel (1806–1859) engineered tunnels, bridges, ships (such as the iron-hulled SS Great Britain), the Great Western Railway, and the iconic Clifton Suspension Bridge across the Avon Gorge in Bristol.",memoryHook:'Geography link "Brunel = Bristol and the West": Great Western Railway, Bristol’s Clifton Suspension Bridge, and Bristol’s SS Great Britain.'},{id:"q-ex15-06",examNumber:15,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which author and poet was born in India in 1865, won the Nobel Prize in Literature in 1907, and wrote The Jungle Book and the poem If?",options:["Thomas Hardy","Robert Louis Stevenson","Rudyard Kipling","Graham Greene"],correctIndices:[2],explanation:"Rudyard Kipling (1865–1936) was born in India and lived in India, the UK, and the USA. Reflecting the idea that the British Empire was a force for good, his works include The Jungle Book, Just So Stories, and the beloved poem If."},{id:"q-ex15-07",examNumber:15,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"In the Boer War of 1899 to 1902 in South Africa, with whom did the British go to war?",options:["Settlers from the Netherlands called the Boers","French colonial troops from Algeria","Spanish naval forces from Cuba","Russian imperial regiments"],correctIndices:[0],explanation:"The Boer War (1899–1902) took place in South Africa against settlers originally from the Netherlands known as the Boers. Lasting over three years with heavy casualties from fighting and disease, it sparked public questioning about the future of the Empire.",memoryHook:'Etymology link: "boer" is the Dutch word for farmer, connecting the South African Boers to the Netherlands.'},{id:"q-ex15-08",examNumber:15,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"What happened in Ireland in 1922 as a result of the 1921 Peace Treaty signed with the British government?",options:["The whole island of Ireland became an independent republic immediately","Northern Ireland joined Scotland under a shared parliament in Edinburgh","Ireland first joined the United Kingdom under a new Act of Union","Ireland was divided into two: six mainly Protestant northern counties remained in the UK as Northern Ireland, and the rest became the Irish Free State"],correctIndices:[3],explanation:"In 1921 a peace treaty was signed and in 1922 Ireland split into two countries: the six northern, mainly Protestant counties remained part of the UK under the name Northern Ireland (with a devolved parliament at Stormont), while the rest became the Irish Free State (which became a republic in 1949).",memoryHook:"Digit anchor: 1921 = 1 peace treaty signed; 1922 = Ireland split into 2 (Northern Ireland + the Irish Free State)."},{id:"q-ex15-09",examNumber:15,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"boolean",prompt:"True or False: In 1936, the British Broadcasting Corporation (BBC) began the world’s first regular public television service.",options:["True","False"],correctIndices:[0],explanation:"True! Following the start of radio broadcasts in 1922, the BBC launched the world’s first regular high-definition public television service from Alexandra Palace in London in 1936."},{id:"q-ex15-10",examNumber:15,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"What aggressive act by Adolf Hitler caused Britain and France to declare war on Germany in September 1939?",options:["The bombing of Pearl Harbor","The invasion of Poland","The occupation of the Rhineland in 1936","The sinking of HMS Hood"],correctIndices:[1],explanation:"After Nazi Germany occupied Austria and invaded Czechoslovakia, Adolf Hitler invaded Poland on 1 September 1939. Honouring their guarantee to Poland, Britain and France declared war on Germany on 3 September 1939.",visualId:"history-timeline"},{id:"q-ex15-11",examNumber:15,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Which Minister of Health led the establishment of the National Health Service (NHS) in 1948?",options:["William Beveridge","R. A. Butler",'Aneurin ("Nye") Bevan',"Anthony Eden"],correctIndices:[2],explanation:'In 1948, Welsh Labour Minister of Health Aneurin ("Nye") Bevan led the creation of the National Health Service (NHS), guaranteeing a minimum standard of healthcare for all, free at the point of use. (Watch the classic trap: Beveridge wrote the 1942 report; Butler passed the 1944 Education Act; Bevan launched the 1948 NHS!)',memoryHook:'Triple-B trap: Beveridge wrote the 1942 report, Butler reformed schools (1944), and "Nye" Bevan launched the NHS (1948: Nye = NHS).'},{id:"q-ex15-12",examNumber:15,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Who became the United Kingdom’s first woman Prime Minister in 1979 and led the country during the 1982 Falklands War?",options:["Margaret Thatcher","Emmeline Pankhurst","Theresa May","Barbara Castle"],correctIndices:[0],explanation:"Conservative leader Margaret Thatcher became the UK’s first female Prime Minister in 1979 and served until 1990 (the longest-serving PM of the 20th century). Her government privatised nationalised industries, deregulated London’s financial markets, and sent a taskforce to recover the Falkland Islands after Argentina invaded in 1982.",visualId:"history-timeline"},{id:"q-ex15-13",examNumber:15,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which British computer scientist invented the World Wide Web, successfully transferring information via the web for the first time on 25 December 1990?",options:["Alan Turing","Sir Clive Sinclair","James Dyson","Sir Tim Berners-Lee"],correctIndices:[3],explanation:"British scientist Sir Tim Berners-Lee (born 1955) invented the World Wide Web (HTTP, HTML, and URLs), putting the first webpage live and transferring data via the web on Christmas Day 1990."},{id:"q-ex15-14",examNumber:15,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:'Which British mathematician developed the theoretical "Turing machine" in the 1930s and played a key role in cracking German wartime codes at Bletchley Park?',options:["Sir Peter Mansfield","Alan Turing","Francis Crick","Stephen Hawking"],correctIndices:[1],explanation:'Alan Turing (1912–1954) proposed the "Turing machine": a mathematical model of computation foundational to modern computer science: and worked at Bletchley Park breaking German Enigma ciphers during WWII. His portrait now appears on the Bank of England £50 note.'},{id:"q-ex15-15",examNumber:15,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which 20th-century English artist from Yorkshire is best known for large, abstract cast-bronze sculptures featuring reclining figures and hollowed-out spaces?",options:["David Hockney","John Petts","Henry Moore","Thomas Gainsborough"],correctIndices:[2],explanation:"Henry Moore (1898–1986) gained international fame for monumental abstract bronze and stone sculptures inspired by the human figure and landscape. (David Hockney was a major Pop art figure; John Petts was a Welsh engraver and stained-glass artist.)",memoryHook:'Name pun: "Less solid bronze, MOORE hollow space" = Henry Moore’s hollowed-out bronze sculptures.'},{id:"q-ex15-16",examNumber:15,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:'Which London venue hosts the main concerts (including the famous "Last Night") of the BBC Proms, an eight-week summer season of daily orchestral classical music?',options:["The Royal Albert Hall","The Globe Theatre","Wembley Stadium","Tate Modern"],correctIndices:[0],explanation:'Organised by the BBC since 1927, The Proms ("Promenade Concerts") is an eight-week summer festival of more than 70 concerts held in various venues across the UK, centred on the Royal Albert Hall in London.'},{id:"q-ex15-17",examNumber:15,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which British animator has won four Oscars for animated films, including three featuring Wallace and Gromit?",options:["Sir Ridley Scott","Sir Alfred Hitchcock","Sir David Lean","Nick Park"],correctIndices:[3],explanation:"Britain remains a powerhouse in animation and special effects: Nick Park won four Academy Awards for stop-motion animations, including three starring eccentric inventor Wallace and his loyal dog Gromit. (Hitchcock, Lean, and Ridley Scott are celebrated live-action British film directors.)",memoryHook:"Visual link: you walk a dog like Gromit in the PARK (Nick Park = Wallace and Gromit)."},{id:"q-ex15-18",examNumber:15,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"single",prompt:"In which English county is the Eden Project located, famous for its giant bubble-like biomes housing plants from around the world?",options:["Cumbria","Cornwall","Kent","Northumberland"],correctIndices:[1],explanation:"The Eden Project is located in Cornwall, in the south-west of England. Its giant rainforest and Mediterranean biomes are also a charity running environmental and social projects internationally.",visualId:"uk-map"},{id:"q-ex15-19",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"True or False: In England, Wales, and Northern Ireland, members of the general public are freely allowed inside Youth Courts to watch cases involving 10- to 17-year-olds.",options:["True","False"],correctIndices:[1],explanation:"False! Youth Courts hear cases for young people aged 10 to 17 (presided over by up to three specially trained magistrates or a District Judge). Members of the public are NOT allowed in Youth Courts, and the accused young person’s name or photograph cannot normally be published in the media.",visualId:"parliament-courts"},{id:"q-ex15-20",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In Scotland, which specialised system deals with children and young people who have committed an offence or are in need of care and protection?",options:["The Coroners’ Bench","The Privy Council Panel","The Children’s Hearings System","The Small Claims Tribunal"],correctIndices:[2],explanation:"Instead of Youth Courts (used in England, Wales, and Northern Ireland), Scotland uses a welfare-focused system called the Children’s Hearings System when children or young people commit offences or require protection.",visualId:"parliament-courts"},{id:"q-ex15-21",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"Do directly elected Police and Crime Commissioners (PCCs) in England and Wales instruct the police on whom to arrest in day-to-day operational policing?",options:["Yes","No"],correctIndices:[1],explanation:"No! The police service is operationally independent of government and politicians. Elected Police and Crime Commissioners (PCCs) in England and Wales set local police priorities, agree the local policing budget, and appoint (or dismiss) the Chief Constable, but cannot interfere in individual arrests or investigations."},{id:"q-ex15-22",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO of the following are examples of civil law matters rather than criminal law offences? (Choose TWO)",options:["Carrying a concealed weapon in a public street","Selling tobacco or alcohol to someone under 18","Disputes between landlords and tenants over a housing lease","Claims of unfair dismissal or discrimination in the workplace"],correctIndices:[2,3],explanation:"Civil law settles disputes between individuals or groups: including housing law (landlord/tenant disputes), consumer rights, employment law (unfair dismissal), debt, and family law. Carrying weapons and underage sales of tobacco/alcohol are criminal offences prosecuted by the state."},{id:"q-ex15-23",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"In which TWO situations are you required by law to hold a valid TV Licence in the UK (unless covered by an exemption such as aged 75+ receiving Pension Credit)? (Choose TWO)",options:["Watching or recording live television programmes on any channel or device","Downloading or watching any programme on BBC iPlayer","Listening exclusively to FM or digital radio stations in your car","Playing offline video games on a television monitor"],correctIndices:[0,1],explanation:"By law, a household needs a TV Licence (which funds the BBC) to watch or record programmes as they are being shown live on TV or an online TV service on any device (TV, laptop, phone), OR to download/watch any content on BBC iPlayer. Watching without a licence is a criminal offence carrying a fine up to £1,000."},{id:"q-ex15-24",examNumber:15,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"While most young people born or raised in the UK are sent a National Insurance (NI) number just before their 16th birthday, whom must a new adult resident with permission to work contact to apply for one?",options:["The Department for Work and Pensions (DWP)","The Driver and Vehicle Licensing Agency (DVLA)","Their local County Court","The Electoral Commission"],correctIndices:[0],explanation:"A National Insurance number ensures your tax and NI contributions are properly recorded against your name. Anyone with permission to work in the UK who does not already have an NI number applies for one through the Department for Work and Pensions (DWP) / Jobcentre Plus (or gov.uk). (Note: having an NI number alone does NOT prove the right to work!)",memoryHook:"NI tracks your Work contributions toward your State Pension, so you apply to the Department for Work and Pensions (DWP, not HMRC)."},{id:"q-ex16-01",examNumber:16,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"True or False: Looking after the area in which you live and protecting the environment is one of the shared responsibilities of everyone living in the UK.",options:["True","False"],correctIndices:[0],explanation:"True! Alongside obeying the law, respecting others’ rights and opinions, treating others fairly, and looking after yourself and your family, everyone in the UK shares the responsibility to look after their local area and the environment."},{id:"q-ex16-02",examNumber:16,chapterId:"ch1",subtopicId:"ch1-citizenship",type:"single",prompt:"At a UK Citizenship Ceremony, to whom do new citizens swear or affirm faithful allegiance in the Oath (or Affirmation) of Allegiance?",options:["The Prime Minister and the Cabinet","The Speaker of the House of Commons","The Supreme Court of the United Kingdom","His Majesty King Charles III, His Heirs and Successors"],correctIndices:[3],explanation:"New adult British citizens swear (or affirm) faithful allegiance to His Majesty King Charles III, His Heirs and Successors according to law, followed by a Pledge of loyalty to the United Kingdom and its democratic rights, freedoms, and laws."},{id:"q-ex16-03",examNumber:16,chapterId:"ch2",subtopicId:"ch2-symbols",type:"boolean",prompt:"True or False: The Welsh red dragon appears at the centre of the official Union Flag alongside the crosses of St George, St Andrew, and St Patrick.",options:["True","False"],correctIndices:[1],explanation:"False! The official Union Flag combines ONLY three crosses (St George for England, St Andrew for Scotland, and St Patrick for Ireland). Because the Principality of Wales was already united with England when the first Union Flag was created in 1606, the Welsh dragon does not appear on it.",visualId:"union-jack"},{id:"q-ex16-04",examNumber:16,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Which peak in the Mourne Mountains is the highest mountain in Northern Ireland?",options:["Ben Nevis","Slieve Donard","Snowdon","Scafell Pike"],correctIndices:[1],explanation:"Slieve Donard (850m / 2,789 ft) in the Mourne Mountains, County Down, is the highest peak in Northern Ireland. (Ben Nevis is highest in Scotland/UK, Snowdon in Wales, and Scafell Pike in England.)",memoryHook:'Peak word roots: "Slieve" is Irish for mountain (Slieve Donard in County Down = NI), "Ben" is Scottish (Ben Nevis), and "Fell" is English Lake District (Scafell Pike).',visualId:"uk-map"},{id:"q-ex16-05",examNumber:16,chapterId:"ch2",subtopicId:"ch2-territories",type:"boolean",prompt:"True or False: Banknotes issued by designated banks in Scotland and Northern Ireland are valid currency across the UK, even though shops are not legally obliged to accept them.",options:["True","False"],correctIndices:[0],explanation:"True! Both Northern Ireland and Scotland have their own banknotes (£5, £10, £20, £50, etc.) which are valid currency everywhere in the UK; however, shops and businesses have legal discretion over whether to accept them."},{id:"q-ex16-06",examNumber:16,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Who was born in Manchester in 1858 and founded the Women’s Social and Political Union (WSPU) in 1903 to campaign for women’s right to vote?",options:["Florence Nightingale","Mary Seacole","Emmeline Pankhurst","Octavia Hill"],correctIndices:[2],explanation:'Emmeline Pankhurst (1858–1928), born in Manchester, set up the Women’s Franchise League in 1889 and founded the WSPU in 1903. Its members: called "suffragettes", used civil disobedience, chaining themselves to railings, smashing windows, and going on hunger strike for women’s suffrage.',visualId:"history-timeline"},{id:"q-ex16-07",examNumber:16,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"How were women granted the right to vote in UK parliamentary elections across the 1918 and 1928 Acts?",options:["Women aged 30+ (meeting property rules) gained the vote in 1918, and in 1928 the voting age was lowered to 21 on equal terms with men","All women aged 18+ won the vote in 1903, lowered to 16 in 1928","Women aged 25+ gained the vote in 1914, and men lost property requirements in 1945","Women first gained the right to vote in 1948 alongside the creation of the NHS"],correctIndices:[0],explanation:"In 1918, in recognition of women’s vital contribution to the First World War effort, women over 30 who were householders (or married to householders) gained the vote and the right to stand for Parliament. In 1928: shortly before Emmeline Pankhurst died, women were given the vote at age 21, equal to men.",memoryHook:"Exam trap: equal voting in 1928 meant age 21, not 18 (1918 = women 30+; 1928 = all adults 21+; 1969 = lowered to 18)."},{id:"q-ex16-08",examNumber:16,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"What major nine-day industrial conflict took place in Britain in May 1926 when transport and industrial workers walked out in support of coal miners facing wage cuts?",options:["The Winter of Discontent","The Tolpuddle Protest","The Chartist March","The General Strike"],correctIndices:[3],explanation:"In 1926, disagreement between coal mine owners and miners over pay and working conditions led the Trades Union Congress (TUC) to call the General Strike, bringing much of British transport and heavy industry to a standstill."},{id:"q-ex16-09",examNumber:16,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:'Who replaced Neville Chamberlain as Prime Minister in May 1940 and inspired Britain during WWII with lines such as "I have nothing to offer but blood, toil, tears and sweat"?',options:["David Lloyd George","Winston Churchill","Clement Attlee","Anthony Eden"],correctIndices:[1],explanation:"When Germany invaded France, Belgium, and the Netherlands in May 1940, Winston Churchill (1874–1965) became Prime Minister of a cross-party wartime coalition. In 2002, he was voted the Greatest Briton of all time by the public.",visualId:"history-timeline"},{id:"q-ex16-10",examNumber:16,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:"Roughly how many British and Allied troops were rescued from the beaches of Dunkirk in France in late May and early June 1940 with the help of Royal Navy warships and small civilian boats?",options:["Around 25,000 men","Around 60,000 men","More than 300,000 men","More than 2 million men"],correctIndices:[2],explanation:'During the Evacuation of Dunkirk in 1940, hundreds of volunteer civilian pleasure boats and fishing vessels crossed the Channel alongside the Royal Navy under heavy fire, rescuing more than 300,000 British and French soldiers and giving rise to the phrase "the Dunkirk spirit".',memoryHook:"War-number check: 60,000 = Somme day-one casualties; 300,000+ = troops rescued at Dunkirk; 2 million+ = total British WWI casualties."},{id:"q-ex16-11",examNumber:16,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:'What major reform did Conservative Minister R. A. Butler introduce through the Education Act 1944 (often called "the Butler Act")?',options:["Free university tuition for all overseas students","Compulsory Latin examinations for all civil servants","Free secondary education in England and Wales and a clear split between primary and secondary schools","The abolition of all independent fee-paying schools"],correctIndices:[2],explanation:'Even before WWII ended, R. A. Butler oversaw the Education Act 1944 ("the Butler Act"), introducing free secondary education for all pupils in England and Wales and establishing a clear division between primary and secondary schooling (usually at age 11).'},{id:"q-ex16-12",examNumber:16,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"multiple",prompt:"In 1947, independence was granted to nine colonies/territories: most famously including which TWO new independent South Asian nations? (Choose TWO)",options:["India","Australia","Pakistan","Canada"],correctIndices:[0,2],explanation:"Under Clement Attlee’s post-war government, decolonisation accelerated: in 1947 independence was granted to India and Pakistan (with Ceylon, now Sri Lanka: following in 1948), beginning a peaceful transition from Empire to Commonwealth."},{id:"q-ex16-13",examNumber:16,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Building on peace talks begun under Prime Minister John Major, which historic 1998 accord signed under Tony Blair’s Labour government established a power-sharing Northern Ireland Assembly?",options:["The Good Friday (Belfast) Agreement","The Treaty of Runnymede","The Statute of Rhuddlan","The Maastricht Treaty"],correctIndices:[0],explanation:"Elected in 1997, Tony Blair’s government built on the Northern Ireland peace process started by Conservative PM John Major, concluding the Good Friday Agreement (Belfast Agreement) in 1998 and delivering devolved parliaments/assemblies to Scotland, Wales, and Northern Ireland.",visualId:"history-timeline"},{id:"q-ex16-14",examNumber:16,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO pioneering reproductive and genetic breakthroughs were achieved in Britain in 1978 and 1996 respectively? (Choose TWO)",options:['The birth of the world’s first "test-tube baby" via in-vitro fertilisation (IVF), pioneered by Patrick Steptoe and Sir Robert Edwards',"Performing the world’s first vaccination against smallpox by Edward Jenner","Discovering the circulation of blood by William Harvey","Cloning the first mammal from an adult cell: Dolly the sheep, led by Sir Ian Wilmut and Keith Campbell"],correctIndices:[0,3],explanation:'Gynaecologist Patrick Steptoe and physiologist Sir Robert Edwards pioneered IVF therapy, leading to the world’s first "test-tube baby" (Louise Brown) in Oldham in 1978. In 1996 at the Roslin Institute in Scotland, Sir Ian Wilmut and Keith Campbell cloned Dolly the sheep, the first mammal cloned from an adult somatic cell.',memoryHook:'Name hooks: "Step-toe" = a baby’s first steps/toes (Steptoe and Edwards = IVF baby, 1978); "Wil-mut" sounds like wool/mutton (Wilmut and Campbell = Dolly the sheep, 1996).'},{id:"q-ex16-15",examNumber:16,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which British scientist co-invented the MRI (magnetic resonance imaging) scanner, enabling doctors to obtain detailed internal images of the human body without surgery or X-rays?",options:["Sir Christopher Cockerell","John Logie Baird","Sir Frank Whittle","Sir Peter Mansfield"],correctIndices:[3],explanation:"Physicist Sir Peter Mansfield (1933–2017) of the University of Nottingham co-invented the MRI scanner, earning the 2003 Nobel Prize in Physiology or Medicine for transforming modern medical imaging.",memoryHook:'Name link: "M" for Mansfield = "M" for MRI, scanning inside a "Man".'},{id:"q-ex16-16",examNumber:16,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which 20th-century British architect designed war memorials across the world: including the Cenotaph on Whitehall in London, as well as New Delhi for the British government in India?",options:["Robert Adam","Sir Edwin Lutyens","Sir Norman Foster","Dame Zaha Hadid"],correctIndices:[1],explanation:"Sir Edwin Lutyens (1869–1944) designed New Delhi and after WWI created the Cenotaph in Whitehall, the centrepiece of Britain’s annual Remembrance Day ceremony. (Robert Adam was 18th-century neoclassical; Norman Foster, Richard Rogers, and Zaha Hadid are renowned contemporary British architects.)"},{id:"q-ex16-17",examNumber:16,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO major annual UK prizes recognise contemporary visual art (hosted at Tate Britain) and excellence in London theatre, respectively? (Choose TWO)",options:["The Mercury Prize","The Turner Prize","The Laurence Olivier Awards","The BAFTA Awards"],correctIndices:[1,2],explanation:"Established in 1984 and named after painter Joseph Turner, the Turner Prize celebrates contemporary art (shortlisted works exhibited at Tate Britain). Named after legendary actor Lord Olivier, the Laurence Olivier Awards honour professional London/West End theatre. (Mercury & BRITs are for music; BAFTAs are for film and TV.)"},{id:"q-ex16-18",examNumber:16,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"boolean",prompt:'True or False: "Big Ben" is officially the name of the clock tower at the Houses of Parliament, rather than the great bell inside it.',options:["True","False"],correctIndices:[1],explanation:'False! "Big Ben" is actually the nickname for the great bell of the striking clock (over 150 years old). The clock tower itself: once simply called the Clock Tower, was officially renamed "Elizabeth Tower" in 2012 to mark Queen Elizabeth II’s Diamond Jubilee! Nearby London icons include the 443-foot (135m) London Eye and the Tower of London (where Yeoman Warders, or "Beefeaters", guard the Crown Jewels).'},{id:"q-ex16-19",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Established in October 2009 to replace the judicial role of the House of Lords, what is the final and highest court of appeal in the United Kingdom?",options:["The Crown Court","The High Court of Justice","The Supreme Court of the UK","The Privy Magistrates’ Chamber"],correctIndices:[2],explanation:"The Supreme Court of the UK sits in Parliament Square, London, and serves as the final court of appeal for all UK civil cases and for criminal cases from England, Wales, and Northern Ireland (Scottish criminal appeals stop at the High Court of Justiciary in Edinburgh except on devolution/human-rights points).",visualId:"parliament-courts"},{id:"q-ex16-20",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In England, Wales, and Northern Ireland, where are serious criminal offences (such as robbery or murder) tried before a judge and a 12-person jury?",options:["A Crown Court","A Magistrates’ Court","A County Court","A Small Claims Court"],correctIndices:[0],explanation:'In England, Wales, and Northern Ireland, serious ("indictable") criminal cases are tried in a Crown Court with a professional judge and a jury of 12 members of the public chosen randomly from the electoral register.',memoryHook:"Don’t confuse the two C-courts: Crown Court = serious Crime (prosecuted by the Crown with a jury); County Court = Civil disputes.",visualId:"parliament-courts"},{id:"q-ex16-21",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Which well-known independent charity provides free, confidential information and advice across the UK to help people with legal, debt, consumer, and housing problems (and can help find a solicitor)?",options:["The National Trust","Hansard","The Crown Prosecution Service","Citizens Advice"],correctIndices:[3],explanation:"Citizens Advice (formerly Citizens Advice Bureau) offers free, impartial practical guidance online and in local offices on consumer, housing, employment, benefits, and legal issues, and can point you toward qualified solicitors (trained lawyers who advise clients, prepare documents, and negotiate settlements)."},{id:"q-ex16-22",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In the UK, what are the minimum ages at which you can legally ride a moped (up to 50cc) and drive a car on public roads, respectively?",options:["15 for a moped and 16 for a car","16 for a moped and 17 for a car","17 for a moped and 18 for a car","18 for both a moped and a car"],correctIndices:[1],explanation:"To apply for a provisional licence and ride a moped (maximum engine size 50cc, top speed 28 mph / 45 km/h), you must be at least 16. To drive a car, you must be at least 17 (or 16 if receiving the higher/enhanced mobility rate of disability benefit) and pass both a computer theory test and practical driving test.",memoryHook:"16-17-18 age ladder: 16 = Moped (up to 50cc), 17 = Car, 18 = Adult milestones (voting, alcohol, tobacco, Lottery)."},{id:"q-ex16-23",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Almost everybody in the UK in paid work pays National Insurance contributions. Which TWO state services and benefits does National Insurance help pay for? (Choose TWO)",options:["Local rubbish collection and council libraries","The State Retirement Pension (and contributory benefits such as maternity allowance)","BBC television channels via the TV Licence","The National Health Service (NHS)"],correctIndices:[1,3],explanation:"Money raised from National Insurance contributions pays for contributory state benefits: notably the State Pension, jobseeker/sickness/maternity support, and helps fund the National Health Service (NHS)."},{id:"q-ex16-24",examNumber:16,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO voluntary bodies give parents and local community members a formal role in setting strategic direction, accountability, and support for local state schools across the UK? (Choose TWO)",options:["Parliamentary Whips","Police and Crime Commissioners","School governors (in England, Wales, and Northern Ireland)","Parent Councils / school boards (in Scotland)"],correctIndices:[2,3],explanation:"Volunteering in local schools is a vital form of community participation: people aged 18+ can serve as school governors (raising standards, setting strategic direction, holding the headteacher to account) in England, Wales, and Northern Ireland, or join Parent Councils in Scotland."},{id:"q-ex17-01",examNumber:17,chapterId:"ch1",subtopicId:"ch1-principles",type:"multiple",prompt:"In return for respecting UK laws and shared responsibilities, which TWO fundamental freedoms does the United Kingdom offer to its residents and citizens? (Choose TWO)",options:["A right to a fair trial","Freedom from unfair discrimination","Exemption from paying Income Tax for the first five years","Guaranteed election as a Member of Parliament"],correctIndices:[0,1],explanation:"The official handbook highlights five core freedoms offered by the UK: freedom of belief and religion, freedom of speech, freedom from unfair discrimination, a right to a fair trial, and a right to join in the election of a government."},{id:"q-ex17-02",examNumber:17,chapterId:"ch1",subtopicId:"ch1-principles",type:"boolean",prompt:"Is it legal in the UK to take a girl or woman abroad for female genital mutilation (FGM) if the practice is permitted in that destination country?",options:["Yes","No"],correctIndices:[1],explanation:"No! Practising FGM in the UK OR taking a girl or woman abroad for FGM is a serious criminal offence under UK law, regardless of local customs abroad."},{id:"q-ex17-03",examNumber:17,chapterId:"ch2",subtopicId:"ch2-nations",type:"single",prompt:"Roughly what is the longest distance on the mainland from John O’Groats on the north coast of Scotland to Land’s End in the south-west corner of England?",options:["About 300 miles (480 km)","About 550 miles (885 km)","About 870 miles (1,400 km)","About 1,500 miles (2,400 km)"],correctIndices:[2],explanation:"The longest mainland distance from John O’Groats (north coast of Scotland) to Land’s End (south-west tip of Cornwall, England) is about 870 miles (approximately 1,400 km). Most parts of Britain are no more than 75 miles from the sea, and at its widest Great Britain is about 300 miles across.",memoryHook:'Countdown digits "8-7-0": about 870 miles top-to-bottom (don’t pick 300 miles, which is Great Britain’s east-to-west width).',visualId:"uk-map"},{id:"q-ex17-04",examNumber:17,chapterId:"ch2",subtopicId:"ch2-nations",type:"multiple",prompt:"Alongside the capital city Cardiff, which TWO of the following cities are located in Wales? (Choose TWO)",options:["Swansea","Aberdeen","Newport","Lisburn"],correctIndices:[0,2],explanation:"Cardiff, Swansea, and Newport (along with Wrexham, Bangor, St Davids, and St Asaph) are cities in Wales. Aberdeen is in Scotland, and Lisburn is in Northern Ireland.",memoryHook:'Visual phrase "New Swan’s Card" for the three main South Wales cities: Newport, Swansea, and Cardiff.',visualId:"uk-map"},{id:"q-ex17-05",examNumber:17,chapterId:"ch3",subtopicId:"ch3-empire-industry",type:"single",prompt:"Which monarch became queen in 1837 at the age of 18 and reigned for almost 64 years until 1901, presiding over the height of Britain’s industrial power and vast global Empire?",options:["Queen Anne","Queen Victoria","Queen Elizabeth I","Queen Mary II"],correctIndices:[1],explanation:"Queen Victoria reigned from 1837 to 1901 (almost 64 years: the Victorian Age). During her reign, the British Empire grew to cover up to 400 million people worldwide, trade boomed, and major social, railway, and public-health reforms transformed Britain.",visualId:"history-timeline"},{id:"q-ex17-06",examNumber:17,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"boolean",prompt:"True or False: During the Great Depression of the 1930s, parts of the UK suffered mass unemployment in traditional heavy industries such as shipbuilding, while new light industries including car manufacturing and aviation grew.",options:["True","False"],correctIndices:[0],explanation:"True! The 1929 global downturn led to the Great Depression of the 1930s: coal, steel, and shipbuilding regions (especially in Scotland, Wales, Northern Ireland, and northern England) suffered severe unemployment, yet falling prices meant those in work had more disposable income, fuelling house-building and new car and aviation industries in the Midlands and South."},{id:"q-ex17-07",examNumber:17,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"multiple",prompt:'During "the Blitz" in 1940–1941, German bombers mounted sustained night-time raids on British cities. Which TWO cities are specifically highlighted in the handbook for suffering massive destruction (including the near-total destruction of one city’s cathedral)? (Choose TWO)',options:["London","St Andrews","Inverness","Coventry"],correctIndices:[0,3],explanation:'After losing the daylight Battle of Britain, the Luftwaffe bombed British cities by night ("the Blitz"). London suffered massive damage (especially the East End Docks), and Coventry was almost totally destroyed in a single devastating raid in November 1940, including its medieval cathedral.'},{id:"q-ex17-08",examNumber:17,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:'Where did British, American, Canadian, and Allied forces land on 6 June 1944 ("D-Day") to open the liberation of Western Europe from Nazi occupation?',options:["The beaches of Dunkirk","The Rock of Gibraltar","The beaches of Normandy","The coast of Sicily"],correctIndices:[2],explanation:'On 6 June 1944 ("D-Day"), Allied forces landed in Normandy in northern France, winning a decisive foothold and pressing on through France and into Germany until Allied victory in Europe (VE Day) in May 1945.',memoryHook:"Don’t swap the two French beach operations: Dunkirk (1940) was the evacuation OUT; Normandy (6/6/1944) was the D-Day landing IN.",visualId:"history-timeline"},{id:"q-ex17-09",examNumber:17,chapterId:"ch3",subtopicId:"ch3-world-wars",type:"single",prompt:'Which New Zealand-born scientist working at Manchester and then Cambridge University led the team that was the first in the world to "split the atom"?',options:["Ernest Rutherford","Isaac Newton","Francis Crick","Stephen Hawking"],correctIndices:[0],explanation:'Ernest Rutherford (1871–1937), working in Britain at Manchester and Cambridge universities, led the scientists who first "split the atom" (artificial nuclear reaction): foundational physics later involved in the Manhattan Project.'},{id:"q-ex17-10",examNumber:17,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"multiple",prompt:'Following Prime Minister Harold Macmillan’s "wind of change" era, the 1960s became known as "the Swinging Sixties": a boom in British pop music (The Beatles, The Rolling Stones), fashion, and technology. Which TWO achievements belong to this era? (Choose TWO)',options:["Opening the Great Exhibition inside Hyde Park’s Crystal Palace","Fashion designer Mary Quant popularising bold new styles such as the miniskirt","Britain and France jointly developing Concorde, the world’s only commercial supersonic passenger airliner (alongside Germany in wider aerospace)","Introducing the penny black postage stamp under Rowland Hill"],correctIndices:[1,2],explanation:"The 1960s saw vibrant social and technological change: fashion icons like Mary Quant transformed style, British bands conquered the globe, social laws on divorce and abortion were liberalised, and Britain and France jointly developed Concorde (which first flew in 1969 and entered commercial passenger service in 1976)."},{id:"q-ex17-11",examNumber:17,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"After the 2010 Conservative–Liberal Democrat coalition, the 2012 London Olympics, and the June 2016 referendum vote to leave, on what date did the UK officially leave the European Union?",options:["23 June 2016","29 March 2018","31 January 2020","1 January 2022"],correctIndices:[2],explanation:"In the referendum held on 23 June 2016, the UK public voted (51.9% to 48.1%) to leave the European Union. Following parliamentary negotiations, the United Kingdom officially left the EU on 31 January 2020.",visualId:"history-timeline"},{id:"q-ex17-12",examNumber:17,chapterId:"ch3",subtopicId:"ch3-modern-britain",type:"single",prompt:"Which historic Jubilee did Queen Elizabeth II celebrate in 2022 (marking 70 years on the throne as Britain’s longest-reigning monarch) before being succeeded later that year by His Majesty King Charles III?",options:["Silver Jubilee","Golden Jubilee","Diamond Jubilee","Platinum Jubilee"],correctIndices:[3],explanation:"Queen Elizabeth II reigned from 1952 to September 2022, celebrating her Silver (1977, 25 yrs), Golden (2002, 50 yrs), Diamond (2012, 60 yrs), and unprecedented Platinum Jubilee (2022, 70 yrs). Upon her passing in September 2022, her eldest son became King Charles III."},{id:"q-ex17-13",examNumber:17,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"multiple",prompt:"Which TWO Nobel Prize-winning life-science breakthroughs involved British scientist Francis Crick (in 1953) and Scottish researcher John Macleod (in 1921), respectively? (Choose TWO)",options:["Developing radar waves to track enemy bombers","Co-discovering the double-helix structure of the DNA molecule","Inventing the hovercraft cushion-of-air skirt","Co-discovering insulin to treat diabetes"],correctIndices:[1,3],explanation:"In 1953, British biophysicist Francis Crick (working at Cambridge with James Watson, alongside Maurice Wilkins and Rosalind Franklin at King’s College London) discovered the double-helix structure of DNA. Earlier, Scottish physiologist John Macleod (1876–1935) co-discovered insulin, saving millions of lives from diabetes."},{id:"q-ex17-14",examNumber:17,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which pair of celebrated British designers are renowned for shaping sweeping 18th-century country landscapes and colourful 19th/20th-century country cottage gardens, respectively?",options:["Hans Holbein and Anthony van Dyck","Dante Gabriel Rossetti and John Everett Millais","Sir Norman Foster and Richard Rogers",'Lancelot "Capability" Brown and Gertrude Jekyll'],correctIndices:[3],explanation:'In the 18th century, Lancelot "Capability" Brown designed natural-looking grass, lake, and woodland estates around country houses (saying grounds had "great capabilities"). Later, Gertrude Jekyll (1843–1932) often collaborated with architect Edwin Lutyens to create iconic colourful country gardens. (Holbein & Van Dyck were royal portraitists; Rossetti & Millais were Pre-Raphaelites; Foster & Rogers are modern architects.)',memoryHook:'Name clue: "Capability" Brown worked with brown earth and estates (18th-century landscapes, paired with garden designer Gertrude Jekyll).'},{id:"q-ex17-15",examNumber:17,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which 19th-century duo wrote comic operas full of wit and memorable melodies: including HMS Pinafore, The Pirates of Penzance, and The Mikado, paving the way for modern musicals like Andrew Lloyd Webber’s Cats and The Phantom of the Opera?",options:["Torvill and Dean","Gilbert and Sullivan","Elgar and Vaughan Williams","Purcell and Britten"],correctIndices:[1],explanation:'Librettist W. S. Gilbert and composer Sir Arthur Sullivan wrote wildly popular Victorian comic ("Savoy") operas including HMS Pinafore, The Pirates of Penzance, and The Mikado. Later, Lord Andrew Lloyd Webber composed global musical theatre hits including Jesus Christ Superstar, Evita, Cats, and The Phantom of the Opera.'},{id:"q-ex17-16",examNumber:17,chapterId:"ch4",subtopicId:"ch4-arts-culture",type:"single",prompt:"Which major annual cultural festival in Wales celebrates literature, music, and performance largely in the Welsh language, including prestigious poetry competitions?",options:["The Edinburgh Festival Fringe","The Glastonbury Festival","The National Eisteddfod of Wales","Hogmanay"],correctIndices:[2],explanation:"The National Eisteddfod of Wales is an annual festival held each August celebrating Welsh music, literature, drama, and poetry in the Welsh language. (Glastonbury in Somerset is a famous contemporary music festival; the Edinburgh Festival Fringe is the world’s largest showcase of theatre and comedy.)"},{id:"q-ex17-17",examNumber:17,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"single",prompt:"Located on the north-east coast of Northern Ireland, what is the Giant’s Causeway famous for?",options:["Columns of interlocking volcanic basalt lava formed about 50 million years ago","A prehistoric circle of standing sandstone blocks","A Roman defensive wall stretching coast to coast","Glass domes housing tropical rainforest trees"],correctIndices:[0],explanation:"The Giant’s Causeway on the County Antrim coast of Northern Ireland is a dramatic land formation of about 40,000 interlocking hexagonal columns made from volcanic lava roughly 50 million years ago (and steeped in legend of the giant Finn MacCool).",visualId:"uk-map"},{id:"q-ex17-18",examNumber:17,chapterId:"ch4",subtopicId:"ch4-landmarks",type:"boolean",prompt:"True or False: The National Trust was founded in 1895 by three volunteers to preserve important historic buildings, coastline, and countryside across England, Wales, and Northern Ireland.",options:["True","False"],correctIndices:[0],explanation:"True! Founded in 1895 by Octavia Hill, Sir Robert Hunter, and Canon Hardwicke Rawnsley, the National Trust (alongside the separate National Trust for Scotland, founded in 1931) is a charity supported by millions of members and volunteers keeping historic houses, gardens, and coastlines open for everyone."},{id:"q-ex17-19",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:"True or False: Under the UK system of government, Cabinet ministers have the legal authority to instruct judges on how to decide individual court cases.",options:["True","False"],correctIndices:[1],explanation:"False! The judiciary (judges) is strictly independent of the government and Parliament. Judges interpret the law fairly without political interference, and can even rule that a government action is unlawful through judicial review.",visualId:"parliament-courts"},{id:"q-ex17-20",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"multiple",prompt:"Which TWO telephone numbers can be dialled free of charge from any phone in the UK to reach emergency services (police, fire, ambulance, or coastguard)? (Choose TWO)",options:["999","101","112","118"],correctIndices:[0,2],explanation:"Both 999 (the traditional UK emergency number) and 112 (the pan-European/international emergency number) work free of charge anywhere in the UK to reach emergency services immediately. (101 is for non-emergency police calls.)"},{id:"q-ex17-21",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Anyone can make a complaint about the police to the Chief Constable or to an independent oversight body. Which independent body investigates serious police complaints in England and Wales (alongside the PIRC in Scotland and the Police Ombudsman in Northern Ireland)?",options:["The Privy Council","The Electoral Commission","The National Trust","The Independent Office for Police Conduct (IOPC)"],correctIndices:[3],explanation:"Serious complaints against police conduct are handled independently by the Independent Office for Police Conduct (IOPC, successor to the IPCC) in England and Wales, the Police Investigations & Review Commissioner (PIRC) in Scotland, and the Police Ombudsman for Northern Ireland."},{id:"q-ex17-22",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"In the UK: where smoking is banned in nearly all enclosed public places and workplaces: what is the minimum legal age to buy tobacco products?",options:["16","17","18","21"],correctIndices:[2],explanation:"It is against the law across the UK to sell tobacco products (such as cigarettes, cigars, or rolling tobacco) to anyone under the age of 18, and smoking in enclosed public places, workplaces, and cars carrying under-18s is illegal."},{id:"q-ex17-23",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"boolean",prompt:'True or False: Organ donation across the UK now operates on an "opt-out" (deemed consent) system, meaning eligible adults are considered willing to donate organs after death unless they have recorded a decision to opt out.',options:["True","False"],correctIndices:[0],explanation:"True! Wales, England, Scotland, and Northern Ireland have all adopted an opt-out organ donation system (though families are still consulted and anyone can register their decision to opt in or opt out on the NHS Organ Donor Register; living volunteers can also register to donate blood)."},{id:"q-ex17-24",examNumber:17,chapterId:"ch5",subtopicId:"ch5-courts-police-role",type:"single",prompt:"Which voluntary UK programme gives 16- and 17-year-olds the chance to take part in outdoor challenges, live away from home, build life skills, and deliver a local community project?",options:["The Hansard Fellowship","The National Citizen Service (NCS)","The Shadow Cabinet Scheme","The Jurors’ Reserve Corps"],correctIndices:[1],explanation:"The National Citizen Service (NCS) is a voluntary personal and social development programme for 16- and 17-year-olds, helping young people gain confidence, outdoor teamwork skills, and hands-on experience helping their local community."}],n=[...e,...t,...i],o=17;export{n as B,o as T};
